// Generated by scripts/fetch_verses.py — 和合本 (CUV, public domain) + World English Bible (public domain)
window.BIBLE_TEXT = window.BIBLE_TEXT || {};
window.BIBLE_TEXT["john"] = {
 "1": {
  "1": {
   "zh": "太初有道，道與神同在，道就是神。",
   "en": "In the beginning was the Word, and the Word was with God, and the Word was God."
  },
  "2": {
   "zh": "這道太初與神同在。",
   "en": "The same was in the beginning with God."
  },
  "3": {
   "zh": "萬物是藉著他造的；凡被造的，沒有一樣不是藉著他造的。",
   "en": "All things were made through him. Without him was not anything made that has been made."
  },
  "4": {
   "zh": "生命在他裡頭，這生命就是人的光。",
   "en": "In him was life, and the life was the light of men."
  },
  "5": {
   "zh": "光照在黑暗裡，黑暗卻不接受光。",
   "en": "The light shines in the darkness, and the darkness hasn’t overcome it."
  },
  "6": {
   "zh": "有一個人，是從神那裡差來的，名叫約翰。",
   "en": "There came a man, sent from God, whose name was John."
  },
  "7": {
   "zh": "這人來，為要作見證，就是為光作見證，叫眾人因他可以信。",
   "en": "The same came as a witness, that he might testify about the light, that all might believe through him."
  },
  "8": {
   "zh": "他不是那光，乃是要為光作見證。",
   "en": "He was not the light, but was sent that he might testify about the light."
  },
  "9": {
   "zh": "那光是真光，照亮一切生在世上的人。",
   "en": "The true light that enlightens everyone was coming into the world."
  },
  "10": {
   "zh": "他在世界，世界也是藉著他造的，世界卻不認識他。",
   "en": "He was in the world, and the world was made through him, and the world didn’t recognize him."
  },
  "11": {
   "zh": "他到自己的地方來，自己的人倒不接待他。",
   "en": "He came to his own, and those who were his own didn’t receive him."
  },
  "12": {
   "zh": "凡接待他的，就是信他名的人，他就賜他們權柄作神的兒女。",
   "en": "But as many as received him, to them he gave the right to become God’s children, to those who believe in his name:"
  },
  "13": {
   "zh": "這等人不是從血氣生的，不是從情慾生的，也不是從人意生的，乃是從神生的。",
   "en": "who were born not of blood, nor of the will of the flesh, nor of the will of man, but of God."
  },
  "14": {
   "zh": "道成了肉身，住在我們中間，充充滿滿地有恩典有真理。我們也見過他的榮光，正是父獨生子的榮光。",
   "en": "The Word became flesh, and lived among us. We saw his glory, such glory as of the one and only Son of the Father, full of grace and truth."
  },
  "15": {
   "zh": "約翰為他作見證，喊著說：「這就是我曾說：『那在我以後來的，反成了在我以前的，因他本來在我以前。』」",
   "en": "John testified about him. He cried out, saying, “This was he of whom I said, ‘He who comes after me has surpassed me, for he was before me.’”"
  },
  "16": {
   "zh": "從他豐滿的恩典裡，我們都領受了，而且恩上加恩。",
   "en": "From his fullness we all received grace upon grace."
  },
  "17": {
   "zh": "律法本是藉著摩西傳的；恩典和真理都是由耶穌基督來的。",
   "en": "For the law was given through Moses. Grace and truth were realized through Jesus Christ."
  },
  "18": {
   "zh": "從來沒有人看見神，只有在父懷裡的獨生子將他表明出來。",
   "en": "No one has seen God at any time. The one and only Son, who is in the bosom of the Father, he has declared him."
  },
  "19": {
   "zh": "約翰所作的見證記在下面：猶太人從耶路撒冷差祭司和利未人到約翰那裡，問他說：「你是誰？」",
   "en": "This is John’s testimony, when the Jews sent priests and Levites from Jerusalem to ask him, “Who are you?”"
  },
  "20": {
   "zh": "他就明說，並不隱瞞，明說：「我不是基督。」",
   "en": "He declared, and didn’t deny, but he declared, “I am not the Christ.”"
  },
  "21": {
   "zh": "他們又問他說：「這樣，你是誰呢？是以利亞嗎？」他說：「我不是。」「是那先知嗎？」他回答說：「不是。」",
   "en": "They asked him, “What then? Are you Elijah?” He said, “I am not.” “Are you the prophet?” He answered, “No.”"
  },
  "22": {
   "zh": "於是他們說：「你到底是誰，叫我們好回覆差我們來的人。你自己說，你是誰？」",
   "en": "They said therefore to him, “Who are you? Give us an answer to take back to those who sent us. What do you say about yourself?”"
  },
  "23": {
   "zh": "他說：「我就是那在曠野有人聲喊著說：『修直主的道路』，正如先知以賽亞所說的。」",
   "en": "He said, “I am the voice of one crying in the wilderness, ‘Make straight the way of the Lord,’ as Isaiah the prophet said.”"
  },
  "24": {
   "zh": "那些人是法利賽人差來的（或譯：那差來的是法利賽人）；",
   "en": "The ones who had been sent were from the Pharisees."
  },
  "25": {
   "zh": "他們就問他說：「你既不是基督，不是以利亞，也不是那先知，為甚麼施洗呢？」",
   "en": "They asked him, “Why then do you baptize, if you are not the Christ, nor Elijah, nor the prophet?”"
  },
  "26": {
   "zh": "約翰回答說：「我是用水施洗，但有一位站在你們中間，是你們不認識的，",
   "en": "John answered them, “I baptize in water, but among you stands one whom you don’t know."
  },
  "27": {
   "zh": "就是那在我以後來的，我給他解鞋帶也不配。」",
   "en": "He is the one who comes after me, who is preferred before me, whose sandal strap I’m not worthy to loosen.”"
  },
  "28": {
   "zh": "這是在約旦河外伯大尼（有古卷：伯大巴喇），約翰施洗的地方作的見證。",
   "en": "These things were done in Bethany beyond the Jordan, where John was baptizing."
  },
  "29": {
   "zh": "次日，約翰看見耶穌來到他那裡，就說：「看哪，神的羔羊，除去（或譯：背負）世人罪孽的！",
   "en": "The next day, he saw Jesus coming to him, and said, “Behold, the Lamb of God, who takes away the sin of the world!"
  },
  "30": {
   "zh": "這就是我曾說：『有一位在我以後來、反成了在我以前的，因他本來在我以前。』",
   "en": "This is he of whom I said, ‘After me comes a man who is preferred before me, for he was before me.’"
  },
  "31": {
   "zh": "我先前不認識他，如今我來用水施洗，為要叫他顯明給以色列人。」",
   "en": "I didn’t know him, but for this reason I came baptizing in water: that he would be revealed to Israel.”"
  },
  "32": {
   "zh": "約翰又作見證說：「我曾看見聖靈，彷彿鴿子從天降下，住在他的身上。",
   "en": "John testified, saying, “I have seen the Spirit descending like a dove out of heaven, and it remained on him."
  },
  "33": {
   "zh": "我先前不認識他，只是那差我來用水施洗的、對我說：『你看見聖靈降下來，住在誰的身上，誰就是用聖靈施洗的。』",
   "en": "I didn’t recognize him, but he who sent me to baptize in water, he said to me, ‘On whomever you will see the Spirit descending, and remaining on him, the same is he who baptizes in the Holy Spirit.’"
  },
  "34": {
   "zh": "我看見了，就證明這是神的兒子。」",
   "en": "I have seen, and have testified that this is the Son of God.”"
  },
  "35": {
   "zh": "再次日，約翰同兩個門徒站在那裡。",
   "en": "Again, the next day, John was standing with two of his disciples,"
  },
  "36": {
   "zh": "他見耶穌行走，就說：「看哪，這是神的羔羊！」",
   "en": "and he looked at Jesus as he walked, and said, “Behold, the Lamb of God!”"
  },
  "37": {
   "zh": "兩個門徒聽見他的話，就跟從了耶穌。",
   "en": "The two disciples heard him speak, and they followed Jesus."
  },
  "38": {
   "zh": "耶穌轉過身來，看見他們跟著，就問他們說：「你們要甚麼？」他們說：「拉比，在哪裡住？」（拉比翻出來就是夫子。）",
   "en": "Jesus turned, and saw them following, and said to them, “What are you looking for?” They said to him, “Rabbi” (which is to say, being interpreted, Teacher), “where are you staying?”"
  },
  "39": {
   "zh": "耶穌說：「你們來看。」他們就去看他在哪裡住，這一天便與他同住；那時約有申正了。",
   "en": "He said to them, “Come, and see.” They came and saw where he was staying, and they stayed with him that day. It was about the tenth hour."
  },
  "40": {
   "zh": "聽見約翰的話跟從耶穌的那兩個人，一個是西門•彼得的兄弟安得烈。",
   "en": "One of the two who heard John, and followed him, was Andrew, Simon Peter’s brother."
  },
  "41": {
   "zh": "他先找著自己的哥哥西門，對他說：「我們遇見彌賽亞了。」（彌賽亞翻出來就是基督。）",
   "en": "He first found his own brother, Simon, and said to him, “We have found the Messiah!” (which is, being interpreted, Christ)."
  },
  "42": {
   "zh": "於是領他去見耶穌。耶穌看見他，說：「你是約翰的兒子西門（約翰在馬太十六章十七節稱約拿），你要稱為磯法。」（磯法翻出來就是彼得。）",
   "en": "He brought him to Jesus. Jesus looked at him, and said, “You are Simon the son of Jonah. You shall be called Cephas” (which is by interpretation, Peter)."
  },
  "43": {
   "zh": "又次日，耶穌想要往加利利去，遇見腓力，就對他說：「來跟從我吧。」",
   "en": "On the next day, he was determined to go out into Galilee, and he found Philip. Jesus said to him, “Follow me.”"
  },
  "44": {
   "zh": "這腓力是伯賽大人，和安得烈、彼得同城。",
   "en": "Now Philip was from Bethsaida, of the city of Andrew and Peter."
  },
  "45": {
   "zh": "腓力找著拿但業，對他說：「摩西在律法上所寫的和眾先知所記的那一位，我們遇見了，就是約瑟的兒子拿撒勒人耶穌。」",
   "en": "Philip found Nathanael, and said to him, “We have found him, of whom Moses in the law, and the prophets, wrote: Jesus of Nazareth, the son of Joseph.”"
  },
  "46": {
   "zh": "拿但業對他說：「拿撒勒還能出甚麼好的嗎？」腓力說：「你來看！」",
   "en": "Nathanael said to him, “Can any good thing come out of Nazareth?” Philip said to him, “Come and see.”"
  },
  "47": {
   "zh": "耶穌看見拿但業來，就指著他說：「看哪，這是個真以色列人，他心裡是沒有詭詐的。」",
   "en": "Jesus saw Nathanael coming to him, and said about him, “Behold, an Israelite indeed, in whom is no deceit!”"
  },
  "48": {
   "zh": "拿但業對耶穌說：「你從哪裡知道我呢？」耶穌回答說：「腓力還沒有招呼你，你在無花果樹底下，我就看見你了。」",
   "en": "Nathanael said to him, “How do you know me?” Jesus answered him, “Before Philip called you, when you were under the fig tree, I saw you.”"
  },
  "49": {
   "zh": "拿但業說：「拉比，你是神的兒子，你是以色列的王！」",
   "en": "Nathanael answered him, “Rabbi, you are the Son of God! You are King of Israel!”"
  },
  "50": {
   "zh": "耶穌對他說：「因為我說『在無花果樹底下看見你』，你就信嗎？你將要看見比這更大的事」；",
   "en": "Jesus answered him, “Because I told you, ‘I saw you underneath the fig tree,’ do you believe? You will see greater things than these!”"
  },
  "51": {
   "zh": "又說：「我實實在在地告訴你們，你們將要看見天開了，神的使者上去下來在人子身上。」",
   "en": "He said to him, “Most certainly, I tell you all, hereafter you will see heaven opened, and the angels of God ascending and descending on the Son of Man.”"
  }
 },
 "2": {
  "1": {
   "zh": "第三日，在加利利的迦拿有娶親的筵席，耶穌的母親在那裡。",
   "en": "The third day, there was a marriage in Cana of Galilee. Jesus’ mother was there."
  },
  "2": {
   "zh": "耶穌和他的門徒也被請去赴席。",
   "en": "Jesus also was invited, with his disciples, to the marriage."
  },
  "3": {
   "zh": "酒用盡了，耶穌的母親對他說：「他們沒有酒了。」",
   "en": "When the wine ran out, Jesus’ mother said to him, “They have no wine.”"
  },
  "4": {
   "zh": "耶穌說：「母親（原文是婦人），我與你有甚麼相干？我的時候還沒有到。」",
   "en": "Jesus said to her, “Woman, what does that have to do with you and me? My hour has not yet come.”"
  },
  "5": {
   "zh": "他母親對用人說：「他告訴你們甚麼，你們就做甚麼。」",
   "en": "His mother said to the servants, “Whatever he says to you, do it.”"
  },
  "6": {
   "zh": "照猶太人潔淨的規矩，有六口石缸擺在那裡，每口可以盛兩三桶水。",
   "en": "Now there were six water pots of stone set there after the Jews’ way of purifying, containing two or three metretes apiece."
  },
  "7": {
   "zh": "耶穌對用人說：「把缸倒滿了水。」他們就倒滿了，直到缸口。",
   "en": "Jesus said to them, “Fill the water pots with water.” They filled them up to the brim."
  },
  "8": {
   "zh": "耶穌又說：「現在可以舀出來，送給管筵席的。」他們就送了去。",
   "en": "He said to them, “Now draw some out, and take it to the ruler of the feast.” So they took it."
  },
  "9": {
   "zh": "管筵席的嘗了那水變的酒，並不知道是哪裡來的，只有舀水的用人知道。管筵席的便叫新郎來，",
   "en": "When the ruler of the feast tasted the water now become wine, and didn’t know where it came from (but the servants who had drawn the water knew), the ruler of the feast called the bridegroom,"
  },
  "10": {
   "zh": "對他說：「人都是先擺上好酒，等客喝足了，才擺上次的，你倒把好酒留到如今！」",
   "en": "and said to him, “Everyone serves the good wine first, and when the guests have drunk freely, then that which is worse. You have kept the good wine until now!”"
  },
  "11": {
   "zh": "這是耶穌所行的頭一件神蹟，是在加利利的迦拿行的，顯出他的榮耀來；他的門徒就信他了。",
   "en": "This beginning of his signs Jesus did in Cana of Galilee, and revealed his glory; and his disciples believed in him."
  },
  "12": {
   "zh": "這事以後，耶穌與他的母親、弟兄，和門徒都下迦百農去，在那裡住了不多幾日。",
   "en": "After this, he went down to Capernaum, he, and his mother, his brothers, and his disciples; and they stayed there a few days."
  },
  "13": {
   "zh": "猶太人的逾越節近了，耶穌就上耶路撒冷去。",
   "en": "The Passover of the Jews was at hand, and Jesus went up to Jerusalem."
  },
  "14": {
   "zh": "看見殿裡有賣牛、羊、鴿子的，並有兌換銀錢的人坐在那裡，",
   "en": "He found in the temple those who sold oxen, sheep, and doves, and the changers of money sitting."
  },
  "15": {
   "zh": "耶穌就拿繩子做成鞭子，把牛羊都趕出殿去，倒出兌換銀錢之人的銀錢，推翻他們的桌子，",
   "en": "He made a whip of cords, and threw all out of the temple, both the sheep and the oxen; and he poured out the changers’ money, and overthrew their tables."
  },
  "16": {
   "zh": "又對賣鴿子的說：「把這些東西拿去！不要將我父的殿當作買賣的地方。」",
   "en": "To those who sold the doves, he said, “Take these things out of here! Don’t make my Father’s house a marketplace!”"
  },
  "17": {
   "zh": "他的門徒就想起經上記著說：「我為你的殿心裡焦急，如同火燒。」",
   "en": "His disciples remembered that it was written, “Zeal for your house will eat me up.”"
  },
  "18": {
   "zh": "因此猶太人問他說：「你既做這些事，還顯甚麼神蹟給我們看呢？」",
   "en": "The Jews therefore answered him, “What sign do you show us, seeing that you do these things?”"
  },
  "19": {
   "zh": "耶穌回答說：「你們拆毀這殿，我三日內要再建立起來。」",
   "en": "Jesus answered them, “Destroy this temple, and in three days I will raise it up.”"
  },
  "20": {
   "zh": "猶太人便說：「這殿是四十六年才造成的，你三日內就再建立起來嗎？」",
   "en": "The Jews therefore said, “It took forty-six years to build this temple! Will you raise it up in three days?”"
  },
  "21": {
   "zh": "但耶穌這話是以他的身體為殿。",
   "en": "But he spoke of the temple of his body."
  },
  "22": {
   "zh": "所以到他從死裡復活以後，門徒就想起他說過這話，便信了聖經和耶穌所說的。",
   "en": "When therefore he was raised from the dead, his disciples remembered that he said this, and they believed the Scripture, and the word which Jesus had said."
  },
  "23": {
   "zh": "當耶穌在耶路撒冷過逾越節的時候，有許多人看見他所行的神蹟，就信了他的名。",
   "en": "Now when he was in Jerusalem at the Passover, during the feast, many believed in his name, observing his signs which he did."
  },
  "24": {
   "zh": "耶穌卻不將自己交託他們；因為他知道萬人，",
   "en": "But Jesus didn’t entrust himself to them, because he knew everyone,"
  },
  "25": {
   "zh": "也用不著誰見證人怎樣，因他知道人心裡所存的。",
   "en": "and because he didn’t need for anyone to testify concerning man; for he himself knew what was in man."
  }
 },
 "3": {
  "1": {
   "zh": "有一個法利賽人，名叫尼哥底母，是猶太人的官。",
   "en": "Now there was a man of the Pharisees named Nicodemus, a ruler of the Jews."
  },
  "2": {
   "zh": "這人夜裡來見耶穌，說：「拉比，我們知道你是由神那裡來作師傅的；因為你所行的神蹟，若沒有神同在，無人能行。」",
   "en": "The same came to him by night, and said to him, “Rabbi, we know that you are a teacher come from God, for no one can do these signs that you do, unless God is with him.”"
  },
  "3": {
   "zh": "耶穌回答說：「我實實在在地告訴你，人若不重生，就不能見神的國。」",
   "en": "Jesus answered him, “Most certainly, I tell you, unless one is born anew, he can’t see God’s Kingdom.”"
  },
  "4": {
   "zh": "尼哥底母說：「人已經老了，如何能重生呢？豈能再進母腹生出來嗎？」",
   "en": "Nicodemus said to him, “How can a man be born when he is old? Can he enter a second time into his mother’s womb, and be born?”"
  },
  "5": {
   "zh": "耶穌說：「我實實在在地告訴你，人若不是從水和聖靈生的，就不能進神的國。",
   "en": "Jesus answered, “Most certainly I tell you, unless one is born of water and spirit, he can’t enter into God’s Kingdom."
  },
  "6": {
   "zh": "從肉身生的就是肉身；從靈生的就是靈。",
   "en": "That which is born of the flesh is flesh. That which is born of the Spirit is spirit."
  },
  "7": {
   "zh": "我說：『你們必須重生』，你不要以為希奇。",
   "en": "Don’t marvel that I said to you, ‘You must be born anew.’"
  },
  "8": {
   "zh": "風隨著意思吹，你聽見風的響聲，卻不曉得從哪裡來，往哪裡去；凡從聖靈生的，也是如此。」",
   "en": "The wind blows where it wants to, and you hear its sound, but don’t know where it comes from and where it is going. So is everyone who is born of the Spirit.”"
  },
  "9": {
   "zh": "尼哥底母問他說：「怎能有這事呢？」",
   "en": "Nicodemus answered him, “How can these things be?”"
  },
  "10": {
   "zh": "耶穌回答說：「你是以色列人的先生，還不明白這事嗎？",
   "en": "Jesus answered him, “Are you the teacher of Israel, and don’t understand these things?"
  },
  "11": {
   "zh": "我實實在在地告訴你，我們所說的是我們知道的；我們所見證的是我們見過的；你們卻不領受我們的見證。",
   "en": "Most certainly I tell you, we speak that which we know, and testify of that which we have seen, and you don’t receive our witness."
  },
  "12": {
   "zh": "我對你們說地上的事，你們尚且不信，若說天上的事，如何能信呢？",
   "en": "If I told you earthly things and you don’t believe, how will you believe if I tell you heavenly things?"
  },
  "13": {
   "zh": "除了從天降下、仍舊在天的人子，沒有人升過天。",
   "en": "No one has ascended into heaven, but he who descended out of heaven, the Son of Man, who is in heaven."
  },
  "14": {
   "zh": "摩西在曠野怎樣舉蛇，人子也必照樣被舉起來，",
   "en": "As Moses lifted up the serpent in the wilderness, even so must the Son of Man be lifted up,"
  },
  "15": {
   "zh": "叫一切信他的都得永生（或譯：叫一切信的人在他裡面得永生）。",
   "en": "that whoever believes in him should not perish, but have eternal life."
  },
  "16": {
   "zh": "「神愛世人，甚至將他的獨生子賜給他們，叫一切信他的，不致滅亡，反得永生。",
   "en": "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life."
  },
  "17": {
   "zh": "因為神差他的兒子降世，不是要定世人的罪（或譯：審判世人；下同），乃是要叫世人因他得救。",
   "en": "For God didn’t send his Son into the world to judge the world, but that the world should be saved through him."
  },
  "18": {
   "zh": "信他的人，不被定罪；不信的人，罪已經定了，因為他不信神獨生子的名。",
   "en": "He who believes in him is not judged. He who doesn’t believe has been judged already, because he has not believed in the name of the one and only Son of God."
  },
  "19": {
   "zh": "光來到世間，世人因自己的行為是惡的，不愛光，倒愛黑暗，定他們的罪就是在此。",
   "en": "This is the judgment, that the light has come into the world, and men loved the darkness rather than the light; for their works were evil."
  },
  "20": {
   "zh": "凡作惡的便恨光，並不來就光，恐怕他的行為受責備。",
   "en": "For everyone who does evil hates the light, and doesn’t come to the light, lest his works would be exposed."
  },
  "21": {
   "zh": "但行真理的必來就光，要顯明他所行的是靠神而行。」",
   "en": "But he who does the truth comes to the light, that his works may be revealed, that they have been done in God.”"
  },
  "22": {
   "zh": "這事以後，耶穌和門徒到了猶太地，在那裡居住，施洗。",
   "en": "After these things, Jesus came with his disciples into the land of Judea. He stayed there with them, and baptized."
  },
  "23": {
   "zh": "約翰在靠近撒冷的哀嫩也施洗；因為那裡水多，眾人都去受洗。",
   "en": "John also was baptizing in Enon near Salim, because there was much water there. They came, and were baptized."
  },
  "24": {
   "zh": "（那時約翰還沒有下在監裡。）",
   "en": "For John was not yet thrown into prison."
  },
  "25": {
   "zh": "約翰的門徒和一個猶太人辯論潔淨的禮，",
   "en": "There arose therefore a questioning on the part of John’s disciples with some Jews about purification."
  },
  "26": {
   "zh": "就來見約翰，說：「拉比，從前同你在約旦河外、你所見證的那位，現在施洗，眾人都往他那裡去了。」",
   "en": "They came to John, and said to him, “Rabbi, he who was with you beyond the Jordan, to whom you have testified, behold, the same baptizes, and everyone is coming to him.”"
  },
  "27": {
   "zh": "約翰說：「若不是從天上賜的，人就不能得甚麼。",
   "en": "John answered, “A man can receive nothing, unless it has been given him from heaven."
  },
  "28": {
   "zh": "我曾說：『我不是基督，是奉差遣在他前面的』，你們自己可以給我作見證。",
   "en": "You yourselves testify that I said, ‘I am not the Christ,’ but, ‘I have been sent before him.’"
  },
  "29": {
   "zh": "娶新婦的就是新郎；新郎的朋友站著，聽見新郎的聲音就甚喜樂。故此，我這喜樂滿足了。",
   "en": "He who has the bride is the bridegroom; but the friend of the bridegroom, who stands and hears him, rejoices greatly because of the bridegroom’s voice. This, my joy, therefore is made full."
  },
  "30": {
   "zh": "他必興旺，我必衰微。」",
   "en": "He must increase, but I must decrease."
  },
  "31": {
   "zh": "「從天上來的是在萬有之上；從地上來的是屬乎地，他所說的也是屬乎地。從天上來的是在萬有之上。",
   "en": "He who comes from above is above all. He who is from the earth belongs to the earth, and speaks of the earth. He who comes from heaven is above all."
  },
  "32": {
   "zh": "他將所見所聞的見證出來，只是沒有人領受他的見證。",
   "en": "What he has seen and heard, of that he testifies; and no one receives his witness."
  },
  "33": {
   "zh": "那領受他見證的，就印上印，證明神是真的。",
   "en": "He who has received his witness has set his seal to this, that God is true."
  },
  "34": {
   "zh": "神所差來的就說神的話，因為神賜聖靈給他是沒有限量的。",
   "en": "For he whom God has sent speaks the words of God; for God gives the Spirit without measure."
  },
  "35": {
   "zh": "父愛子，已將萬有交在他手裡。",
   "en": "The Father loves the Son, and has given all things into his hand."
  },
  "36": {
   "zh": "信子的人有永生；不信子的人得不著永生（原文是不得見永生），神的震怒常在他身上。」",
   "en": "One who believes in the Son has eternal life, but one who disobeys the Son won’t see life, but the wrath of God remains on him.”"
  }
 },
 "4": {
  "1": {
   "zh": "主知道法利賽人聽見他收門徒，施洗，比約翰還多，",
   "en": "Therefore when the Lord knew that the Pharisees had heard that Jesus was making and baptizing more disciples than John"
  },
  "2": {
   "zh": "（其實不是耶穌親自施洗，乃是他的門徒施洗，）",
   "en": "(although Jesus himself didn’t baptize, but his disciples),"
  },
  "3": {
   "zh": "他就離了猶太，又往加利利去。",
   "en": "he left Judea, and departed into Galilee."
  },
  "4": {
   "zh": "必須經過撒馬利亞，",
   "en": "He needed to pass through Samaria."
  },
  "5": {
   "zh": "於是到了撒馬利亞的一座城，名叫敘加，靠近雅各給他兒子約瑟的那塊地。",
   "en": "So he came to a city of Samaria, called Sychar, near the parcel of ground that Jacob gave to his son, Joseph."
  },
  "6": {
   "zh": "在那裡有雅各井；耶穌因走路困乏，就坐在井旁。那時約有午正。",
   "en": "Jacob’s well was there. Jesus therefore, being tired from his journey, sat down by the well. It was about the sixth hour."
  },
  "7": {
   "zh": "有一個撒馬利亞的婦人來打水。耶穌對她說：「請你給我水喝。」",
   "en": "A woman of Samaria came to draw water. Jesus said to her, “Give me a drink.”"
  },
  "8": {
   "zh": "（那時門徒進城買食物去了。）",
   "en": "For his disciples had gone away into the city to buy food."
  },
  "9": {
   "zh": "撒馬利亞的婦人對他說：「你既是猶太人，怎麼向我一個撒馬利亞婦人要水喝呢？」原來猶太人和撒馬利亞人沒有來往。",
   "en": "The Samaritan woman therefore said to him, “How is it that you, being a Jew, ask for a drink from me, a Samaritan woman?” (For Jews have no dealings with Samaritans.)"
  },
  "10": {
   "zh": "耶穌回答說：「你若知道神的恩賜，和對你說『給我水喝』的是誰，你必早求他，他也必早給了你活水。」",
   "en": "Jesus answered her, “If you knew the gift of God, and who it is who says to you, ‘Give me a drink,’ you would have asked him, and he would have given you living water.”"
  },
  "11": {
   "zh": "婦人說：「先生，沒有打水的器具，井又深，你從哪裡得活水呢？",
   "en": "The woman said to him, “Sir, you have nothing to draw with, and the well is deep. So where do you get that living water?"
  },
  "12": {
   "zh": "我們的祖宗雅各將這井留給我們，他自己和兒子並牲畜也都喝這井裡的水，難道你比他還大嗎？」",
   "en": "Are you greater than our father, Jacob, who gave us the well, and drank of it himself, as did his children, and his livestock?”"
  },
  "13": {
   "zh": "耶穌回答說：「凡喝這水的還要再渴；",
   "en": "Jesus answered her, “Everyone who drinks of this water will thirst again,"
  },
  "14": {
   "zh": "人若喝我所賜的水就永遠不渴。我所賜的水要在他裡頭成為泉源，直湧到永生。」",
   "en": "but whoever drinks of the water that I will give him will never thirst again; but the water that I will give him will become in him a well of water springing up to eternal life.”"
  },
  "15": {
   "zh": "婦人說：「先生，請把這水賜給我，叫我不渴，也不用來這麼遠打水。」",
   "en": "The woman said to him, “Sir, give me this water, so that I don’t get thirsty, neither come all the way here to draw.”"
  },
  "16": {
   "zh": "耶穌說：「你去叫你丈夫也到這裡來。」",
   "en": "Jesus said to her, “Go, call your husband, and come here.”"
  },
  "17": {
   "zh": "婦人說：「我沒有丈夫。」耶穌說：「你說沒有丈夫是不錯的。",
   "en": "The woman answered, “I have no husband.” Jesus said to her, “You said well, ‘I have no husband,’"
  },
  "18": {
   "zh": "你已經有五個丈夫，你現在有的並不是你的丈夫。你這話是真的。」",
   "en": "for you have had five husbands; and he whom you now have is not your husband. This you have said truly.”"
  },
  "19": {
   "zh": "婦人說：「先生，我看出你是先知。",
   "en": "The woman said to him, “Sir, I perceive that you are a prophet."
  },
  "20": {
   "zh": "我們的祖宗在這山上禮拜，你們倒說，應當禮拜的地方是在耶路撒冷。」",
   "en": "Our fathers worshiped in this mountain, and you Jews say that in Jerusalem is the place where people ought to worship.”"
  },
  "21": {
   "zh": "耶穌說：「婦人，你當信我。時候將到，你們拜父，也不在這山上，也不在耶路撒冷。",
   "en": "Jesus said to her, “Woman, believe me, the hour comes, when neither in this mountain, nor in Jerusalem, will you worship the Father."
  },
  "22": {
   "zh": "你們所拜的，你們不知道；我們所拜的，我們知道，因為救恩是從猶太人出來的。",
   "en": "You worship that which you don’t know. We worship that which we know; for salvation is from the Jews."
  },
  "23": {
   "zh": "時候將到，如今就是了，那真正拜父的，要用心靈和誠實拜他，因為父要這樣的人拜他。",
   "en": "But the hour comes, and now is, when the true worshipers will worship the Father in spirit and truth, for the Father seeks such to be his worshipers."
  },
  "24": {
   "zh": "神是個靈（或無個字），所以拜他的必須用心靈和誠實拜他。」",
   "en": "God is spirit, and those who worship him must worship in spirit and truth.”"
  },
  "25": {
   "zh": "婦人說：「我知道彌賽亞（就是那稱為基督的）要來；他來了，必將一切的事都告訴我們。」",
   "en": "The woman said to him, “I know that Messiah comes, he who is called Christ. When he has come, he will declare to us all things.”"
  },
  "26": {
   "zh": "耶穌說：「這和你說話的就是他！」",
   "en": "Jesus said to her, “I am he, the one who speaks to you.”"
  },
  "27": {
   "zh": "當下門徒回來，就希奇耶穌和一個婦人說話；只是沒有人說：「你是要甚麼？」或說：「你為甚麼和她說話？」",
   "en": "At this, his disciples came. They marveled that he was speaking with a woman; yet no one said, “What are you looking for?” or, “Why do you speak with her?”"
  },
  "28": {
   "zh": "那婦人就留下水罐子，往城裡去，對眾人說：",
   "en": "So the woman left her water pot, and went away into the city, and said to the people,"
  },
  "29": {
   "zh": "「你們來看！有一個人將我素來所行的一切事都給我說出來了，莫非這就是基督嗎？」",
   "en": "“Come, see a man who told me everything that I did. Can this be the Christ?”"
  },
  "30": {
   "zh": "眾人就出城，往耶穌那裡去。",
   "en": "They went out of the city, and were coming to him."
  },
  "31": {
   "zh": "這其間，門徒對耶穌說：「拉比，請吃。」",
   "en": "In the meanwhile, the disciples urged him, saying, “Rabbi, eat.”"
  },
  "32": {
   "zh": "耶穌說：「我有食物吃，是你們不知道的。」",
   "en": "But he said to them, “I have food to eat that you don’t know about.”"
  },
  "33": {
   "zh": "門徒就彼此對問說：「莫非有人拿甚麼給他吃嗎？」",
   "en": "The disciples therefore said to one another, “Has anyone brought him something to eat?”"
  },
  "34": {
   "zh": "耶穌說：「我的食物就是遵行差我來者的旨意，做成他的工。",
   "en": "Jesus said to them, “My food is to do the will of him who sent me, and to accomplish his work."
  },
  "35": {
   "zh": "你們豈不說『到收割的時候還有四個月』嗎？我告訴你們，舉目向田觀看，莊稼已經熟了（原文是發白），可以收割了。",
   "en": "Don’t you say, ‘There are yet four months until the harvest?’ Behold, I tell you, lift up your eyes, and look at the fields, that they are white for harvest already."
  },
  "36": {
   "zh": "收割的人得工價，積蓄五穀到永生，叫撒種的和收割的一同快樂。",
   "en": "He who reaps receives wages, and gathers fruit to eternal life; that both he who sows and he who reaps may rejoice together."
  },
  "37": {
   "zh": "俗語說：『那人撒種，這人收割』，這話可見是真的。",
   "en": "For in this the saying is true, ‘One sows, and another reaps.’"
  },
  "38": {
   "zh": "我差你們去收你們所沒有勞苦的；別人勞苦，你們享受他們所勞苦的。」",
   "en": "I sent you to reap that for which you haven’t labored. Others have labored, and you have entered into their labor.”"
  },
  "39": {
   "zh": "那城裡有好些撒馬利亞人信了耶穌，因為那婦人作見證說：「他將我素來所行的一切事都給我說出來了。」",
   "en": "From that city many of the Samaritans believed in him because of the word of the woman, who testified, “He told me everything that I did.”"
  },
  "40": {
   "zh": "於是撒馬利亞人來見耶穌，求他在他們那裡住下，他便在那裡住了兩天。",
   "en": "So when the Samaritans came to him, they begged him to stay with them. He stayed there two days."
  },
  "41": {
   "zh": "因耶穌的話，信的人就更多了，",
   "en": "Many more believed because of his word."
  },
  "42": {
   "zh": "便對婦人說：「現在我們信，不是因為你的話，是我們親自聽見了，知道這真是救世主。」",
   "en": "They said to the woman, “Now we believe, not because of your speaking; for we have heard for ourselves, and know that this is indeed the Christ, the Savior of the world.”"
  },
  "43": {
   "zh": "過了那兩天，耶穌離了那地方，往加利利去。",
   "en": "After the two days he went out from there and went into Galilee."
  },
  "44": {
   "zh": "因為耶穌自己作過見證說：「先知在本地是沒有人尊敬的。」",
   "en": "For Jesus himself testified that a prophet has no honor in his own country."
  },
  "45": {
   "zh": "到了加利利，加利利人既然看見他在耶路撒冷過節所行的一切事，就接待他，因為他們也是上去過節。",
   "en": "So when he came into Galilee, the Galileans received him, having seen all the things that he did in Jerusalem at the feast, for they also went to the feast."
  },
  "46": {
   "zh": "耶穌又到了加利利的迦拿，就是他從前變水為酒的地方。有一個大臣，他的兒子在迦百農患病。",
   "en": "Jesus came therefore again to Cana of Galilee, where he made the water into wine. There was a certain nobleman whose son was sick at Capernaum."
  },
  "47": {
   "zh": "他聽見耶穌從猶太到了加利利，就來見他，求他下去醫治他的兒子，因為他兒子快要死了。",
   "en": "When he heard that Jesus had come out of Judea into Galilee, he went to him, and begged him that he would come down and heal his son, for he was at the point of death."
  },
  "48": {
   "zh": "耶穌就對他說：「若不看見神蹟奇事，你們總是不信。」",
   "en": "Jesus therefore said to him, “Unless you see signs and wonders, you will in no way believe.”"
  },
  "49": {
   "zh": "那大臣說：「先生，求你趁著我的孩子還沒有死就下去。」",
   "en": "The nobleman said to him, “Sir, come down before my child dies.”"
  },
  "50": {
   "zh": "耶穌對他說：「回去吧，你的兒子活了！」那人信耶穌所說的話就回去了。",
   "en": "Jesus said to him, “Go your way. Your son lives.” The man believed the word that Jesus spoke to him, and he went his way."
  },
  "51": {
   "zh": "正下去的時候，他的僕人迎見他，說他的兒子活了。",
   "en": "As he was now going down, his servants met him and reported, saying “Your child lives!”"
  },
  "52": {
   "zh": "他就問甚麼時候見好的。他們說：「昨日未時熱就退了。」",
   "en": "So he inquired of them the hour when he began to get better. They said therefore to him, “Yesterday at the seventh hour, the fever left him.”"
  },
  "53": {
   "zh": "他便知道這正是耶穌對他說「你兒子活了」的時候；他自己和全家就都信了。",
   "en": "So the father knew that it was at that hour in which Jesus said to him, “Your son lives.” He believed, as did his whole house."
  },
  "54": {
   "zh": "這是耶穌在加利利行的第二件神蹟，是他從猶太回去以後行的。",
   "en": "This is again the second sign that Jesus did, having come out of Judea into Galilee."
  }
 },
 "5": {
  "1": {
   "zh": "這事以後，到了猶太人的一個節期，耶穌就上耶路撒冷去。",
   "en": "After these things, there was a feast of the Jews, and Jesus went up to Jerusalem."
  },
  "2": {
   "zh": "在耶路撒冷，靠近羊門有一個池子，希伯來話叫作畢士大，旁邊有五個廊子；",
   "en": "Now in Jerusalem by the sheep gate, there is a pool, which is called in Hebrew, “Bethesda”, having five porches."
  },
  "3": {
   "zh": "裡面躺著瞎眼的、瘸腿的、血氣枯乾的許多病人。（有古卷加：等候水動；",
   "en": "In these lay a great multitude of those who were sick, blind, lame, or paralyzed, waiting for the moving of the water;"
  },
  "4": {
   "zh": "因為有天使按時下池子攪動那水，水動之後，誰先下去，無論害甚麼病就痊癒了。）",
   "en": "for an angel went down at certain times into the pool, and stirred up the water. Whoever stepped in first after the stirring of the water was healed of whatever disease he had."
  },
  "5": {
   "zh": "在那裡有一個人，病了三十八年。",
   "en": "A certain man was there, who had been sick for thirty-eight years."
  },
  "6": {
   "zh": "耶穌看見他躺著，知道他病了許久，就問他說：「你要痊癒嗎？」",
   "en": "When Jesus saw him lying there, and knew that he had been sick for a long time, he asked him, “Do you want to be made well?”"
  },
  "7": {
   "zh": "病人回答說：「先生，水動的時候，沒有人把我放在池子裡；我正去的時候，就有別人比我先下去。」",
   "en": "The sick man answered him, “Sir, I have no one to put me into the pool when the water is stirred up, but while I’m coming, another steps down before me.”"
  },
  "8": {
   "zh": "耶穌對他說：「起來，拿你的褥子走吧！」",
   "en": "Jesus said to him, “Arise, take up your mat, and walk.”"
  },
  "9": {
   "zh": "那人立刻痊癒，就拿起褥子來走了。",
   "en": "Immediately, the man was made well, and took up his mat and walked. Now it was the Sabbath on that day."
  },
  "10": {
   "zh": "那天是安息日，所以猶太人對那醫好的人說：「今天是安息日，你拿褥子是不可的。」",
   "en": "So the Jews said to him who was cured, “It is the Sabbath. It is not lawful for you to carry the mat.”"
  },
  "11": {
   "zh": "他卻回答說：「那使我痊癒的，對我說：『拿你的褥子走吧。』」",
   "en": "He answered them, “He who made me well, the same said to me, ‘Take up your mat, and walk.’”"
  },
  "12": {
   "zh": "他們問他說：「對你說『拿褥子走』的是甚麼人？」",
   "en": "Then they asked him, “Who is the man who said to you, ‘Take up your mat, and walk’?”"
  },
  "13": {
   "zh": "那醫好的人不知道是誰；因為那裡的人多，耶穌已經躲開了。",
   "en": "But he who was healed didn’t know who it was, for Jesus had withdrawn, a crowd being in the place."
  },
  "14": {
   "zh": "後來耶穌在殿裡遇見他，對他說：「你已經痊癒了，不要再犯罪，恐怕你遭遇的更加利害。」",
   "en": "Afterward Jesus found him in the temple, and said to him, “Behold, you are made well. Sin no more, so that nothing worse happens to you.”"
  },
  "15": {
   "zh": "那人就去告訴猶太人，使他痊癒的是耶穌。",
   "en": "The man went away, and told the Jews that it was Jesus who had made him well."
  },
  "16": {
   "zh": "所以猶太人逼迫耶穌，因為他在安息日做了這事。",
   "en": "For this cause the Jews persecuted Jesus, and sought to kill him, because he did these things on the Sabbath."
  },
  "17": {
   "zh": "耶穌就對他們說：「我父做事直到如今，我也做事。」",
   "en": "But Jesus answered them, “My Father is still working, so I am working, too.”"
  },
  "18": {
   "zh": "所以猶太人越發想要殺他；因他不但犯了安息日，並且稱神為他的父，將自己和神當作平等。",
   "en": "For this cause therefore the Jews sought all the more to kill him, because he not only broke the Sabbath, but also called God his own Father, making himself equal with God."
  },
  "19": {
   "zh": "耶穌對他們說：「我實實在在地告訴你們，子憑著自己不能做甚麼，惟有看見父所做的，子才能做；父所做的事，子也照樣做。",
   "en": "Jesus therefore answered them, “Most certainly, I tell you, the Son can do nothing of himself, but what he sees the Father doing. For whatever things he does, these the Son also does likewise."
  },
  "20": {
   "zh": "父愛子，將自己所做的一切事指給他看，還要將比這更大的事指給他看，叫你們希奇。",
   "en": "For the Father has affection for the Son, and shows him all things that he himself does. He will show him greater works than these, that you may marvel."
  },
  "21": {
   "zh": "父怎樣叫死人起來，使他們活著，子也照樣隨自己的意思使人活著。",
   "en": "For as the Father raises the dead and gives them life, even so the Son also gives life to whom he desires."
  },
  "22": {
   "zh": "父不審判甚麼人，乃將審判的事全交與子，",
   "en": "For the Father judges no one, but he has given all judgment to the Son,"
  },
  "23": {
   "zh": "叫人都尊敬子如同尊敬父一樣。不尊敬子的，就是不尊敬差子來的父。",
   "en": "that all may honor the Son, even as they honor the Father. He who doesn’t honor the Son doesn’t honor the Father who sent him."
  },
  "24": {
   "zh": "我實實在在地告訴你們，那聽我話、又信差我來者的，就有永生；不至於定罪，是已經出死入生了。",
   "en": "“Most certainly I tell you, he who hears my word, and believes him who sent me, has eternal life, and doesn’t come into judgment, but has passed out of death into life."
  },
  "25": {
   "zh": "我實實在在地告訴你們，時候將到，現在就是了，死人要聽見神兒子的聲音，聽見的人就要活了。",
   "en": "Most certainly, I tell you, the hour comes, and now is, when the dead will hear the Son of God’s voice; and those who hear will live."
  },
  "26": {
   "zh": "因為父怎樣在自己有生命，就賜給他兒子也照樣在自己有生命，",
   "en": "For as the Father has life in himself, even so he gave to the Son also to have life in himself."
  },
  "27": {
   "zh": "並且因為他是人子，就賜給他行審判的權柄。",
   "en": "He also gave him authority to execute judgment, because he is a son of man."
  },
  "28": {
   "zh": "你們不要把這事看作希奇。時候要到，凡在墳墓裡的，都要聽見他的聲音，就出來：",
   "en": "Don’t marvel at this, for the hour comes, in which all that are in the tombs will hear his voice,"
  },
  "29": {
   "zh": "行善的，復活得生；作惡的，復活定罪。",
   "en": "and will come out; those who have done good, to the resurrection of life; and those who have done evil, to the resurrection of judgment."
  },
  "30": {
   "zh": "「我憑著自己不能做甚麼，我怎麼聽見就怎麼審判。我的審判也是公平的；因為我不求自己的意思，只求那差我來者的意思。」",
   "en": "I can of myself do nothing. As I hear, I judge, and my judgment is righteous; because I don’t seek my own will, but the will of my Father who sent me."
  },
  "31": {
   "zh": "「我若為自己作見證，我的見證就不真。",
   "en": "“If I testify about myself, my witness is not valid."
  },
  "32": {
   "zh": "另有一位給我作見證，我也知道他給我作的見證是真的。",
   "en": "It is another who testifies about me. I know that the testimony which he testifies about me is true."
  },
  "33": {
   "zh": "你們曾差人到約翰那裡，他為真理作過見證。",
   "en": "You have sent to John, and he has testified to the truth."
  },
  "34": {
   "zh": "其實，我所受的見證不是從人來的；然而，我說這些話，為要叫你們得救。",
   "en": "But the testimony which I receive is not from man. However, I say these things that you may be saved."
  },
  "35": {
   "zh": "約翰是點著的明燈，你們情願暫時喜歡他的光。",
   "en": "He was the burning and shining lamp, and you were willing to rejoice for a while in his light."
  },
  "36": {
   "zh": "但我有比約翰更大的見證；因為父交給我要我成就的事，就是我所做的事，這便見證我是父所差來的。",
   "en": "But the testimony which I have is greater than that of John, for the works which the Father gave me to accomplish, the very works that I do, testify about me, that the Father has sent me."
  },
  "37": {
   "zh": "差我來的父也為我作過見證。你們從來沒有聽見他的聲音，也沒有看見他的形像。",
   "en": "The Father himself, who sent me, has testified about me. You have neither heard his voice at any time, nor seen his form."
  },
  "38": {
   "zh": "你們並沒有他的道存在心裡；因為他所差來的，你們不信。",
   "en": "You don’t have his word living in you; because you don’t believe him whom he sent."
  },
  "39": {
   "zh": "你們查考聖經（或譯：應當查考聖經），因你們以為內中有永生；給我作見證的就是這經。",
   "en": "“You search the Scriptures, because you think that in them you have eternal life; and these are they which testify about me."
  },
  "40": {
   "zh": "然而，你們不肯到我這裡來得生命。",
   "en": "Yet you will not come to me, that you may have life."
  },
  "41": {
   "zh": "「我不受從人來的榮耀。",
   "en": "I don’t receive glory from men."
  },
  "42": {
   "zh": "但我知道，你們心裡沒有神的愛。",
   "en": "But I know you, that you don’t have God’s love in yourselves."
  },
  "43": {
   "zh": "我奉我父的名來，你們並不接待我；若有別人奉自己的名來，你們倒要接待他。",
   "en": "I have come in my Father’s name, and you don’t receive me. If another comes in his own name, you will receive him."
  },
  "44": {
   "zh": "你們互相受榮耀，卻不求從獨一之神來的榮耀，怎能信我呢？",
   "en": "How can you believe, who receive glory from one another, and you don’t seek the glory that comes from the only God?"
  },
  "45": {
   "zh": "不要想我在父面前要告你們；有一位告你們的，就是你們所仰賴的摩西。",
   "en": "“Don’t think that I will accuse you to the Father. There is one who accuses you, even Moses, on whom you have set your hope."
  },
  "46": {
   "zh": "你們如果信摩西，也必信我，因為他書上有指著我寫的話。",
   "en": "For if you believed Moses, you would believe me; for he wrote about me."
  },
  "47": {
   "zh": "你們若不信他的書，怎能信我的話呢？」",
   "en": "But if you don’t believe his writings, how will you believe my words?”"
  }
 },
 "6": {
  "1": {
   "zh": "這事以後，耶穌渡過加利利海，就是提比哩亞海。",
   "en": "After these things, Jesus went away to the other side of the sea of Galilee, which is also called the Sea of Tiberias."
  },
  "2": {
   "zh": "有許多人因為看見他在病人身上所行的神蹟，就跟隨他。",
   "en": "A great multitude followed him, because they saw his signs which he did on those who were sick."
  },
  "3": {
   "zh": "耶穌上了山，和門徒一同坐在那裡。",
   "en": "Jesus went up into the mountain, and he sat there with his disciples."
  },
  "4": {
   "zh": "那時猶太人的逾越節近了。",
   "en": "Now the Passover, the feast of the Jews, was at hand."
  },
  "5": {
   "zh": "耶穌舉目看見許多人來，就對腓力說：「我們從哪裡買餅叫這些人吃呢？」",
   "en": "Jesus therefore lifting up his eyes, and seeing that a great multitude was coming to him, said to Philip, “Where are we to buy bread, that these may eat?”"
  },
  "6": {
   "zh": "（他說這話是要試驗腓力；他自己原知道要怎樣行。）",
   "en": "This he said to test him, for he himself knew what he would do."
  },
  "7": {
   "zh": "腓力回答說：「就是二十兩銀子的餅，叫他們各人吃一點也是不夠的。」",
   "en": "Philip answered him, “Two hundred denarii worth of bread is not sufficient for them, that everyone of them may receive a little.”"
  },
  "8": {
   "zh": "有一個門徒，就是西門•彼得的兄弟安得烈，對耶穌說：",
   "en": "One of his disciples, Andrew, Simon Peter’s brother, said to him,"
  },
  "9": {
   "zh": "「在這裡有一個孩童，帶著五個大麥餅、兩條魚，只是分給這許多人還算甚麼呢？」",
   "en": "“There is a boy here who has five barley loaves and two fish, but what are these among so many?”"
  },
  "10": {
   "zh": "耶穌說：「你們叫眾人坐下。」原來那地方的草多，眾人就坐下，數目約有五千。",
   "en": "Jesus said, “Have the people sit down.” Now there was much grass in that place. So the men sat down, in number about five thousand."
  },
  "11": {
   "zh": "耶穌拿起餅來，祝謝了，就分給那坐著的人；分魚也是這樣，都隨著他們所要的。",
   "en": "Jesus took the loaves; and having given thanks, he distributed to the disciples, and the disciples to those who were sitting down; likewise also of the fish as much as they desired."
  },
  "12": {
   "zh": "他們吃飽了，耶穌對門徒說：「把剩下的零碎收拾起來，免得有糟蹋的。」",
   "en": "When they were filled, he said to his disciples, “Gather up the broken pieces which are left over, that nothing be lost.”"
  },
  "13": {
   "zh": "他們便將那五個大麥餅的零碎，就是眾人吃了剩下的，收拾起來，裝滿了十二個籃子。",
   "en": "So they gathered them up, and filled twelve baskets with broken pieces from the five barley loaves, which were left over by those who had eaten."
  },
  "14": {
   "zh": "眾人看見耶穌所行的神蹟，就說：「這真是那要到世間來的先知！」",
   "en": "When therefore the people saw the sign which Jesus did, they said, “This is truly the prophet who comes into the world.”"
  },
  "15": {
   "zh": "耶穌既知道眾人要來強逼他作王，就獨自又退到山上去了。",
   "en": "Jesus therefore, perceiving that they were about to come and take him by force, to make him king, withdrew again to the mountain by himself."
  },
  "16": {
   "zh": "到了晚上，他的門徒下海邊去，",
   "en": "When evening came, his disciples went down to the sea,"
  },
  "17": {
   "zh": "上了船，要過海往迦百農去。天已經黑了，耶穌還沒有來到他們那裡。",
   "en": "and they entered into the boat, and were going over the sea to Capernaum. It was now dark, and Jesus had not come to them."
  },
  "18": {
   "zh": "忽然狂風大作，海就翻騰起來。",
   "en": "The sea was tossed by a great wind blowing."
  },
  "19": {
   "zh": "門徒搖櫓，約行了十里多路，看見耶穌在海面上走，漸漸近了船，他們就害怕。",
   "en": "When therefore they had rowed about twenty-five or thirty stadia, they saw Jesus walking on the sea, and drawing near to the boat; and they were afraid."
  },
  "20": {
   "zh": "耶穌對他們說：「是我，不要怕！」",
   "en": "But he said to them, “It is I. Don’t be afraid.”"
  },
  "21": {
   "zh": "門徒就喜歡接他上船，船立時到了他們所要去的地方。",
   "en": "They were willing therefore to receive him into the boat. Immediately the boat was at the land where they were going."
  },
  "22": {
   "zh": "第二日，站在海那邊的眾人知道那裡沒有別的船，只有一隻小船，又知道耶穌沒有同他的門徒上船，乃是門徒自己去的。",
   "en": "On the next day, the multitude that stood on the other side of the sea saw that there was no other boat there, except the one in which his disciples had embarked, and that Jesus hadn’t entered with his disciples into the boat, but his disciples had gone away alone."
  },
  "23": {
   "zh": "然而，有幾隻小船從提比哩亞來，靠近主祝謝後分餅給人吃的地方。",
   "en": "However boats from Tiberias came near to the place where they ate the bread after the Lord had given thanks."
  },
  "24": {
   "zh": "眾人見耶穌和門徒都不在那裡，就上了船，往迦百農去找耶穌。",
   "en": "When the multitude therefore saw that Jesus wasn’t there, nor his disciples, they themselves got into the boats, and came to Capernaum, seeking Jesus."
  },
  "25": {
   "zh": "既在海那邊找著了，就對他說：「拉比，是幾時到這裡來的？」",
   "en": "When they found him on the other side of the sea, they asked him, “Rabbi, when did you come here?”"
  },
  "26": {
   "zh": "耶穌回答說：「我實實在在地告訴你們，你們找我，並不是因見了神蹟，乃是因吃餅得飽。",
   "en": "Jesus answered them, “Most certainly I tell you, you seek me, not because you saw signs, but because you ate of the loaves, and were filled."
  },
  "27": {
   "zh": "不要為那必壞的食物勞力，要為那存到永生的食物勞力，就是人子要賜給你們的，因為人子是父神所印證的。」",
   "en": "Don’t work for the food which perishes, but for the food which remains to eternal life, which the Son of Man will give to you. For God the Father has sealed him.”"
  },
  "28": {
   "zh": "眾人問他說：「我們當行甚麼才算做神的工呢？」",
   "en": "They said therefore to him, “What must we do, that we may work the works of God?”"
  },
  "29": {
   "zh": "耶穌回答說：「信神所差來的，這就是做神的工。」",
   "en": "Jesus answered them, “This is the work of God, that you believe in him whom he has sent.”"
  },
  "30": {
   "zh": "他們又說：「你行甚麼神蹟，叫我們看見就信你；你到底做甚麼事呢？",
   "en": "They said therefore to him, “What then do you do for a sign, that we may see, and believe you? What work do you do?"
  },
  "31": {
   "zh": "我們的祖宗在曠野吃過嗎哪，如經上寫著說：『他從天上賜下糧來給他們吃。』」",
   "en": "Our fathers ate the manna in the wilderness. As it is written, ‘He gave them bread out of heaven to eat.’”"
  },
  "32": {
   "zh": "耶穌說：「我實實在在地告訴你們，那從天上來的糧不是摩西賜給你們的，乃是我父將天上來的真糧賜給你們。",
   "en": "Jesus therefore said to them, “Most certainly, I tell you, it wasn’t Moses who gave you the bread out of heaven, but my Father gives you the true bread out of heaven."
  },
  "33": {
   "zh": "因為神的糧就是那從天上降下來、賜生命給世界的。」",
   "en": "For the bread of God is that which comes down out of heaven, and gives life to the world.”"
  },
  "34": {
   "zh": "他們說：「主啊，常將這糧賜給我們！」",
   "en": "They said therefore to him, “Lord, always give us this bread.”"
  },
  "35": {
   "zh": "耶穌說：「我就是生命的糧。到我這裡來的，必定不餓；信我的，永遠不渴。",
   "en": "Jesus said to them, “I am the bread of life. He who comes to me will not be hungry, and he who believes in me will never be thirsty."
  },
  "36": {
   "zh": "只是我對你們說過，你們已經看見我，還是不信。",
   "en": "But I told you that you have seen me, and yet you don’t believe."
  },
  "37": {
   "zh": "凡父所賜給我的人必到我這裡來；到我這裡來的，我總不丟棄他。",
   "en": "All those whom the Father gives me will come to me. He who comes to me I will in no way throw out."
  },
  "38": {
   "zh": "因為我從天上降下來，不是要按自己的意思行，乃是要按那差我來者的意思行。",
   "en": "For I have come down from heaven, not to do my own will, but the will of him who sent me."
  },
  "39": {
   "zh": "差我來者的意思就是：他所賜給我的，叫我一個也不失落，在末日卻叫他復活。",
   "en": "This is the will of my Father who sent me, that of all he has given to me I should lose nothing, but should raise him up at the last day."
  },
  "40": {
   "zh": "因為我父的意思是叫一切見子而信的人得永生，並且在末日我要叫他復活。」",
   "en": "This is the will of the one who sent me, that everyone who sees the Son, and believes in him, should have eternal life; and I will raise him up at the last day.”"
  },
  "41": {
   "zh": "猶太人因為耶穌說「我是從天上降下來的糧」，就私下議論他，",
   "en": "The Jews therefore murmured concerning him, because he said, “I am the bread which came down out of heaven.”"
  },
  "42": {
   "zh": "說：「這不是約瑟的兒子耶穌嗎？他的父母我們豈不認得嗎？他如今怎麼說『我是從天上降下來的』呢？」",
   "en": "They said, “Isn’t this Jesus, the son of Joseph, whose father and mother we know? How then does he say, ‘I have come down out of heaven?’”"
  },
  "43": {
   "zh": "耶穌回答說：「你們不要大家議論。",
   "en": "Therefore Jesus answered them, “Don’t murmur among yourselves."
  },
  "44": {
   "zh": "若不是差我來的父吸引人，就沒有能到我這裡來的；到我這裡來的，在末日我要叫他復活。",
   "en": "No one can come to me unless the Father who sent me draws him, and I will raise him up in the last day."
  },
  "45": {
   "zh": "在先知書上寫著說：『他們都要蒙神的教訓。』凡聽見父之教訓又學習的，就到我這裡來。",
   "en": "It is written in the prophets, ‘They will all be taught by God.’ Therefore everyone who hears from the Father, and has learned, comes to me."
  },
  "46": {
   "zh": "這不是說有人看見過父，惟獨從神來的，他看見過父。",
   "en": "Not that anyone has seen the Father, except he who is from God. He has seen the Father."
  },
  "47": {
   "zh": "我實實在在地告訴你們，信的人有永生。",
   "en": "Most certainly, I tell you, he who believes in me has eternal life."
  },
  "48": {
   "zh": "我就是生命的糧。",
   "en": "I am the bread of life."
  },
  "49": {
   "zh": "你們的祖宗在曠野吃過嗎哪，還是死了。",
   "en": "Your fathers ate the manna in the wilderness, and they died."
  },
  "50": {
   "zh": "這是從天上降下來的糧，叫人吃了就不死。",
   "en": "This is the bread which comes down out of heaven, that anyone may eat of it and not die."
  },
  "51": {
   "zh": "我是從天上降下來生命的糧；人若吃這糧，就必永遠活著。我所要賜的糧就是我的肉，為世人之生命所賜的。」",
   "en": "I am the living bread which came down out of heaven. If anyone eats of this bread, he will live forever. Yes, the bread which I will give for the life of the world is my flesh.”"
  },
  "52": {
   "zh": "因此，猶太人彼此爭論說：「這個人怎能把他的肉給我們吃呢？」",
   "en": "The Jews therefore contended with one another, saying, “How can this man give us his flesh to eat?”"
  },
  "53": {
   "zh": "耶穌說：「我實實在在地告訴你們，你們若不吃人子的肉，不喝人子的血，就沒有生命在你們裡面。",
   "en": "Jesus therefore said to them, “Most certainly I tell you, unless you eat the flesh of the Son of Man and drink his blood, you don’t have life in yourselves."
  },
  "54": {
   "zh": "吃我肉、喝我血的人就有永生，在末日我要叫他復活。",
   "en": "He who eats my flesh and drinks my blood has eternal life, and I will raise him up at the last day."
  },
  "55": {
   "zh": "我的肉真是可吃的，我的血真是可喝的。",
   "en": "For my flesh is food indeed, and my blood is drink indeed."
  },
  "56": {
   "zh": "吃我肉、喝我血的人常在我裡面，我也常在他裡面。",
   "en": "He who eats my flesh and drinks my blood lives in me, and I in him."
  },
  "57": {
   "zh": "永活的父怎樣差我來，我又因父活著；照樣，吃我肉的人也要因我活著。",
   "en": "As the living Father sent me, and I live because of the Father; so he who feeds on me, he will also live because of me."
  },
  "58": {
   "zh": "這就是從天上降下來的糧。吃這糧的人就永遠活著，不像你們的祖宗吃過嗎哪還是死了。」",
   "en": "This is the bread which came down out of heaven—not as our fathers ate the manna, and died. He who eats this bread will live forever.”"
  },
  "59": {
   "zh": "這些話是耶穌在迦百農會堂裡教訓人說的。",
   "en": "He said these things in the synagogue, as he taught in Capernaum."
  },
  "60": {
   "zh": "他的門徒中有好些人聽見了，就說：「這話甚難，誰能聽呢？」",
   "en": "Therefore many of his disciples, when they heard this, said, “This is a hard saying! Who can listen to it?”"
  },
  "61": {
   "zh": "耶穌心裡知道門徒為這話議論，就對他們說：「這話是叫你們厭棄（原文是跌倒）嗎？",
   "en": "But Jesus knowing in himself that his disciples murmured at this, said to them, “Does this cause you to stumble?"
  },
  "62": {
   "zh": "倘或你們看見人子升到他原來所在之處，怎麼樣呢？",
   "en": "Then what if you would see the Son of Man ascending to where he was before?"
  },
  "63": {
   "zh": "叫人活著的乃是靈，肉體是無益的。我對你們所說的話就是靈，就是生命。",
   "en": "It is the spirit who gives life. The flesh profits nothing. The words that I speak to you are spirit, and are life."
  },
  "64": {
   "zh": "只是你們中間有不信的人。」耶穌從起頭就知道誰不信他，誰要賣他。",
   "en": "But there are some of you who don’t believe.” For Jesus knew from the beginning who they were who didn’t believe, and who it was who would betray him."
  },
  "65": {
   "zh": "耶穌又說：「所以我對你們說過，若不是蒙我父的恩賜，沒有人能到我這裡來。」",
   "en": "He said, “For this cause I have said to you that no one can come to me, unless it is given to him by my Father.”"
  },
  "66": {
   "zh": "從此，他門徒中多有退去的，不再和他同行。",
   "en": "At this, many of his disciples went back, and walked no more with him."
  },
  "67": {
   "zh": "耶穌就對那十二個門徒說：「你們也要去嗎？」",
   "en": "Jesus said therefore to the twelve, “You don’t also want to go away, do you?”"
  },
  "68": {
   "zh": "西門•彼得回答說：「主啊，你有永生之道，我們還歸從誰呢？",
   "en": "Simon Peter answered him, “Lord, to whom would we go? You have the words of eternal life."
  },
  "69": {
   "zh": "我們已經信了，又知道你是神的聖者。」",
   "en": "We have come to believe and know that you are the Christ, the Son of the living God.”"
  },
  "70": {
   "zh": "耶穌說：「我不是揀選了你們十二個門徒嗎？但你們中間有一個是魔鬼。」",
   "en": "Jesus answered them, “Didn’t I choose you, the twelve, and one of you is a devil?”"
  },
  "71": {
   "zh": "耶穌這話是指著加略人西門的兒子猶大說的；他本是十二個門徒裡的一個，後來要賣耶穌的。",
   "en": "Now he spoke of Judas, the son of Simon Iscariot, for it was he who would betray him, being one of the twelve."
  }
 },
 "7": {
  "1": {
   "zh": "這事以後，耶穌在加利利遊行，不願在猶太遊行，因為猶太人想要殺他。",
   "en": "After these things, Jesus was walking in Galilee, for he wouldn’t walk in Judea, because the Jews sought to kill him."
  },
  "2": {
   "zh": "當時猶太人的住棚節近了。",
   "en": "Now the feast of the Jews, the Feast of Booths, was at hand."
  },
  "3": {
   "zh": "耶穌的弟兄就對他說：「你離開這裡上猶太去吧，叫你的門徒也看見你所行的事。",
   "en": "His brothers therefore said to him, “Depart from here, and go into Judea, that your disciples also may see your works which you do."
  },
  "4": {
   "zh": "人要顯揚名聲，沒有在暗處行事的；你如果行這些事，就當將自己顯明給世人看。」",
   "en": "For no one does anything in secret, and himself seeks to be known openly. If you do these things, reveal yourself to the world.”"
  },
  "5": {
   "zh": "因為連他的弟兄說這話，是因為不信他。",
   "en": "For even his brothers didn’t believe in him."
  },
  "6": {
   "zh": "耶穌就對他們說：「我的時候還沒有到；你們的時候常是方便的。",
   "en": "Jesus therefore said to them, “My time has not yet come, but your time is always ready."
  },
  "7": {
   "zh": "世人不能恨你們，卻是恨我，因為我指證他們所做的事是惡的。",
   "en": "The world can’t hate you, but it hates me, because I testify about it, that its works are evil."
  },
  "8": {
   "zh": "你們上去過節吧，我現在不上去過這節，因為我的時候還沒有滿。」",
   "en": "You go up to the feast. I am not yet going up to this feast, because my time is not yet fulfilled.”"
  },
  "9": {
   "zh": "耶穌說了這話，仍舊住在加利利。",
   "en": "Having said these things to them, he stayed in Galilee."
  },
  "10": {
   "zh": "但他弟兄上去以後，他也上去過節，不是明去，似乎是暗去的。",
   "en": "But when his brothers had gone up to the feast, then he also went up, not publicly, but as it were in secret."
  },
  "11": {
   "zh": "正在節期，猶太人尋找耶穌，說：「他在哪裡？」",
   "en": "The Jews therefore sought him at the feast, and said, “Where is he?”"
  },
  "12": {
   "zh": "眾人為他紛紛議論，有的說：「他是好人。」有的說：「不然，他是迷惑眾人的。」",
   "en": "There was much murmuring among the multitudes concerning him. Some said, “He is a good man.” Others said, “Not so, but he leads the multitude astray.”"
  },
  "13": {
   "zh": "只是沒有人明明地講論他，因為怕猶太人。",
   "en": "Yet no one spoke openly of him for fear of the Jews."
  },
  "14": {
   "zh": "到了節期，耶穌上殿裡去教訓人。",
   "en": "But when it was now the middle of the feast, Jesus went up into the temple and taught."
  },
  "15": {
   "zh": "猶太人就希奇，說：「這個人沒有學過，怎麼明白書呢？」",
   "en": "The Jews therefore marveled, saying, “How does this man know letters, having never been educated?”"
  },
  "16": {
   "zh": "耶穌說：「我的教訓不是我自己的，乃是那差我來者的。",
   "en": "Jesus therefore answered them, “My teaching is not mine, but his who sent me."
  },
  "17": {
   "zh": "人若立志遵著他的旨意行，就必曉得這教訓或是出於神，或是我憑著自己說的。",
   "en": "If anyone desires to do his will, he will know about the teaching, whether it is from God, or if I am speaking from myself."
  },
  "18": {
   "zh": "人憑著自己說，是求自己的榮耀；惟有求那差他來者的榮耀，這人是真的，在他心裡沒有不義。",
   "en": "He who speaks from himself seeks his own glory, but he who seeks the glory of him who sent him is true, and no unrighteousness is in him."
  },
  "19": {
   "zh": "摩西豈不是傳律法給你們嗎？你們卻沒有一個人守律法。為甚麼想要殺我呢？」",
   "en": "Didn’t Moses give you the law, and yet none of you keeps the law? Why do you seek to kill me?”"
  },
  "20": {
   "zh": "眾人回答說：「你是被鬼附著了！誰想要殺你？」",
   "en": "The multitude answered, “You have a demon! Who seeks to kill you?”"
  },
  "21": {
   "zh": "耶穌說：「我做了一件事，你們都以為希奇。",
   "en": "Jesus answered them, “I did one work, and you all marvel because of it."
  },
  "22": {
   "zh": "摩西傳割禮給你們（其實不是從摩西起的，乃是從祖先起的），因此你們也在安息日給人行割禮。",
   "en": "Moses has given you circumcision (not that it is of Moses, but of the fathers), and on the Sabbath you circumcise a boy."
  },
  "23": {
   "zh": "人若在安息日受割禮，免得違背摩西的律法，我在安息日叫一個人全然好了，你們就向我生氣嗎？",
   "en": "If a boy receives circumcision on the Sabbath, that the law of Moses may not be broken, are you angry with me, because I made a man completely healthy on the Sabbath?"
  },
  "24": {
   "zh": "不可按外貌斷定是非，總要按公平斷定是非。」",
   "en": "Don’t judge according to appearance, but judge righteous judgment.”"
  },
  "25": {
   "zh": "耶路撒冷人中有的說：「這不是他們想要殺的人嗎？",
   "en": "Therefore some of them of Jerusalem said, “Isn’t this he whom they seek to kill?"
  },
  "26": {
   "zh": "你看他還明明地講道，他們也不向他說甚麼，難道官長真知道這是基督嗎？",
   "en": "Behold, he speaks openly, and they say nothing to him. Can it be that the rulers indeed know that this is truly the Christ?"
  },
  "27": {
   "zh": "然而，我們知道這個人從哪裡來；只是基督來的時候，沒有人知道他從哪裡來。」",
   "en": "However we know where this man comes from, but when the Christ comes, no one will know where he comes from.”"
  },
  "28": {
   "zh": "那時，耶穌在殿裡教訓人，大聲說：「你們也知道我，也知道我從哪裡來；我來並不是由於自己。但那差我來的是真的。你們不認識他，",
   "en": "Jesus therefore cried out in the temple, teaching and saying, “You both know me, and know where I am from. I have not come of myself, but he who sent me is true, whom you don’t know."
  },
  "29": {
   "zh": "我卻認識他；因為我是從他來的，他也是差了我來。」",
   "en": "I know him, because I am from him, and he sent me.”"
  },
  "30": {
   "zh": "他們就想要捉拿耶穌；只是沒有人下手，因為他的時候還沒有到。",
   "en": "They sought therefore to take him; but no one laid a hand on him, because his hour had not yet come."
  },
  "31": {
   "zh": "但眾人中間有好些信他的，說：「基督來的時候，他所行的神蹟豈能比這人所行的更多嗎？」",
   "en": "But of the multitude, many believed in him. They said, “When the Christ comes, he won’t do more signs than those which this man has done, will he?”"
  },
  "32": {
   "zh": "法利賽人聽見眾人為耶穌這樣紛紛議論，祭司長和法利賽人就打發差役去捉拿他。",
   "en": "The Pharisees heard the multitude murmuring these things concerning him, and the chief priests and the Pharisees sent officers to arrest him."
  },
  "33": {
   "zh": "於是耶穌說：「我還有不多的時候和你們同在，以後就回到差我來的那裡去。",
   "en": "Then Jesus said, “I will be with you a little while longer, then I go to him who sent me."
  },
  "34": {
   "zh": "你們要找我，卻找不著；我所在的地方你們不能到。」",
   "en": "You will seek me, and won’t find me; and where I am, you can’t come.”"
  },
  "35": {
   "zh": "猶太人就彼此對問說：「這人要往哪裡去，叫我們找不著呢？難道他要往散住希臘中的猶太人那裡去教訓希臘人嗎？",
   "en": "The Jews therefore said among themselves, “Where will this man go that we won’t find him? Will he go to the Dispersion among the Greeks, and teach the Greeks?"
  },
  "36": {
   "zh": "他說：『你們要找我，卻找不著；我所在的地方，你們不能到』，這話是甚麼意思呢？」",
   "en": "What is this word that he said, ‘You will seek me, and won’t find me; and where I am, you can’t come’?”"
  },
  "37": {
   "zh": "節期的末日，就是最大之日，耶穌站著高聲說：「人若渴了，可以到我這裡來喝。",
   "en": "Now on the last and greatest day of the feast, Jesus stood and cried out, “If anyone is thirsty, let him come to me and drink!"
  },
  "38": {
   "zh": "信我的人就如經上所說：『從他腹中要流出活水的江河來。』」",
   "en": "He who believes in me, as the Scripture has said, from within him will flow rivers of living water.”"
  },
  "39": {
   "zh": "耶穌這話是指著信他之人要受聖靈說的。那時還沒有賜下聖靈來，因為耶穌尚未得著榮耀。",
   "en": "But he said this about the Spirit, which those believing in him were to receive. For the Holy Spirit was not yet given, because Jesus wasn’t yet glorified."
  },
  "40": {
   "zh": "眾人聽見這話，有的說：「這真是那先知。」",
   "en": "Many of the multitude therefore, when they heard these words, said, “This is truly the prophet.”"
  },
  "41": {
   "zh": "有的說：「這是基督。」但也有的說：「基督豈是從加利利出來的嗎？",
   "en": "Others said, “This is the Christ.” But some said, “What, does the Christ come out of Galilee?"
  },
  "42": {
   "zh": "經上豈不是說『基督是大衛的後裔，從大衛本鄉伯利恆出來的』嗎？」",
   "en": "Hasn’t the Scripture said that the Christ comes of the offspring of David, and from Bethlehem, the village where David was?”"
  },
  "43": {
   "zh": "於是眾人因著耶穌起了紛爭。",
   "en": "So there arose a division in the multitude because of him."
  },
  "44": {
   "zh": "其中有人要捉拿他，只是無人下手。",
   "en": "Some of them would have arrested him, but no one laid hands on him."
  },
  "45": {
   "zh": "差役回到祭司長和法利賽人那裡。他們對差役說：「你們為甚麼沒有帶他來呢？」",
   "en": "The officers therefore came to the chief priests and Pharisees, and they said to them, “Why didn’t you bring him?”"
  },
  "46": {
   "zh": "差役回答說：「從來沒有像他這樣說話的！」",
   "en": "The officers answered, “No man ever spoke like this man!”"
  },
  "47": {
   "zh": "法利賽人說：「你們也受了迷惑嗎？",
   "en": "The Pharisees therefore answered them, “You aren’t also led astray, are you?"
  },
  "48": {
   "zh": "官長或是法利賽人豈有信他的呢？",
   "en": "Have any of the rulers believed in him, or of the Pharisees?"
  },
  "49": {
   "zh": "但這些不明白律法的百姓是被咒詛的！」",
   "en": "But this multitude that doesn’t know the law is accursed.”"
  },
  "50": {
   "zh": "內中有尼哥底母，就是從前去見耶穌的，對他們說：",
   "en": "Nicodemus (he who came to him by night, being one of them) said to them,"
  },
  "51": {
   "zh": "「不先聽本人的口供，不知道他所做的事，難道我們的律法還定他的罪嗎？」",
   "en": "“Does our law judge a man, unless it first hears from him personally and knows what he does?”"
  },
  "52": {
   "zh": "他們回答說：「你也是出於加利利嗎？你且去查考，就可知道加利利沒有出過先知。」",
   "en": "They answered him, “Are you also from Galilee? Search, and see that no prophet has arisen out of Galilee.”"
  },
  "53": {
   "zh": "",
   "en": "Everyone went to his own house,"
  }
 },
 "8": {
  "1": {
   "zh": "於是各人都回家去了；耶穌卻往橄欖山去，",
   "en": "but Jesus went to the Mount of Olives."
  },
  "2": {
   "zh": "清早又回到殿裡。眾百姓都到他那裡去，他就坐下，教訓他們。",
   "en": "Now very early in the morning, he came again into the temple, and all the people came to him. He sat down, and taught them."
  },
  "3": {
   "zh": "文士和法利賽人帶著一個行淫時被拿的婦人來，叫她站在當中，",
   "en": "The scribes and the Pharisees brought a woman taken in adultery. Having set her in the middle,"
  },
  "4": {
   "zh": "就對耶穌說：「夫子，這婦人是正行淫之時被拿的。",
   "en": "they told him, “Teacher, we found this woman in adultery, in the very act."
  },
  "5": {
   "zh": "摩西在律法上吩咐我們把這樣的婦人用石頭打死。你說該把她怎麼樣呢？」",
   "en": "Now in our law, Moses commanded us to stone such women. What then do you say about her?”"
  },
  "6": {
   "zh": "他們說這話，乃試探耶穌，要得著告他的把柄。耶穌卻彎著腰，用指頭在地上畫字。",
   "en": "They said this testing him, that they might have something to accuse him of. But Jesus stooped down, and wrote on the ground with his finger."
  },
  "7": {
   "zh": "他們還是不住地問他，耶穌就直起腰來，對他們說：「你們中間誰是沒有罪的，誰就可以先拿石頭打她。」",
   "en": "But when they continued asking him, he looked up and said to them, “He who is without sin among you, let him throw the first stone at her.”"
  },
  "8": {
   "zh": "於是又彎著腰，用指頭在地上畫字。",
   "en": "Again he stooped down, and with his finger wrote on the ground."
  },
  "9": {
   "zh": "他們聽見這話，就從老到少，一個一個地都出去了，只剩下耶穌一人，還有那婦人仍然站在當中。",
   "en": "They, when they heard it, being convicted by their conscience, went out one by one, beginning from the oldest, even to the last. Jesus was left alone with the woman where she was, in the middle."
  },
  "10": {
   "zh": "耶穌就直起腰來，對她說：「婦人，那些人在哪裡呢？沒有人定你的罪嗎？」",
   "en": "Jesus, standing up, saw her and said, “Woman, where are your accusers? Did no one condemn you?”"
  },
  "11": {
   "zh": "她說：「主啊，沒有。」耶穌說：「我也不定你的罪。去吧，從此不要再犯罪了！」",
   "en": "She said, “No one, Lord.” Jesus said, “Neither do I condemn you. Go your way. From now on, sin no more.”"
  },
  "12": {
   "zh": "耶穌又對眾人說：「我是世界的光。跟從我的，就不在黑暗裡走，必要得著生命的光。」",
   "en": "Again, therefore, Jesus spoke to them, saying, “I am the light of the world. He who follows me will not walk in the darkness, but will have the light of life.”"
  },
  "13": {
   "zh": "法利賽人對他說：「你是為自己作見證，你的見證不真。」",
   "en": "The Pharisees therefore said to him, “You testify about yourself. Your testimony is not valid.”"
  },
  "14": {
   "zh": "耶穌說：「我雖然為自己作見證，我的見證還是真的；因我知道我從哪裡來，往哪裡去；你們卻不知道我從哪裡來，往哪裡去。",
   "en": "Jesus answered them, “Even if I testify about myself, my testimony is true, for I know where I came from, and where I am going; but you don’t know where I came from, or where I am going."
  },
  "15": {
   "zh": "你們是以外貌（原文是憑肉身）判斷人，我卻不判斷人。",
   "en": "You judge according to the flesh. I judge no one."
  },
  "16": {
   "zh": "就是判斷人，我的判斷也是真的；因為不是我獨自在這裡，還有差我來的父與我同在。",
   "en": "Even if I do judge, my judgment is true, for I am not alone, but I am with the Father who sent me."
  },
  "17": {
   "zh": "你們的律法上也記著說：『兩個人的見證是真的。』",
   "en": "It’s also written in your law that the testimony of two people is valid."
  },
  "18": {
   "zh": "我是為自己作見證，還有差我來的父也是為我作見證。」",
   "en": "I am one who testifies about myself, and the Father who sent me testifies about me.”"
  },
  "19": {
   "zh": "他們就問他說：「你的父在哪裡？」耶穌回答說：「你們不認識我，也不認識我的父；若是認識我，也就認識我的父。」",
   "en": "They said therefore to him, “Where is your Father?” Jesus answered, “You know neither me, nor my Father. If you knew me, you would know my Father also.”"
  },
  "20": {
   "zh": "這些話是耶穌在殿裡的庫房、教訓人時所說的，也沒有人拿他，因為他的時候還沒有到。",
   "en": "Jesus spoke these words in the treasury, as he taught in the temple. Yet no one arrested him, because his hour had not yet come."
  },
  "21": {
   "zh": "耶穌又對他們說：「我要去了，你們要找我，並且你們要死在罪中。我所去的地方，你們不能到。」",
   "en": "Jesus said therefore again to them, “I am going away, and you will seek me, and you will die in your sins. Where I go, you can’t come.”"
  },
  "22": {
   "zh": "猶太人說：「他說『我所去的地方，你們不能到』，難道他要自盡嗎？」",
   "en": "The Jews therefore said, “Will he kill himself, because he says, ‘Where I am going, you can’t come’?”"
  },
  "23": {
   "zh": "耶穌對他們說：「你們是從下頭來的，我是從上頭來的；你們是屬這世界的，我不是屬這世界的。",
   "en": "He said to them, “You are from beneath. I am from above. You are of this world. I am not of this world."
  },
  "24": {
   "zh": "所以我對你們說，你們要死在罪中。你們若不信我是基督，必要死在罪中。」",
   "en": "I said therefore to you that you will die in your sins; for unless you believe that I am he, you will die in your sins.”"
  },
  "25": {
   "zh": "他們就問他說：「你是誰？」耶穌對他們說：「就是我從起初所告訴你們的。",
   "en": "They said therefore to him, “Who are you?” Jesus said to them, “Just what I have been saying to you from the beginning."
  },
  "26": {
   "zh": "我有許多事講論你們，判斷你們；但那差我來的是真的，我在他那裡所聽見的，我就傳給世人。」",
   "en": "I have many things to speak and to judge concerning you. However he who sent me is true; and the things which I heard from him, these I say to the world.”"
  },
  "27": {
   "zh": "他們不明白耶穌是指著父說的。",
   "en": "They didn’t understand that he spoke to them about the Father."
  },
  "28": {
   "zh": "所以耶穌說：「你們舉起人子以後，必知道我是基督，並且知道我沒有一件事是憑著自己做的。我說這些話乃是照著父所教訓我的。",
   "en": "Jesus therefore said to them, “When you have lifted up the Son of Man, then you will know that I am he, and I do nothing of myself, but as my Father taught me, I say these things."
  },
  "29": {
   "zh": "那差我來的是與我同在；他沒有撇下我獨自在這裡，因為我常做他所喜悅的事。」",
   "en": "He who sent me is with me. The Father hasn’t left me alone, for I always do the things that are pleasing to him.”"
  },
  "30": {
   "zh": "耶穌說這話的時候，就有許多人信他。",
   "en": "As he spoke these things, many believed in him."
  },
  "31": {
   "zh": "耶穌對信他的猶太人說：「你們若常常遵守我的道，就真是我的門徒；",
   "en": "Jesus therefore said to those Jews who had believed him, “If you remain in my word, then you are truly my disciples."
  },
  "32": {
   "zh": "你們必曉得真理，真理必叫你們得以自由。」",
   "en": "You will know the truth, and the truth will make you free.”"
  },
  "33": {
   "zh": "他們回答說：「我們是亞伯拉罕的後裔，從來沒有作過誰的奴僕。你怎麼說『你們必得以自由』呢？」",
   "en": "They answered him, “We are Abraham’s offspring, and have never been in bondage to anyone. How do you say, ‘You will be made free’?”"
  },
  "34": {
   "zh": "耶穌回答說：「我實實在在地告訴你們，所有犯罪的就是罪的奴僕。",
   "en": "Jesus answered them, “Most certainly I tell you, everyone who commits sin is the bondservant of sin."
  },
  "35": {
   "zh": "奴僕不能永遠住在家裡；兒子是永遠住在家裡。",
   "en": "A bondservant doesn’t live in the house forever. A son remains forever."
  },
  "36": {
   "zh": "所以天父的兒子若叫你們自由，你們就真自由了。",
   "en": "If therefore the Son makes you free, you will be free indeed."
  },
  "37": {
   "zh": "我知道你們是亞伯拉罕的子孫，你們卻想要殺我，因為你們心裡容不下我的道。",
   "en": "I know that you are Abraham’s offspring, yet you seek to kill me, because my word finds no place in you."
  },
  "38": {
   "zh": "我所說的是在我父那裡看見的；你們所行的是在你們的父那裡聽見的。」",
   "en": "I say the things which I have seen with my Father; and you also do the things which you have seen with your father.”"
  },
  "39": {
   "zh": "他們說：「我們的父就是亞伯拉罕。」耶穌說：「你們若是亞伯拉罕的兒子，就必行亞伯拉罕所行的事。",
   "en": "They answered him, “Our father is Abraham.” Jesus said to them, “If you were Abraham’s children, you would do the works of Abraham."
  },
  "40": {
   "zh": "我將在神那裡所聽見的真理告訴了你們，現在你們卻想要殺我，這不是亞伯拉罕所行的事。",
   "en": "But now you seek to kill me, a man who has told you the truth, which I heard from God. Abraham didn’t do this."
  },
  "41": {
   "zh": "你們是行你們父所行的事。」他們說：「我們不是從淫亂生的；我們只有一位父，就是神。」",
   "en": "You do the works of your father.” They said to him, “We were not born of sexual immorality. We have one Father, God.”"
  },
  "42": {
   "zh": "耶穌說：「倘若神是你們的父，你們就必愛我；因為我本是出於神，也是從神而來，並不是由著自己來，乃是他差我來。",
   "en": "Therefore Jesus said to them, “If God were your father, you would love me, for I came out and have come from God. For I haven’t come of myself, but he sent me."
  },
  "43": {
   "zh": "你們為甚麼不明白我的話呢？無非是因你們不能聽我的道。",
   "en": "Why don’t you understand my speech? Because you can’t hear my word."
  },
  "44": {
   "zh": "你們是出於你們的父魔鬼，你們父的私慾你們偏要行。他從起初是殺人的，不守真理，因他心裡沒有真理。他說謊是出於自己；因他本來是說謊的，也是說謊之人的父。",
   "en": "You are of your father, the devil, and you want to do the desires of your father. He was a murderer from the beginning, and doesn’t stand in the truth, because there is no truth in him. When he speaks a lie, he speaks on his own; for he is a liar, and the father of lies."
  },
  "45": {
   "zh": "我將真理告訴你們，你們就因此不信我。",
   "en": "But because I tell the truth, you don’t believe me."
  },
  "46": {
   "zh": "你們中間誰能指證我有罪呢？我既然將真理告訴你們，為甚麼不信我呢？",
   "en": "Which of you convicts me of sin? If I tell the truth, why do you not believe me?"
  },
  "47": {
   "zh": "出於神的，必聽神的話；你們不聽，因為你們不是出於神。」",
   "en": "He who is of God hears the words of God. For this cause you don’t hear, because you are not of God.”"
  },
  "48": {
   "zh": "猶太人回答說：「我們說你是撒馬利亞人，並且是鬼附著的，這話豈不正對嗎？」",
   "en": "Then the Jews answered him, “Don’t we say well that you are a Samaritan, and have a demon?”"
  },
  "49": {
   "zh": "耶穌說：「我不是鬼附著的；我尊敬我的父，你們倒輕慢我。",
   "en": "Jesus answered, “I don’t have a demon, but I honor my Father, and you dishonor me."
  },
  "50": {
   "zh": "我不求自己的榮耀，有一位為我求榮耀、定是非的。",
   "en": "But I don’t seek my own glory. There is one who seeks and judges."
  },
  "51": {
   "zh": "我實實在在地告訴你們，人若遵守我的道，就永遠不見死。」",
   "en": "Most certainly, I tell you, if a person keeps my word, he will never see death.”"
  },
  "52": {
   "zh": "猶太人對他說：「現在我們知道你是鬼附著的。亞伯拉罕死了，眾先知也死了，你還說：『人若遵守我的道，就永遠不嘗死味。』",
   "en": "Then the Jews said to him, “Now we know that you have a demon. Abraham died, and the prophets; and you say, ‘If a man keeps my word, he will never taste of death.’"
  },
  "53": {
   "zh": "難道你比我們的祖宗亞伯拉罕還大嗎？他死了，眾先知也死了，你將自己當作甚麼人呢？」",
   "en": "Are you greater than our father, Abraham, who died? The prophets died. Who do you make yourself out to be?”"
  },
  "54": {
   "zh": "耶穌回答說：「我若榮耀自己，我的榮耀就算不得甚麼；榮耀我的乃是我的父，就是你們所說是你們的神。",
   "en": "Jesus answered, “If I glorify myself, my glory is nothing. It is my Father who glorifies me, of whom you say that he is our God."
  },
  "55": {
   "zh": "你們未曾認識他；我卻認識他。我若說不認識他，我就是說謊的，像你們一樣；但我認識他，也遵守他的道。",
   "en": "You have not known him, but I know him. If I said, ‘I don’t know him,’ I would be like you, a liar. But I know him, and keep his word."
  },
  "56": {
   "zh": "你們的祖宗亞伯拉罕歡歡喜喜地仰望我的日子，既看見了就快樂。」",
   "en": "Your father Abraham rejoiced to see my day. He saw it, and was glad.”"
  },
  "57": {
   "zh": "猶太人說：「你還沒有五十歲，豈見過亞伯拉罕呢？」",
   "en": "The Jews therefore said to him, “You are not yet fifty years old, and have you seen Abraham?”"
  },
  "58": {
   "zh": "耶穌說：「我實實在在地告訴你們，還沒有亞伯拉罕就有了我。」",
   "en": "Jesus said to them, “Most certainly, I tell you, before Abraham came into existence, I AM.”"
  },
  "59": {
   "zh": "於是他們拿石頭要打他；耶穌卻躲藏，從殿裡出去了。",
   "en": "Therefore they took up stones to throw at him, but Jesus was hidden, and went out of the temple, having gone through the middle of them, and so passed by."
  }
 },
 "9": {
  "1": {
   "zh": "耶穌過去的時候，看見一個人生來是瞎眼的。",
   "en": "As he passed by, he saw a man blind from birth."
  },
  "2": {
   "zh": "門徒問耶穌說：「拉比，這人生來是瞎眼的，是誰犯了罪？是這人呢？是他父母呢？」",
   "en": "His disciples asked him, “Rabbi, who sinned, this man or his parents, that he was born blind?”"
  },
  "3": {
   "zh": "耶穌回答說：「也不是這人犯了罪，也不是他父母犯了罪，是要在他身上顯出神的作為來。",
   "en": "Jesus answered, “Neither did this man sin, nor his parents; but, that the works of God might be revealed in him."
  },
  "4": {
   "zh": "趁著白日，我們必須做那差我來者的工；黑夜將到，就沒有人能做工了。",
   "en": "I must work the works of him who sent me, while it is day. The night is coming, when no one can work."
  },
  "5": {
   "zh": "我在世上的時候，是世上的光。」",
   "en": "While I am in the world, I am the light of the world.”"
  },
  "6": {
   "zh": "耶穌說了這話，就吐唾沫在地上，用唾沫和泥抹在瞎子的眼睛上，",
   "en": "When he had said this, he spat on the ground, made mud with the saliva, anointed the blind man’s eyes with the mud,"
  },
  "7": {
   "zh": "對他說：「你往西羅亞池子裡去洗。」（西羅亞翻出來就是「奉差遣」。）他去一洗，回頭就看見了。",
   "en": "and said to him, “Go, wash in the pool of Siloam” (which means “Sent”). So he went away, washed, and came back seeing."
  },
  "8": {
   "zh": "他的鄰舍和那素常見他是討飯的，就說：「這不是那從前坐著討飯的人嗎？」",
   "en": "The neighbors therefore, and those who saw that he was blind before, said, “Isn’t this he who sat and begged?”"
  },
  "9": {
   "zh": "有人說：「是他」；又有人說：「不是，卻是像他。」他自己說：「是我。」",
   "en": "Others were saying, “It is he.” Still others were saying, “He looks like him.” He said, “I am he.”"
  },
  "10": {
   "zh": "他們對他說：「你的眼睛是怎麼開的呢？」",
   "en": "They therefore were asking him, “How were your eyes opened?”"
  },
  "11": {
   "zh": "他回答說：「有一個人，名叫耶穌，他和泥抹我的眼睛，對我說：『你往西羅亞池子去洗。』我去一洗，就看見了。」",
   "en": "He answered, “A man called Jesus made mud, anointed my eyes, and said to me, ‘Go to the pool of Siloam, and wash.’ So I went away and washed, and I received sight.”"
  },
  "12": {
   "zh": "他們說：「那個人在哪裡？」他說：「我不知道。」",
   "en": "Then they asked him, “Where is he?” He said, “I don’t know.”"
  },
  "13": {
   "zh": "他們把從前瞎眼的人帶到法利賽人那裡。",
   "en": "They brought him who had been blind to the Pharisees."
  },
  "14": {
   "zh": "耶穌和泥開他眼睛的日子是安息日。",
   "en": "It was a Sabbath when Jesus made the mud and opened his eyes."
  },
  "15": {
   "zh": "法利賽人也問他是怎麼得看見的。瞎子對他們說：「他把泥抹在我的眼睛上，我去一洗，就看見了。」",
   "en": "Again therefore the Pharisees also asked him how he received his sight. He said to them, “He put mud on my eyes, I washed, and I see.”"
  },
  "16": {
   "zh": "法利賽人中有的說：「這個人不是從神來的，因為他不守安息日。」又有人說：「一個罪人怎能行這樣的神蹟呢？」他們就起了紛爭。",
   "en": "Some therefore of the Pharisees said, “This man is not from God, because he doesn’t keep the Sabbath.” Others said, “How can a man who is a sinner do such signs?” There was division among them."
  },
  "17": {
   "zh": "他們又對瞎子說：「他既然開了你的眼睛，你說他是怎樣的人呢？」他說：「是個先知。」",
   "en": "Therefore they asked the blind man again, “What do you say about him, because he opened your eyes?” He said, “He is a prophet.”"
  },
  "18": {
   "zh": "猶太人不信他從前是瞎眼，後來能看見的，等到叫了他的父母來，",
   "en": "The Jews therefore did not believe concerning him, that he had been blind, and had received his sight, until they called the parents of him who had received his sight,"
  },
  "19": {
   "zh": "問他們說：「這是你們的兒子嗎？你們說他生來是瞎眼的，如今怎麼能看見了呢？」",
   "en": "and asked them, “Is this your son, whom you say was born blind? How then does he now see?”"
  },
  "20": {
   "zh": "他父母回答說：「他是我們的兒子，生來就瞎眼，這是我們知道的。",
   "en": "His parents answered them, “We know that this is our son, and that he was born blind;"
  },
  "21": {
   "zh": "至於他如今怎麼能看見，我們卻不知道；是誰開了他的眼睛，我們也不知道。他已經成了人，你們問他吧，他自己必能說。」",
   "en": "but how he now sees, we don’t know; or who opened his eyes, we don’t know. He is of age. Ask him. He will speak for himself.”"
  },
  "22": {
   "zh": "他父母說這話，是怕猶太人；因為猶太人已經商議定了，若有認耶穌是基督的，要把他趕出會堂。",
   "en": "His parents said these things because they feared the Jews; for the Jews had already agreed that if any man would confess him as Christ, he would be put out of the synagogue."
  },
  "23": {
   "zh": "因此他父母說：「他已經成了人，你們問他吧。」",
   "en": "Therefore his parents said, “He is of age. Ask him.”"
  },
  "24": {
   "zh": "所以法利賽人第二次叫了那從前瞎眼的人來，對他說：「你該將榮耀歸給神，我們知道這人是個罪人。」",
   "en": "So they called the man who was blind a second time, and said to him, “Give glory to God. We know that this man is a sinner.”"
  },
  "25": {
   "zh": "他說：「他是個罪人不是，我不知道；有一件事我知道，從前我是眼瞎的，如今能看見了。」",
   "en": "He therefore answered, “I don’t know if he is a sinner. One thing I do know: that though I was blind, now I see.”"
  },
  "26": {
   "zh": "他們就問他說：「他向你做甚麼？是怎麼開了你的眼睛呢？」",
   "en": "They said to him again, “What did he do to you? How did he open your eyes?”"
  },
  "27": {
   "zh": "他回答說：「我方才告訴你們，你們不聽，為甚麼又要聽呢？莫非你們也要作他的門徒嗎？」",
   "en": "He answered them, “I told you already, and you didn’t listen. Why do you want to hear it again? You don’t also want to become his disciples, do you?”"
  },
  "28": {
   "zh": "他們就罵他說：「你是他的門徒；我們是摩西的門徒。",
   "en": "They insulted him and said, “You are his disciple, but we are disciples of Moses."
  },
  "29": {
   "zh": "神對摩西說話是我們知道的；只是這個人，我們不知道他從哪裡來！」",
   "en": "We know that God has spoken to Moses. But as for this man, we don’t know where he comes from.”"
  },
  "30": {
   "zh": "那人回答說：「他開了我的眼睛，你們竟不知道他從哪裡來，這真是奇怪！",
   "en": "The man answered them, “How amazing! You don’t know where he comes from, yet he opened my eyes."
  },
  "31": {
   "zh": "我們知道神不聽罪人，惟有敬奉神、遵行他旨意的，神才聽他。",
   "en": "We know that God doesn’t listen to sinners, but if anyone is a worshiper of God, and does his will, he listens to him."
  },
  "32": {
   "zh": "從創世以來，未曾聽見有人把生來是瞎子的眼睛開了。",
   "en": "Since the world began it has never been heard of that anyone opened the eyes of someone born blind."
  },
  "33": {
   "zh": "這人若不是從神來的，甚麼也不能做。」",
   "en": "If this man were not from God, he could do nothing.”"
  },
  "34": {
   "zh": "他們回答說：「你全然生在罪孽中，還要教訓我們嗎？」於是把他趕出去了。",
   "en": "They answered him, “You were altogether born in sins, and do you teach us?” They threw him out."
  },
  "35": {
   "zh": "耶穌聽說他們把他趕出去，後來遇見他，就說：「你信神的兒子嗎？」",
   "en": "Jesus heard that they had thrown him out, and finding him, he said, “Do you believe in the Son of God?”"
  },
  "36": {
   "zh": "他回答說：「主啊，誰是神的兒子，叫我信他呢？」",
   "en": "He answered, “Who is he, Lord, that I may believe in him?”"
  },
  "37": {
   "zh": "耶穌說：「你已經看見他，現在和你說話的就是他。」",
   "en": "Jesus said to him, “You have both seen him, and it is he who speaks with you.”"
  },
  "38": {
   "zh": "他說：「主啊，我信！」就拜耶穌。",
   "en": "He said, “Lord, I believe!” and he worshiped him."
  },
  "39": {
   "zh": "耶穌說：「我為審判到這世上來，叫不能看見的，可以看見；能看見的，反瞎了眼。」",
   "en": "Jesus said, “I came into this world for judgment, that those who don’t see may see; and that those who see may become blind.”"
  },
  "40": {
   "zh": "同他在那裡的法利賽人聽見這話，就說：「難道我們也瞎了眼嗎？」",
   "en": "Those of the Pharisees who were with him heard these things, and said to him, “Are we also blind?”"
  },
  "41": {
   "zh": "耶穌對他們說：「你們若瞎了眼，就沒有罪了；但如今你們說『我們能看見』，所以你們的罪還在。」",
   "en": "Jesus said to them, “If you were blind, you would have no sin; but now you say, ‘We see.’ Therefore your sin remains."
  }
 },
 "10": {
  "1": {
   "zh": "「我實實在在地告訴你們，人進羊圈，不從門進去，倒從別處爬進去，那人就是賊，就是強盜。",
   "en": "“Most certainly, I tell you, one who doesn’t enter by the door into the sheep fold, but climbs up some other way, the same is a thief and a robber."
  },
  "2": {
   "zh": "從門進去的，才是羊的牧人。",
   "en": "But one who enters in by the door is the shepherd of the sheep."
  },
  "3": {
   "zh": "看門的就給他開門；羊也聽他的聲音。他按著名叫自己的羊，把羊領出來。",
   "en": "The gatekeeper opens the gate for him, and the sheep listen to his voice. He calls his own sheep by name, and leads them out."
  },
  "4": {
   "zh": "既放出自己的羊來，就在前頭走，羊也跟著他，因為認得他的聲音。",
   "en": "Whenever he brings out his own sheep, he goes before them, and the sheep follow him, for they know his voice."
  },
  "5": {
   "zh": "羊不跟著生人；因為不認得他的聲音，必要逃跑。」",
   "en": "They will by no means follow a stranger, but will flee from him; for they don’t know the voice of strangers.”"
  },
  "6": {
   "zh": "耶穌將這比喻告訴他們，但他們不明白所說的是甚麼意思。",
   "en": "Jesus spoke this parable to them, but they didn’t understand what he was telling them."
  },
  "7": {
   "zh": "所以，耶穌又對他們說：「我實實在在地告訴你們，我就是羊的門。",
   "en": "Jesus therefore said to them again, “Most certainly, I tell you, I am the sheep’s door."
  },
  "8": {
   "zh": "凡在我以先來的都是賊，是強盜；羊卻不聽他們。",
   "en": "All who came before me are thieves and robbers, but the sheep didn’t listen to them."
  },
  "9": {
   "zh": "我就是門；凡從我進來的，必然得救，並且出入得草吃。",
   "en": "I am the door. If anyone enters in by me, he will be saved, and will go in and go out, and will find pasture."
  },
  "10": {
   "zh": "盜賊來，無非要偷竊，殺害，毀壞；我來了，是要叫羊（或譯：人）得生命，並且得的更豐盛。",
   "en": "The thief only comes to steal, kill, and destroy. I came that they may have life, and may have it abundantly."
  },
  "11": {
   "zh": "我是好牧人；好牧人為羊捨命。",
   "en": "I am the good shepherd. The good shepherd lays down his life for the sheep."
  },
  "12": {
   "zh": "若是雇工，不是牧人，羊也不是他自己的，他看見狼來，就撇下羊逃走；狼抓住羊，趕散了羊群。",
   "en": "He who is a hired hand, and not a shepherd, who doesn’t own the sheep, sees the wolf coming, leaves the sheep, and flees. The wolf snatches the sheep, and scatters them."
  },
  "13": {
   "zh": "雇工逃走，因他是雇工，並不顧念羊。",
   "en": "The hired hand flees because he is a hired hand, and doesn’t care for the sheep."
  },
  "14": {
   "zh": "我是好牧人；我認識我的羊，我的羊也認識我，",
   "en": "I am the good shepherd. I know my own, and I’m known by my own;"
  },
  "15": {
   "zh": "正如父認識我，我也認識父一樣；並且我為羊捨命。",
   "en": "even as the Father knows me, and I know the Father. I lay down my life for the sheep."
  },
  "16": {
   "zh": "我另外有羊，不是這圈裡的；我必須領他們來，他們也要聽我的聲音，並且要合成一群，歸一個牧人了。",
   "en": "I have other sheep, which are not of this fold. I must bring them also, and they will hear my voice. They will become one flock with one shepherd."
  },
  "17": {
   "zh": "我父愛我；因我將命捨去，好再取回來。",
   "en": "Therefore the Father loves me, because I lay down my life, that I may take it again."
  },
  "18": {
   "zh": "沒有人奪我的命去，是我自己捨的。我有權柄捨了，也有權柄取回來。這是我從我父所受的命令。」",
   "en": "No one takes it away from me, but I lay it down by myself. I have power to lay it down, and I have power to take it again. I received this commandment from my Father.”"
  },
  "19": {
   "zh": "猶太人為這些話又起了紛爭。",
   "en": "Therefore a division arose again among the Jews because of these words."
  },
  "20": {
   "zh": "內中有好些人說：「他是被鬼附著，而且瘋了，為甚麼聽他呢？」",
   "en": "Many of them said, “He has a demon, and is insane! Why do you listen to him?”"
  },
  "21": {
   "zh": "又有人說：「這不是鬼附之人所說的話。鬼豈能叫瞎子的眼睛開了呢？」",
   "en": "Others said, “These are not the sayings of one possessed by a demon. It isn’t possible for a demon to open the eyes of the blind, is it?”"
  },
  "22": {
   "zh": "在耶路撒冷有修殿節，是冬天的時候。",
   "en": "It was the Feast of the Dedication at Jerusalem."
  },
  "23": {
   "zh": "耶穌在殿裡所羅門的廊下行走。",
   "en": "It was winter, and Jesus was walking in the temple, in Solomon’s porch."
  },
  "24": {
   "zh": "猶太人圍著他，說：「你叫我們猶疑不定到幾時呢？你若是基督，就明明地告訴我們。」",
   "en": "The Jews therefore came around him and said to him, “How long will you hold us in suspense? If you are the Christ, tell us plainly.”"
  },
  "25": {
   "zh": "耶穌回答說：「我已經告訴你們，你們不信。我奉我父之名所行的事可以為我作見證；",
   "en": "Jesus answered them, “I told you, and you don’t believe. The works that I do in my Father’s name, these testify about me."
  },
  "26": {
   "zh": "只是你們不信，因為你們不是我的羊。",
   "en": "But you don’t believe, because you are not of my sheep, as I told you."
  },
  "27": {
   "zh": "我的羊聽我的聲音，我也認識他們，他們也跟著我。",
   "en": "My sheep hear my voice, and I know them, and they follow me."
  },
  "28": {
   "zh": "我又賜給他們永生；他們永不滅亡，誰也不能從我手裡把他們奪去。",
   "en": "I give eternal life to them. They will never perish, and no one will snatch them out of my hand."
  },
  "29": {
   "zh": "我父把羊賜給我，他比萬有都大，誰也不能從我父手裡把他們奪去。",
   "en": "My Father, who has given them to me, is greater than all. No one is able to snatch them out of my Father’s hand."
  },
  "30": {
   "zh": "我與父原為一。」",
   "en": "I and the Father are one.”"
  },
  "31": {
   "zh": "猶太人又拿起石頭來要打他。",
   "en": "Therefore Jews took up stones again to stone him."
  },
  "32": {
   "zh": "耶穌對他們說：「我從父顯出許多善事給你們看，你們是為哪一件拿石頭打我呢？」",
   "en": "Jesus answered them, “I have shown you many good works from my Father. For which of those works do you stone me?”"
  },
  "33": {
   "zh": "猶太人回答說：「我們不是為善事拿石頭打你，是為你說僭妄的話；又為你是個人，反將自己當作神。」",
   "en": "The Jews answered him, “We don’t stone you for a good work, but for blasphemy: because you, being a man, make yourself God.”"
  },
  "34": {
   "zh": "耶穌說：「你們的律法上豈不是寫著『我曾說你們是神』嗎？",
   "en": "Jesus answered them, “Isn’t it written in your law, ‘I said, you are gods?’"
  },
  "35": {
   "zh": "經上的話是不能廢的；若那些承受神道的人尚且稱為神，",
   "en": "If he called them gods, to whom the word of God came (and the Scripture can’t be broken),"
  },
  "36": {
   "zh": "父所分別為聖、又差到世間來的，他自稱是神的兒子，你們還向他說『你說僭妄的話』嗎？",
   "en": "do you say of him whom the Father sanctified and sent into the world, ‘You blaspheme,’ because I said, ‘I am the Son of God?’"
  },
  "37": {
   "zh": "我若不行我父的事，你們就不必信我；",
   "en": "If I don’t do the works of my Father, don’t believe me."
  },
  "38": {
   "zh": "我若行了，你們縱然不信我，也當信這些事，叫你們又知道又明白父在我裡面，我也在父裡面。」",
   "en": "But if I do them, though you don’t believe me, believe the works; that you may know and believe that the Father is in me, and I in the Father.”"
  },
  "39": {
   "zh": "他們又要拿他，他卻逃出他們的手走了。",
   "en": "They sought again to seize him, and he went out of their hand."
  },
  "40": {
   "zh": "耶穌又往約旦河外去，到了約翰起初施洗的地方，就住在那裡。",
   "en": "He went away again beyond the Jordan into the place where John was baptizing at first, and there he stayed."
  },
  "41": {
   "zh": "有許多人來到他那裡。他們說：「約翰一件神蹟沒有行過，但約翰指著這人所說的一切話都是真的。」",
   "en": "Many came to him. They said, “John indeed did no sign, but everything that John said about this man is true.”"
  },
  "42": {
   "zh": "在那裡，信耶穌的人就多了。",
   "en": "Many believed in him there."
  }
 },
 "11": {
  "1": {
   "zh": "有一個患病的人，名叫拉撒路，住在伯大尼，就是馬利亞和她姊姊馬大的村莊。",
   "en": "Now a certain man was sick, Lazarus from Bethany, of the village of Mary and her sister, Martha."
  },
  "2": {
   "zh": "這馬利亞就是那用香膏抹主，又用頭髮擦他腳的；患病的拉撒路是她的兄弟。",
   "en": "It was that Mary who had anointed the Lord with ointment, and wiped his feet with her hair, whose brother, Lazarus, was sick."
  },
  "3": {
   "zh": "她姊妹兩個就打發人去見耶穌，說：「主啊，你所愛的人病了。」",
   "en": "The sisters therefore sent to him, saying, “Lord, behold, he for whom you have great affection is sick.”"
  },
  "4": {
   "zh": "耶穌聽見，就說：「這病不至於死，乃是為神的榮耀，叫神的兒子因此得榮耀。」",
   "en": "But when Jesus heard it, he said, “This sickness is not to death, but for the glory of God, that God’s Son may be glorified by it.”"
  },
  "5": {
   "zh": "耶穌素來愛馬大和她妹子並拉撒路。",
   "en": "Now Jesus loved Martha, and her sister, and Lazarus."
  },
  "6": {
   "zh": "聽見拉撒路病了，就在所居之地仍住了兩天。",
   "en": "When therefore he heard that he was sick, he stayed two days in the place where he was."
  },
  "7": {
   "zh": "然後對門徒說：「我們再往猶太去吧。」",
   "en": "Then after this he said to the disciples, “Let’s go into Judea again.”"
  },
  "8": {
   "zh": "門徒說：「拉比，猶太人近來要拿石頭打你，你還往那裡去嗎？」",
   "en": "The disciples told him, “Rabbi, the Jews were just trying to stone you, and are you going there again?”"
  },
  "9": {
   "zh": "耶穌回答說：「白日不是有十二小時嗎？人在白日走路，就不至跌倒，因為看見這世上的光。",
   "en": "Jesus answered, “Aren’t there twelve hours of daylight? If a man walks in the day, he doesn’t stumble, because he sees the light of this world."
  },
  "10": {
   "zh": "若在黑夜走路，就必跌倒，因為他沒有光。」",
   "en": "But if a man walks in the night, he stumbles, because the light isn’t in him.”"
  },
  "11": {
   "zh": "耶穌說了這話，隨後對他們說：「我們的朋友拉撒路睡了，我去叫醒他。」",
   "en": "He said these things, and after that, he said to them, “Our friend, Lazarus, has fallen asleep, but I am going so that I may awake him out of sleep.”"
  },
  "12": {
   "zh": "門徒說：「主啊，他若睡了，就必好了。」",
   "en": "The disciples therefore said, “Lord, if he has fallen asleep, he will recover.”"
  },
  "13": {
   "zh": "耶穌這話是指著他死說的，他們卻以為是說照常睡了。",
   "en": "Now Jesus had spoken of his death, but they thought that he spoke of taking rest in sleep."
  },
  "14": {
   "zh": "耶穌就明明地告訴他們說：「拉撒路死了。",
   "en": "So Jesus said to them plainly then, “Lazarus is dead."
  },
  "15": {
   "zh": "我沒有在那裡就歡喜，這是為你們的緣故，好叫你們相信。如今我們可以往他那裡去吧。」",
   "en": "I am glad for your sakes that I was not there, so that you may believe. Nevertheless, let’s go to him.”"
  },
  "16": {
   "zh": "多馬，又稱為低土馬，就對那同作門徒的說：「我們也去和他同死吧。」",
   "en": "Thomas therefore, who is called Didymus, said to his fellow disciples, “Let’s go also, that we may die with him.”"
  },
  "17": {
   "zh": "耶穌到了，就知道拉撒路在墳墓裡已經四天了。",
   "en": "So when Jesus came, he found that he had been in the tomb four days already."
  },
  "18": {
   "zh": "伯大尼離耶路撒冷不遠，約有六里路。",
   "en": "Now Bethany was near Jerusalem, about fifteen stadia away."
  },
  "19": {
   "zh": "有好些猶太人來看馬大和馬利亞，要為她們的兄弟安慰她們。",
   "en": "Many of the Jews had joined the women around Martha and Mary, to console them concerning their brother."
  },
  "20": {
   "zh": "馬大聽見耶穌來了，就出去迎接他；馬利亞卻仍然坐在家裡。",
   "en": "Then when Martha heard that Jesus was coming, she went and met him, but Mary stayed in the house."
  },
  "21": {
   "zh": "馬大對耶穌說：「主啊，你若早在這裡，我兄弟必不死。",
   "en": "Therefore Martha said to Jesus, “Lord, if you would have been here, my brother wouldn’t have died."
  },
  "22": {
   "zh": "就是現在，我也知道，你無論向神求甚麼，神也必賜給你。」",
   "en": "Even now I know that, whatever you ask of God, God will give you.”"
  },
  "23": {
   "zh": "耶穌說：「你兄弟必然復活。」",
   "en": "Jesus said to her, “Your brother will rise again.”"
  },
  "24": {
   "zh": "馬大說：「我知道在末日復活的時候，他必復活。」",
   "en": "Martha said to him, “I know that he will rise again in the resurrection at the last day.”"
  },
  "25": {
   "zh": "耶穌對她說：「復活在我，生命也在我。信我的人雖然死了，也必復活；",
   "en": "Jesus said to her, “I am the resurrection and the life. He who believes in me will still live, even if he dies."
  },
  "26": {
   "zh": "凡活著信我的人必永遠不死。你信這話嗎？」",
   "en": "Whoever lives and believes in me will never die. Do you believe this?”"
  },
  "27": {
   "zh": "馬大說：「主啊，是的，我信你是基督，是神的兒子，就是那要臨到世界的。」",
   "en": "She said to him, “Yes, Lord. I have come to believe that you are the Christ, God’s Son, he who comes into the world.”"
  },
  "28": {
   "zh": "馬大說了這話，就回去暗暗地叫她妹子馬利亞，說：「夫子來了，叫你。」",
   "en": "When she had said this, she went away, and called Mary, her sister, secretly, saying, “The Teacher is here, and is calling you.”"
  },
  "29": {
   "zh": "馬利亞聽見了，就急忙起來，到耶穌那裡去。",
   "en": "When she heard this, she arose quickly, and went to him."
  },
  "30": {
   "zh": "那時，耶穌還沒有進村子，仍在馬大迎接他的地方。",
   "en": "Now Jesus had not yet come into the village, but was in the place where Martha met him."
  },
  "31": {
   "zh": "那些同馬利亞在家裡安慰她的猶太人，見她急忙起來出去，就跟著她，以為她要往墳墓那裡去哭。",
   "en": "Then the Jews who were with her in the house, and were consoling her, when they saw Mary, that she rose up quickly and went out, followed her, saying, “She is going to the tomb to weep there.”"
  },
  "32": {
   "zh": "馬利亞到了耶穌那裡，看見他，就俯伏在他腳前，說：「主啊，你若早在這裡，我兄弟必不死。」",
   "en": "Therefore when Mary came to where Jesus was, and saw him, she fell down at his feet, saying to him, “Lord, if you would have been here, my brother wouldn’t have died.”"
  },
  "33": {
   "zh": "耶穌看見她哭，並看見與她同來的猶太人也哭，就心裡悲歎，又甚憂愁，",
   "en": "When Jesus therefore saw her weeping, and the Jews weeping who came with her, he groaned in the spirit, and was troubled,"
  },
  "34": {
   "zh": "便說：「你們把他安放在哪裡？」他們回答說：「請主來看。」",
   "en": "and said, “Where have you laid him?” They told him, “Lord, come and see.”"
  },
  "35": {
   "zh": "耶穌哭了。",
   "en": "Jesus wept."
  },
  "36": {
   "zh": "猶太人就說：「你看他愛這人是何等懇切。」",
   "en": "The Jews therefore said, “See how much affection he had for him!”"
  },
  "37": {
   "zh": "其中有人說：「他既然開了瞎子的眼睛，豈不能叫這人不死嗎？」",
   "en": "Some of them said, “Couldn’t this man, who opened the eyes of him who was blind, have also kept this man from dying?”"
  },
  "38": {
   "zh": "耶穌又心裡悲歎，來到墳墓前；那墳墓是個洞，有一塊石頭擋著。",
   "en": "Jesus therefore, again groaning in himself, came to the tomb. Now it was a cave, and a stone lay against it."
  },
  "39": {
   "zh": "耶穌說：「你們把石頭挪開。」那死人的姊姊馬大對他說：「主啊，他現在必是臭了，因為他死了已經四天了。」",
   "en": "Jesus said, “Take away the stone.” Martha, the sister of him who was dead, said to him, “Lord, by this time there is a stench, for he has been dead four days.”"
  },
  "40": {
   "zh": "耶穌說：「我不是對你說過，你若信，就必看見神的榮耀嗎？」",
   "en": "Jesus said to her, “Didn’t I tell you that if you believed, you would see God’s glory?”"
  },
  "41": {
   "zh": "他們就把石頭挪開。耶穌舉目望天，說：「父啊，我感謝你，因為你已經聽我。",
   "en": "So they took away the stone from the place where the dead man was lying. Jesus lifted up his eyes, and said, “Father, I thank you that you listened to me."
  },
  "42": {
   "zh": "我也知道你常聽我，但我說這話是為周圍站著的眾人，叫他們信是你差了我來。」",
   "en": "I know that you always listen to me, but because of the multitude standing around I said this, that they may believe that you sent me.”"
  },
  "43": {
   "zh": "說了這話，就大聲呼叫說：「拉撒路出來！」",
   "en": "When he had said this, he cried with a loud voice, “Lazarus, come out!”"
  },
  "44": {
   "zh": "那死人就出來了，手腳裹著布，臉上包著手巾。耶穌對他們說：「解開，叫他走！」",
   "en": "He who was dead came out, bound hand and foot with wrappings, and his face was wrapped around with a cloth. Jesus said to them, “Free him, and let him go.”"
  },
  "45": {
   "zh": "那些來看馬利亞的猶太人見了耶穌所做的事，就多有信他的；",
   "en": "Therefore many of the Jews, who came to Mary and saw what Jesus did, believed in him."
  },
  "46": {
   "zh": "但其中也有去見法利賽人的，將耶穌所做的事告訴他們。",
   "en": "But some of them went away to the Pharisees, and told them the things which Jesus had done."
  },
  "47": {
   "zh": "祭司長和法利賽人聚集公會，說：「這人行好些神蹟，我們怎麼辦呢？",
   "en": "The chief priests therefore and the Pharisees gathered a council, and said, “What are we doing? For this man does many signs."
  },
  "48": {
   "zh": "若這樣由著他，人人都要信他，羅馬人也要來奪我們的地土和我們的百姓。」",
   "en": "If we leave him alone like this, everyone will believe in him, and the Romans will come and take away both our place and our nation.”"
  },
  "49": {
   "zh": "內中有一個人，名叫該亞法，本年作大祭司，對他們說：「你們不知道甚麼。",
   "en": "But a certain one of them, Caiaphas, being high priest that year, said to them, “You know nothing at all,"
  },
  "50": {
   "zh": "獨不想一個人替百姓死，免得通國滅亡，就是你們的益處。」",
   "en": "nor do you consider that it is advantageous for us that one man should die for the people, and that the whole nation not perish.”"
  },
  "51": {
   "zh": "他這話不是出於自己，是因他本年作大祭司，所以預言耶穌將要替這一國死；",
   "en": "Now he didn’t say this of himself, but being high priest that year, he prophesied that Jesus would die for the nation,"
  },
  "52": {
   "zh": "也不但替這一國死，並要將神四散的子民都聚集歸一。",
   "en": "and not for the nation only, but that he might also gather together into one the children of God who are scattered abroad."
  },
  "53": {
   "zh": "從那日起，他們就商議要殺耶穌。",
   "en": "So from that day forward they took counsel that they might put him to death."
  },
  "54": {
   "zh": "所以，耶穌不再顯然行在猶太人中間，就離開那裡往靠近曠野的地方去，到了一座城，名叫以法蓮，就在那裡和門徒同住。",
   "en": "Jesus therefore walked no more openly among the Jews, but departed from there into the country near the wilderness, to a city called Ephraim. He stayed there with his disciples."
  },
  "55": {
   "zh": "猶太人的逾越節近了，有許多人從鄉下上耶路撒冷去，要在節前潔淨自己。",
   "en": "Now the Passover of the Jews was at hand. Many went up from the country to Jerusalem before the Passover, to purify themselves."
  },
  "56": {
   "zh": "他們就尋找耶穌，站在殿裡彼此說：「你們的意思如何，他不來過節嗎？」",
   "en": "Then they sought for Jesus and spoke one with another, as they stood in the temple, “What do you think—that he isn’t coming to the feast at all?”"
  },
  "57": {
   "zh": "那時，祭司長和法利賽人早已吩咐說，若有人知道耶穌在哪裡，就要報明，好去拿他。",
   "en": "Now the chief priests and the Pharisees had commanded that if anyone knew where he was, he should report it, that they might seize him."
  }
 },
 "12": {
  "1": {
   "zh": "逾越節前六日，耶穌來到伯大尼，就是他叫拉撒路從死裡復活之處。",
   "en": "Then six days before the Passover, Jesus came to Bethany, where Lazarus was, who had been dead, whom he raised from the dead."
  },
  "2": {
   "zh": "有人在那裡給耶穌預備筵席；馬大伺候，拉撒路也在那同耶穌坐席的人中。",
   "en": "So they made him a supper there. Martha served, but Lazarus was one of those who sat at the table with him."
  },
  "3": {
   "zh": "馬利亞就拿著一斤極貴的真哪噠香膏，抹耶穌的腳，又用自己頭髮去擦，屋裡就滿了膏的香氣。",
   "en": "Mary, therefore, took a pound of ointment of pure nard, very precious, and anointed the feet of Jesus, and wiped his feet with her hair. The house was filled with the fragrance of the ointment."
  },
  "4": {
   "zh": "有一個門徒，就是那將要賣耶穌的加略人猶大，",
   "en": "Then Judas Iscariot, Simon’s son, one of his disciples, who would betray him, said,"
  },
  "5": {
   "zh": "說：「這香膏為甚麼不賣三十兩銀子賙濟窮人呢？」",
   "en": "“Why wasn’t this ointment sold for three hundred denarii, and given to the poor?”"
  },
  "6": {
   "zh": "他說這話，並不是掛念窮人，乃因他是個賊，又帶著錢囊，常取其中所存的。",
   "en": "Now he said this, not because he cared for the poor, but because he was a thief, and having the money box, used to steal what was put into it."
  },
  "7": {
   "zh": "耶穌說：「由她吧！她是為我安葬之日存留的。",
   "en": "But Jesus said, “Leave her alone. She has kept this for the day of my burial."
  },
  "8": {
   "zh": "因為常有窮人和你們同在，只是你們不常有我。」",
   "en": "For you always have the poor with you, but you don’t always have me.”"
  },
  "9": {
   "zh": "有許多猶太人知道耶穌在那裡，就來了，不但是為耶穌的緣故，也是要看他從死裡所復活的拉撒路。",
   "en": "A large crowd therefore of the Jews learned that he was there, and they came, not for Jesus’ sake only, but that they might see Lazarus also, whom he had raised from the dead."
  },
  "10": {
   "zh": "但祭司長商議連拉撒路也要殺了；",
   "en": "But the chief priests conspired to put Lazarus to death also,"
  },
  "11": {
   "zh": "因有好些猶太人為拉撒路的緣故，回去信了耶穌。",
   "en": "because on account of him many of the Jews went away and believed in Jesus."
  },
  "12": {
   "zh": "第二天，有許多上來過節的人聽見耶穌將到耶路撒冷，",
   "en": "On the next day a great multitude had come to the feast. When they heard that Jesus was coming to Jerusalem,"
  },
  "13": {
   "zh": "就拿著棕樹枝出去迎接他，喊著說：和散那！奉主名來的以色列王是應當稱頌的！",
   "en": "they took the branches of the palm trees, and went out to meet him, and cried out, “Hosanna! Blessed is he who comes in the name of the Lord, the King of Israel!”"
  },
  "14": {
   "zh": "耶穌得了一個驢駒，就騎上，如經上所記的說：",
   "en": "Jesus, having found a young donkey, sat on it. As it is written,"
  },
  "15": {
   "zh": "錫安的民（原文是女子）哪，不要懼怕！你的王騎著驢駒來了。",
   "en": "“Don’t be afraid, daughter of Zion. Behold, your King comes, sitting on a donkey’s colt.”"
  },
  "16": {
   "zh": "這些事門徒起先不明白，等到耶穌得了榮耀以後才想起這話是指著他寫的，並且眾人果然向他這樣行了。",
   "en": "His disciples didn’t understand these things at first, but when Jesus was glorified, then they remembered that these things were written about him, and that they had done these things to him."
  },
  "17": {
   "zh": "當耶穌呼喚拉撒路，叫他從死復活出墳墓的時候，同耶穌在那裡的眾人就作見證。",
   "en": "The multitude therefore that was with him when he called Lazarus out of the tomb, and raised him from the dead, was testifying about it."
  },
  "18": {
   "zh": "眾人因聽見耶穌行了這神蹟，就去迎接他。",
   "en": "For this cause also the multitude went and met him, because they heard that he had done this sign."
  },
  "19": {
   "zh": "法利賽人彼此說：「看哪，你們是徒勞無益，世人都隨從他去了。」",
   "en": "The Pharisees therefore said among themselves, “See how you accomplish nothing. Behold, the world has gone after him.”"
  },
  "20": {
   "zh": "那時，上來過節禮拜的人中，有幾個希臘人。",
   "en": "Now there were certain Greeks among those that went up to worship at the feast."
  },
  "21": {
   "zh": "他們來見加利利伯賽大的腓力，求他說：「先生，我們願意見耶穌。」",
   "en": "These, therefore, came to Philip, who was from Bethsaida of Galilee, and asked him, saying, “Sir, we want to see Jesus.”"
  },
  "22": {
   "zh": "腓力去告訴安得烈，安得烈同腓力去告訴耶穌。",
   "en": "Philip came and told Andrew, and in turn, Andrew came with Philip, and they told Jesus."
  },
  "23": {
   "zh": "耶穌說：「人子得榮耀的時候到了。",
   "en": "Jesus answered them, “The time has come for the Son of Man to be glorified."
  },
  "24": {
   "zh": "我實實在在地告訴你們，一粒麥子不落在地裡死了，仍舊是一粒，若是死了，就結出許多子粒來。",
   "en": "Most certainly I tell you, unless a grain of wheat falls into the earth and dies, it remains by itself alone. But if it dies, it bears much fruit."
  },
  "25": {
   "zh": "愛惜自己生命的，就失喪生命；在這世上恨惡自己生命的，就要保守生命到永生。",
   "en": "He who loves his life will lose it. He who hates his life in this world will keep it to eternal life."
  },
  "26": {
   "zh": "若有人服事我，就當跟從我；我在哪裡，服事我的人也要在那裡；若有人服事我，我父必尊重他。」",
   "en": "If anyone serves me, let him follow me. Where I am, there will my servant also be. If anyone serves me, the Father will honor him."
  },
  "27": {
   "zh": "「我現在心裡憂愁，我說甚麼才好呢？父啊，救我脫離這時候；但我原是為這時候來的。",
   "en": "“Now my soul is troubled. What shall I say? ‘Father, save me from this time?’ But for this cause I came to this time."
  },
  "28": {
   "zh": "父啊，願你榮耀你的名！」當時就有聲音從天上來，說：「我已經榮耀了我的名，還要再榮耀。」",
   "en": "Father, glorify your name!” Then there came a voice out of the sky, saying, “I have both glorified it, and will glorify it again.”"
  },
  "29": {
   "zh": "站在旁邊的眾人聽見，就說：「打雷了。」還有人說：「有天使對他說話。」",
   "en": "The multitude therefore, who stood by and heard it, said that it had thundered. Others said, “An angel has spoken to him.”"
  },
  "30": {
   "zh": "耶穌說：「這聲音不是為我，是為你們來的。",
   "en": "Jesus answered, “This voice hasn’t come for my sake, but for your sakes."
  },
  "31": {
   "zh": "現在這世界受審判，這世界的王要被趕出去。",
   "en": "Now is the judgment of this world. Now the prince of this world will be cast out."
  },
  "32": {
   "zh": "我若從地上被舉起來，就要吸引萬人來歸我。」",
   "en": "And I, if I am lifted up from the earth, will draw all people to myself.”"
  },
  "33": {
   "zh": "耶穌這話原是指著自己將要怎樣死說的。",
   "en": "But he said this, signifying by what kind of death he should die."
  },
  "34": {
   "zh": "眾人回答說：「我們聽見律法上有話說，基督是永存的，你怎麼說『人子必須被舉起來』呢？這人子是誰呢？」",
   "en": "The multitude answered him, “We have heard out of the law that the Christ remains forever. How do you say, ‘The Son of Man must be lifted up?’ Who is this Son of Man?”"
  },
  "35": {
   "zh": "耶穌對他們說：「光在你們中間還有不多的時候，應當趁著有光行走，免得黑暗臨到你們；那在黑暗裡行走的，不知道往何處去。",
   "en": "Jesus therefore said to them, “Yet a little while the light is with you. Walk while you have the light, that darkness doesn’t overtake you. He who walks in the darkness doesn’t know where he is going."
  },
  "36": {
   "zh": "你們應當趁著有光，信從這光，使你們成為光明之子。」耶穌說了這話，就離開他們隱藏了。",
   "en": "While you have the light, believe in the light, that you may become children of light.” Jesus said these things, and he departed and hid himself from them."
  },
  "37": {
   "zh": "他雖然在他們面前行了許多神蹟，他們還是不信他。",
   "en": "But though he had done so many signs before them, yet they didn’t believe in him,"
  },
  "38": {
   "zh": "這是要應驗先知以賽亞的話，說：主啊，我們所傳的有誰信呢？主的膀臂向誰顯露呢？",
   "en": "that the word of Isaiah the prophet might be fulfilled, which he spoke, “Lord, who has believed our report? To whom has the arm of the Lord been revealed?”"
  },
  "39": {
   "zh": "他們所以不能信，因為以賽亞又說：",
   "en": "For this cause they couldn’t believe, for Isaiah said again,"
  },
  "40": {
   "zh": "主叫他們瞎了眼，硬了心，免得他們眼睛看見，心裡明白，回轉過來，我就醫治他們。",
   "en": "“He has blinded their eyes and he hardened their heart, lest they should see with their eyes, and perceive with their heart, and would turn, and I would heal them.”"
  },
  "41": {
   "zh": "以賽亞因為看見他的榮耀，就指著他說這話。",
   "en": "Isaiah said these things when he saw his glory, and spoke of him."
  },
  "42": {
   "zh": "雖然如此，官長中卻有好些信他的，只因法利賽人的緣故，就不承認，恐怕被趕出會堂。",
   "en": "Nevertheless even of the rulers many believed in him, but because of the Pharisees they didn’t confess it, so that they wouldn’t be put out of the synagogue,"
  },
  "43": {
   "zh": "這是因他們愛人的榮耀過於愛神的榮耀。",
   "en": "for they loved men’s praise more than God’s praise."
  },
  "44": {
   "zh": "耶穌大聲說：「信我的，不是信我，乃是信那差我來的。",
   "en": "Jesus cried out and said, “Whoever believes in me, believes not in me, but in him who sent me."
  },
  "45": {
   "zh": "人看見我，就是看見那差我來的。",
   "en": "He who sees me sees him who sent me."
  },
  "46": {
   "zh": "我到世上來，乃是光，叫凡信我的，不住在黑暗裡。",
   "en": "I have come as a light into the world, that whoever believes in me may not remain in the darkness."
  },
  "47": {
   "zh": "若有人聽見我的話不遵守，我不審判他。我來本不是要審判世界，乃是要拯救世界。",
   "en": "If anyone listens to my sayings, and doesn’t believe, I don’t judge him. For I came not to judge the world, but to save the world."
  },
  "48": {
   "zh": "棄絕我、不領受我話的人，有審判他的─就是我所講的道在末日要審判他。",
   "en": "He who rejects me, and doesn’t receive my sayings, has one who judges him. The word that I spoke, the same will judge him in the last day."
  },
  "49": {
   "zh": "因為我沒有憑著自己講，惟有差我來的父已經給我命令，叫我說甚麼，講甚麼。",
   "en": "For I spoke not from myself, but the Father who sent me, he gave me a commandment, what I should say, and what I should speak."
  },
  "50": {
   "zh": "我也知道他的命令就是永生。故此，我所講的話正是照著父對我所說的。」",
   "en": "I know that his commandment is eternal life. The things therefore which I speak, even as the Father has said to me, so I speak.”"
  }
 },
 "13": {
  "1": {
   "zh": "逾越節以前，耶穌知道自己離世歸父的時候到了。他既然愛世間屬自己的人，就愛他們到底。",
   "en": "Now before the feast of the Passover, Jesus, knowing that his time had come that he would depart from this world to the Father, having loved his own who were in the world, he loved them to the end."
  },
  "2": {
   "zh": "吃晚飯的時候，魔鬼已將賣耶穌的意思放在西門的兒子加略人猶大心裡。",
   "en": "During supper, the devil having already put into the heart of Judas Iscariot, Simon’s son, to betray him,"
  },
  "3": {
   "zh": "耶穌知道父已將萬有交在他手裡，且知道自己是從神出來的，又要歸到神那裡去，",
   "en": "Jesus, knowing that the Father had given all things into his hands, and that he came from God, and was going to God,"
  },
  "4": {
   "zh": "就離席站起來，脫了衣服，拿一條手巾束腰，",
   "en": "arose from supper, and laid aside his outer garments. He took a towel, and wrapped a towel around his waist."
  },
  "5": {
   "zh": "隨後把水倒在盆裡，就洗門徒的腳，並用自己所束的手巾擦乾。",
   "en": "Then he poured water into the basin, and began to wash the disciples’ feet, and to wipe them with the towel that was wrapped around him."
  },
  "6": {
   "zh": "挨到西門•彼得，彼得對他說：「主啊，你洗我的腳嗎？」",
   "en": "Then he came to Simon Peter. He said to him, “Lord, do you wash my feet?”"
  },
  "7": {
   "zh": "耶穌回答說：「我所做的，你如今不知道，後來必明白。」",
   "en": "Jesus answered him, “You don’t know what I am doing now, but you will understand later.”"
  },
  "8": {
   "zh": "彼得說：「你永不可洗我的腳！」耶穌說：「我若不洗你，你就與我無分了。」",
   "en": "Peter said to him, “You will never wash my feet!” Jesus answered him, “If I don’t wash you, you have no part with me.”"
  },
  "9": {
   "zh": "西門•彼得說：「主啊，不但我的腳，連手和頭也要洗。」",
   "en": "Simon Peter said to him, “Lord, not my feet only, but also my hands and my head!”"
  },
  "10": {
   "zh": "耶穌說：「凡洗過澡的人，只要把腳一洗，全身就乾淨了。你們是乾淨的，然而不都是乾淨的。」",
   "en": "Jesus said to him, “Someone who has bathed only needs to have his feet washed, but is completely clean. You are clean, but not all of you.”"
  },
  "11": {
   "zh": "耶穌原知道要賣他的是誰，所以說：「你們不都是乾淨的。」",
   "en": "For he knew him who would betray him, therefore he said, “You are not all clean.”"
  },
  "12": {
   "zh": "耶穌洗完了他們的腳，就穿上衣服，又坐下，對他們說：「我向你們所做的，你們明白嗎？",
   "en": "So when he had washed their feet, put his outer garment back on, and sat down again, he said to them, “Do you know what I have done to you?"
  },
  "13": {
   "zh": "你們稱呼我夫子，稱呼我主，你們說的不錯，我本來是。",
   "en": "You call me, ‘Teacher’ and ‘Lord.’ You say so correctly, for so I am."
  },
  "14": {
   "zh": "我是你們的主，你們的夫子，尚且洗你們的腳，你們也當彼此洗腳。",
   "en": "If I then, the Lord and the Teacher, have washed your feet, you also ought to wash one another’s feet."
  },
  "15": {
   "zh": "我給你們作了榜樣，叫你們照著我向你們所做的去做。",
   "en": "For I have given you an example, that you also should do as I have done to you."
  },
  "16": {
   "zh": "我實實在在地告訴你們，僕人不能大於主人，差人也不能大於差他的人。",
   "en": "Most certainly I tell you, a servant is not greater than his lord, neither one who is sent greater than he who sent him."
  },
  "17": {
   "zh": "你們既知道這事，若是去行就有福了。",
   "en": "If you know these things, blessed are you if you do them."
  },
  "18": {
   "zh": "我這話不是指著你們眾人說的，我知道我所揀選的是誰。現在要應驗經上的話，說：『同我吃飯的人用腳踢我。』",
   "en": "I don’t speak concerning all of you. I know whom I have chosen. But that the Scripture may be fulfilled, ‘He who eats bread with me has lifted up his heel against me.’"
  },
  "19": {
   "zh": "如今事情還沒有成就，我要先告訴你們，叫你們到事情成就的時候可以信我是基督。",
   "en": "From now on, I tell you before it happens, that when it happens, you may believe that I am he."
  },
  "20": {
   "zh": "我實實在在地告訴你們，有人接待我所差遣的，就是接待我；接待我，就是接待那差遣我的。」",
   "en": "Most certainly I tell you, he who receives whomever I send, receives me; and he who receives me, receives him who sent me.”"
  },
  "21": {
   "zh": "耶穌說了這話，心裡憂愁，就明說：「我實實在在地告訴你們，你們中間有一個人要賣我了。」",
   "en": "When Jesus had said this, he was troubled in spirit, and testified, “Most certainly I tell you that one of you will betray me.”"
  },
  "22": {
   "zh": "門徒彼此對看，猜不透所說的是誰。",
   "en": "The disciples looked at one another, perplexed about whom he spoke."
  },
  "23": {
   "zh": "有一個門徒，是耶穌所愛的，側身挨近耶穌的懷裡。",
   "en": "One of his disciples, whom Jesus loved, was at the table, leaning against Jesus’ breast."
  },
  "24": {
   "zh": "西門•彼得點頭對他說：「你告訴我們，主是指著誰說的。」",
   "en": "Simon Peter therefore beckoned to him, and said to him, “Tell us who it is of whom he speaks.”"
  },
  "25": {
   "zh": "那門徒便就勢靠著耶穌的胸膛，問他說：「主啊，是誰呢？」",
   "en": "He, leaning back, as he was, on Jesus’ breast, asked him, “Lord, who is it?”"
  },
  "26": {
   "zh": "耶穌回答說：「我蘸一點餅給誰，就是誰。」耶穌就蘸了一點餅，遞給加略人西門的兒子猶大。",
   "en": "Jesus therefore answered, “It is he to whom I will give this piece of bread when I have dipped it.” So when he had dipped the piece of bread, he gave it to Judas, the son of Simon Iscariot."
  },
  "27": {
   "zh": "他吃了以後，撒但就入了他的心。耶穌便對他說：「你所做的，快做吧！」",
   "en": "After the piece of bread, then Satan entered into him. Then Jesus said to him, “What you do, do quickly.”"
  },
  "28": {
   "zh": "同席的人沒有一個知道是為甚麼對他說這話。",
   "en": "Now no man at the table knew why he said this to him."
  },
  "29": {
   "zh": "有人因猶大帶著錢囊，以為耶穌是對他說：「你去買我們過節所應用的東西」，或是叫他拿甚麼賙濟窮人。",
   "en": "For some thought, because Judas had the money box, that Jesus said to him, “Buy what things we need for the feast,” or that he should give something to the poor."
  },
  "30": {
   "zh": "猶大受了那點餅，立刻就出去。那時候是夜間了。",
   "en": "Therefore having received that morsel, he went out immediately. It was night."
  },
  "31": {
   "zh": "他既出去，耶穌就說：「如今人子得了榮耀，神在人子身上也得了榮耀。",
   "en": "When he had gone out, Jesus said, “Now the Son of Man has been glorified, and God has been glorified in him."
  },
  "32": {
   "zh": "神要因自己榮耀人子，並且要快快地榮耀他。",
   "en": "If God has been glorified in him, God will also glorify him in himself, and he will glorify him immediately."
  },
  "33": {
   "zh": "小子們，我還有不多的時候與你們同在；後來你們要找我，但我所去的地方你們不能到。這話我曾對猶太人說過，如今也照樣對你們說。",
   "en": "Little children, I will be with you a little while longer. You will seek me, and as I said to the Jews, ‘Where I am going, you can’t come,’ so now I tell you."
  },
  "34": {
   "zh": "我賜給你們一條新命令，乃是叫你們彼此相愛；我怎樣愛你們，你們也要怎樣相愛。",
   "en": "A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another."
  },
  "35": {
   "zh": "你們若有彼此相愛的心，眾人因此就認出你們是我的門徒了。」",
   "en": "By this everyone will know that you are my disciples, if you have love for one another.”"
  },
  "36": {
   "zh": "西門•彼得問耶穌說：「主往哪裡去？」耶穌回答說：「我所去的地方，你現在不能跟我去，後來卻要跟我去。」",
   "en": "Simon Peter said to him, “Lord, where are you going?” Jesus answered, “Where I am going, you can’t follow now, but you will follow afterwards.”"
  },
  "37": {
   "zh": "彼得說：「主啊，我為甚麼現在不能跟你去？我願意為你捨命！」",
   "en": "Peter said to him, “Lord, why can’t I follow you now? I will lay down my life for you.”"
  },
  "38": {
   "zh": "耶穌說：「你願意為我捨命嗎？我實實在在地告訴你，雞叫以先，你要三次不認我。」",
   "en": "Jesus answered him, “Will you lay down your life for me? Most certainly I tell you, the rooster won’t crow until you have denied me three times."
  }
 },
 "14": {
  "1": {
   "zh": "「你們心裡不要憂愁；你們信神，也當信我。",
   "en": "“Don’t let your heart be troubled. Believe in God. Believe also in me."
  },
  "2": {
   "zh": "在我父的家裡有許多住處；若是沒有，我就早已告訴你們了。我去原是為你們預備地方去。",
   "en": "In my Father’s house are many homes. If it weren’t so, I would have told you. I am going to prepare a place for you."
  },
  "3": {
   "zh": "我若去為你們預備了地方，就必再來接你們到我那裡去，我在哪裡，叫你們也在那裡。",
   "en": "If I go and prepare a place for you, I will come again, and will receive you to myself; that where I am, you may be there also."
  },
  "4": {
   "zh": "我往哪裡去，你們知道；那條路，你們也知道（有古卷：我往哪裡去，你們知道那條路）。」",
   "en": "Where I go, you know, and you know the way.”"
  },
  "5": {
   "zh": "多馬對他說：「主啊，我們不知道你往哪裡去，怎麼知道那條路呢？」",
   "en": "Thomas said to him, “Lord, we don’t know where you are going. How can we know the way?”"
  },
  "6": {
   "zh": "耶穌說：「我就是道路、真理、生命；若不藉著我，沒有人能到父那裡去。",
   "en": "Jesus said to him, “I am the way, the truth, and the life. No one comes to the Father, except through me."
  },
  "7": {
   "zh": "你們若認識我，也就認識我的父。從今以後，你們認識他，並且已經看見他。」",
   "en": "If you had known me, you would have known my Father also. From now on, you know him, and have seen him.”"
  },
  "8": {
   "zh": "腓力對他說：「求主將父顯給我們看，我們就知足了。」",
   "en": "Philip said to him, “Lord, show us the Father, and that will be enough for us.”"
  },
  "9": {
   "zh": "耶穌對他說：「腓力，我與你們同在這樣長久，你還不認識我嗎？人看見了我，就是看見了父；你怎麼說『將父顯給我們看』呢？",
   "en": "Jesus said to him, “Have I been with you such a long time, and do you not know me, Philip? He who has seen me has seen the Father. How do you say, ‘Show us the Father?’"
  },
  "10": {
   "zh": "我在父裡面，父在我裡面，你不信嗎？我對你們所說的話，不是憑著自己說的，乃是住在我裡面的父做他自己的事。",
   "en": "Don’t you believe that I am in the Father, and the Father in me? The words that I tell you, I speak not from myself; but the Father who lives in me does his works."
  },
  "11": {
   "zh": "你們當信我，我在父裡面，父在我裡面；即或不信，也當因我所做的事信我。",
   "en": "Believe me that I am in the Father, and the Father in me; or else believe me for the very works’ sake."
  },
  "12": {
   "zh": "我實實在在地告訴你們，我所做的事，信我的人也要做，並且要做比這更大的事，因為我往父那裡去。",
   "en": "Most certainly I tell you, he who believes in me, the works that I do, he will do also; and he will do greater works than these, because I am going to my Father."
  },
  "13": {
   "zh": "你們奉我的名無論求甚麼，我必成就，叫父因兒子得榮耀。",
   "en": "Whatever you will ask in my name, that will I do, that the Father may be glorified in the Son."
  },
  "14": {
   "zh": "你們若奉我的名求甚麼，我必成就。」",
   "en": "If you will ask anything in my name, I will do it."
  },
  "15": {
   "zh": "「你們若愛我，就必遵守我的命令。",
   "en": "If you love me, keep my commandments."
  },
  "16": {
   "zh": "我要求父，父就另外賜給你們一位保惠師（或譯：訓慰師；下同），叫他永遠與你們同在，",
   "en": "I will pray to the Father, and he will give you another Counselor, that he may be with you forever,—"
  },
  "17": {
   "zh": "就是真理的聖靈，乃世人不能接受的；因為不見他，也不認識他。你們卻認識他，因他常與你們同在，也要在你們裡面。",
   "en": "the Spirit of truth, whom the world can’t receive; for it doesn’t see him, neither knows him. You know him, for he lives with you, and will be in you."
  },
  "18": {
   "zh": "我不撇下你們為孤兒，我必到你們這裡來。",
   "en": "I will not leave you orphans. I will come to you."
  },
  "19": {
   "zh": "還有不多的時候，世人不再看見我，你們卻看見我；因為我活著，你們也要活著。",
   "en": "Yet a little while, and the world will see me no more; but you will see me. Because I live, you will live also."
  },
  "20": {
   "zh": "到那日，你們就知道我在父裡面，你們在我裡面，我也在你們裡面。",
   "en": "In that day you will know that I am in my Father, and you in me, and I in you."
  },
  "21": {
   "zh": "有了我的命令又遵守的，這人就是愛我的；愛我的必蒙我父愛他，我也要愛他，並且要向他顯現。」",
   "en": "One who has my commandments, and keeps them, that person is one who loves me. One who loves me will be loved by my Father, and I will love him, and will reveal myself to him.”"
  },
  "22": {
   "zh": "猶大（不是加略人猶大）問耶穌說：「主啊，為甚麼要向我們顯現，不向世人顯現呢？」",
   "en": "Judas (not Iscariot) said to him, “Lord, what has happened that you are about to reveal yourself to us, and not to the world?”"
  },
  "23": {
   "zh": "耶穌回答說：「人若愛我，就必遵守我的道；我父也必愛他，並且我們要到他那裡去，與他同住。",
   "en": "Jesus answered him, “If a man loves me, he will keep my word. My Father will love him, and we will come to him, and make our home with him."
  },
  "24": {
   "zh": "不愛我的人就不遵守我的道。你們所聽見的道不是我的，乃是差我來之父的道。",
   "en": "He who doesn’t love me doesn’t keep my words. The word which you hear isn’t mine, but the Father’s who sent me."
  },
  "25": {
   "zh": "「我還與你們同住的時候，已將這些話對你們說了。",
   "en": "I have said these things to you, while still living with you."
  },
  "26": {
   "zh": "但保惠師，就是父因我的名所要差來的聖靈，他要將一切的事指教你們，並且要叫你們想起我對你們所說的一切話。",
   "en": "But the Counselor, the Holy Spirit, whom the Father will send in my name, he will teach you all things, and will remind you of all that I said to you."
  },
  "27": {
   "zh": "我留下平安給你們；我將我的平安賜給你們。我所賜的，不像世人所賜的。你們心裡不要憂愁，也不要膽怯。",
   "en": "Peace I leave with you. My peace I give to you; not as the world gives, give I to you. Don’t let your heart be troubled, neither let it be fearful."
  },
  "28": {
   "zh": "你們聽見我對你們說了，我去還要到你們這裡來。你們若愛我，因我到父那裡去，就必喜樂，因為父是比我大的。",
   "en": "You heard how I told you, ‘I go away, and I come to you.’ If you loved me, you would have rejoiced, because I said ‘I am going to my Father;’ for the Father is greater than I."
  },
  "29": {
   "zh": "現在事情還沒有成就，我預先告訴你們，叫你們到事情成就的時候就可以信。",
   "en": "Now I have told you before it happens so that, when it happens, you may believe."
  },
  "30": {
   "zh": "以後我不再和你們多說話，因為這世界的王將到。他在我裡面是毫無所有；",
   "en": "I will no more speak much with you, for the prince of the world comes, and he has nothing in me."
  },
  "31": {
   "zh": "但要叫世人知道我愛父，並且父怎樣吩咐我，我就怎樣行。起來，我們走吧！」",
   "en": "But that the world may know that I love the Father, and as the Father commanded me, even so I do. Arise, let us go from here."
  }
 },
 "15": {
  "1": {
   "zh": "「我是真葡萄樹，我父是栽培的人。",
   "en": "“I am the true vine, and my Father is the farmer."
  },
  "2": {
   "zh": "凡屬我不結果子的枝子，他就剪去；凡結果子的，他就修理乾淨，使枝子結果子更多。",
   "en": "Every branch in me that doesn’t bear fruit, he takes away. Every branch that bears fruit, he prunes, that it may bear more fruit."
  },
  "3": {
   "zh": "現在你們因我講給你們的道，已經乾淨了。",
   "en": "You are already pruned clean because of the word which I have spoken to you."
  },
  "4": {
   "zh": "你們要常在我裡面，我也常在你們裡面。枝子若不常在葡萄樹上，自己就不能結果子；你們若不常在我裡面，也是這樣。",
   "en": "Remain in me, and I in you. As the branch can’t bear fruit by itself, unless it remains in the vine, so neither can you, unless you remain in me."
  },
  "5": {
   "zh": "我是葡萄樹，你們是枝子。常在我裡面的，我也常在他裡面，這人就多結果子；因為離了我，你們就不能做甚麼。",
   "en": "I am the vine. You are the branches. He who remains in me, and I in him, the same bears much fruit, for apart from me you can do nothing."
  },
  "6": {
   "zh": "人若不常在我裡面，就像枝子丟在外面枯乾，人拾起來，扔在火裡燒了。",
   "en": "If a man doesn’t remain in me, he is thrown out as a branch, and is withered; and they gather them, throw them into the fire, and they are burned."
  },
  "7": {
   "zh": "你們若常在我裡面，我的話也常在你們裡面，凡你們所願意的，祈求，就給你們成就。",
   "en": "If you remain in me, and my words remain in you, you will ask whatever you desire, and it will be done for you."
  },
  "8": {
   "zh": "你們多結果子，我父就因此得榮耀，你們也就是我的門徒了。",
   "en": "“In this is my Father glorified, that you bear much fruit; and so you will be my disciples."
  },
  "9": {
   "zh": "我愛你們，正如父愛我一樣；你們要常在我的愛裡。",
   "en": "Even as the Father has loved me, I also have loved you. Remain in my love."
  },
  "10": {
   "zh": "你們若遵守我的命令，就常在我的愛裡，正如我遵守了我父的命令，常在他的愛裡。",
   "en": "If you keep my commandments, you will remain in my love; even as I have kept my Father’s commandments, and remain in his love."
  },
  "11": {
   "zh": "「這些事我已經對你們說了，是要叫我的喜樂存在你們心裡，並叫你們的喜樂可以滿足。",
   "en": "I have spoken these things to you, that my joy may remain in you, and that your joy may be made full."
  },
  "12": {
   "zh": "你們要彼此相愛，像我愛你們一樣；這就是我的命令。",
   "en": "“This is my commandment, that you love one another, even as I have loved you."
  },
  "13": {
   "zh": "人為朋友捨命，人的愛心沒有比這個大的。",
   "en": "Greater love has no one than this, that someone lay down his life for his friends."
  },
  "14": {
   "zh": "你們若遵行我所吩咐的，就是我的朋友了。",
   "en": "You are my friends, if you do whatever I command you."
  },
  "15": {
   "zh": "以後我不再稱你們為僕人，因僕人不知道主人所做的事。我乃稱你們為朋友；因我從我父所聽見的，已經都告訴你們了。",
   "en": "No longer do I call you servants, for the servant doesn’t know what his lord does. But I have called you friends, for everything that I heard from my Father, I have made known to you."
  },
  "16": {
   "zh": "不是你們揀選了我，是我揀選了你們，並且分派你們去結果子，叫你們的果子常存，使你們奉我的名，無論向父求甚麼，他就賜給你們。",
   "en": "You didn’t choose me, but I chose you, and appointed you, that you should go and bear fruit, and that your fruit should remain; that whatever you will ask of the Father in my name, he may give it to you."
  },
  "17": {
   "zh": "我這樣吩咐你們，是要叫你們彼此相愛。」",
   "en": "“I command these things to you, that you may love one another."
  },
  "18": {
   "zh": "「世人若恨你們，你們知道（或譯：該知道），恨你們以先已經恨我了。",
   "en": "If the world hates you, you know that it has hated me before it hated you."
  },
  "19": {
   "zh": "你們若屬世界，世界必愛屬自己的；只因你們不屬世界，乃是我從世界中揀選了你們，所以世界就恨你們。",
   "en": "If you were of the world, the world would love its own. But because you are not of the world, since I chose you out of the world, therefore the world hates you."
  },
  "20": {
   "zh": "你們要記念我從前對你們所說的話：『僕人不能大於主人。』他們若逼迫了我，也要逼迫你們；若遵守了我的話，也要遵守你們的話。",
   "en": "Remember the word that I said to you: ‘A servant is not greater than his lord.’ If they persecuted me, they will also persecute you. If they kept my word, they will also keep yours."
  },
  "21": {
   "zh": "但他們因我的名要向你們行這一切的事，因為他們不認識那差我來的。",
   "en": "But all these things will they do to you for my name’s sake, because they don’t know him who sent me."
  },
  "22": {
   "zh": "我若沒有來教訓他們，他們就沒有罪；但如今他們的罪無可推諉了。",
   "en": "If I had not come and spoken to them, they would not have had sin; but now they have no excuse for their sin."
  },
  "23": {
   "zh": "恨我的，也恨我的父。",
   "en": "He who hates me, hates my Father also."
  },
  "24": {
   "zh": "我若沒有在他們中間行過別人未曾行的事，他們就沒有罪；但如今連我與我的父，他們也看見也恨惡了。",
   "en": "If I hadn’t done among them the works which no one else did, they wouldn’t have had sin. But now have they seen and also hated both me and my Father."
  },
  "25": {
   "zh": "這要應驗他們律法上所寫的話，說：『他們無故地恨我。』",
   "en": "But this happened so that the word may be fulfilled which was written in their law, ‘They hated me without a cause.’"
  },
  "26": {
   "zh": "但我要從父那裡差保惠師來，就是從父出來真理的聖靈；他來了，就要為我作見證。",
   "en": "“When the Counselor has come, whom I will send to you from the Father, the Spirit of truth, who proceeds from the Father, he will testify about me."
  },
  "27": {
   "zh": "你們也要作見證，因為你們從起頭就與我同在。」",
   "en": "You will also testify, because you have been with me from the beginning."
  }
 },
 "16": {
  "1": {
   "zh": "「我已將這些事告訴你們，使你們不至於跌倒。",
   "en": "“I have said these things to you so that you wouldn’t be caused to stumble."
  },
  "2": {
   "zh": "人要把你們趕出會堂，並且時候將到，凡殺你們的就以為是事奉神。",
   "en": "They will put you out of the synagogues. Yes, the time comes that whoever kills you will think that he offers service to God."
  },
  "3": {
   "zh": "他們這樣行，是因未曾認識父，也未曾認識我。",
   "en": "They will do these things because they have not known the Father, nor me."
  },
  "4": {
   "zh": "我將這事告訴你們，是叫你們到了時候可以想起我對你們說過了。」「我起先沒有將這事告訴你們，因為我與你們同在。",
   "en": "But I have told you these things, so that when the time comes, you may remember that I told you about them. I didn’t tell you these things from the beginning, because I was with you."
  },
  "5": {
   "zh": "現今我往差我來的父那裡去，你們中間並沒有人問我：『你往哪裡去？』",
   "en": "But now I am going to him who sent me, and none of you asks me, ‘Where are you going?’"
  },
  "6": {
   "zh": "只因我將這事告訴你們，你們就滿心憂愁。",
   "en": "But because I have told you these things, sorrow has filled your heart."
  },
  "7": {
   "zh": "然而，我將真情告訴你們，我去是與你們有益的；我若不去，保惠師就不到你們這裡來；我若去，就差他來。",
   "en": "Nevertheless I tell you the truth: It is to your advantage that I go away, for if I don’t go away, the Counselor won’t come to you. But if I go, I will send him to you."
  },
  "8": {
   "zh": "他既來了，就要叫世人為罪、為義、為審判，自己責備自己。",
   "en": "When he has come, he will convict the world about sin, about righteousness, and about judgment;"
  },
  "9": {
   "zh": "為罪，是因他們不信我；",
   "en": "about sin, because they don’t believe in me;"
  },
  "10": {
   "zh": "為義，是因我往父那裡去，你們就不再見我；",
   "en": "about righteousness, because I am going to my Father, and you won’t see me any more;"
  },
  "11": {
   "zh": "為審判，是因這世界的王受了審判。",
   "en": "about judgment, because the prince of this world has been judged."
  },
  "12": {
   "zh": "「我還有好些事要告訴你們，但你們現在擔當不了（或譯：不能領會）。",
   "en": "“I have yet many things to tell you, but you can’t bear them now."
  },
  "13": {
   "zh": "只等真理的聖靈來了，他要引導你們明白（原文是進入）一切的真理；因為他不是憑自己說的，乃是把他所聽見的都說出來，並要把將來的事告訴你們。",
   "en": "However when he, the Spirit of truth, has come, he will guide you into all truth, for he will not speak from himself; but whatever he hears, he will speak. He will declare to you things that are coming."
  },
  "14": {
   "zh": "他要榮耀我，因為他要將受於我的告訴你們。",
   "en": "He will glorify me, for he will take from what is mine, and will declare it to you."
  },
  "15": {
   "zh": "凡父所有的，都是我的；所以我說，他要將受於我的告訴你們。」",
   "en": "All things whatever the Father has are mine; therefore I said that he takes of mine, and will declare it to you."
  },
  "16": {
   "zh": "「等不多時，你們就不得見我；再等不多時，你們還要見我。」",
   "en": "A little while, and you will not see me. Again a little while, and you will see me.”"
  },
  "17": {
   "zh": "有幾個門徒就彼此說：「他對我們說：『等不多時，你們就不得見我；再等不多時，你們還要見我』；又說：『因我往父那裡去。』這是甚麼意思呢？」",
   "en": "Some of his disciples therefore said to one another, “What is this that he says to us, ‘A little while, and you won’t see me, and again a little while, and you will see me;’ and, ‘Because I go to the Father’?”"
  },
  "18": {
   "zh": "門徒彼此說：「他說『等不多時』到底是甚麼意思呢？我們不明白他所說的話。」",
   "en": "They said therefore, “What is this that he says, ‘A little while’? We don’t know what he is saying.”"
  },
  "19": {
   "zh": "耶穌看出他們要問他，就說：「我說『等不多時，你們就不得見我；再等不多時，你們還要見我』，你們為這話彼此相問嗎？",
   "en": "Therefore Jesus perceived that they wanted to ask him, and he said to them, “Do you inquire among yourselves concerning this, that I said, ‘A little while, and you won’t see me, and again a little while, and you will see me?’"
  },
  "20": {
   "zh": "我實實在在地告訴你們，你們將要痛哭、哀號，世人倒要喜樂；你們將要憂愁，然而你們的憂愁要變為喜樂。",
   "en": "Most certainly I tell you, that you will weep and lament, but the world will rejoice. You will be sorrowful, but your sorrow will be turned into joy."
  },
  "21": {
   "zh": "婦人生產的時候就憂愁，因為她的時候到了；既生了孩子，就不再記念那苦楚，因為歡喜世上生了一個人。",
   "en": "A woman, when she gives birth, has sorrow, because her time has come. But when she has delivered the child, she doesn’t remember the anguish any more, for the joy that a human being is born into the world."
  },
  "22": {
   "zh": "你們現在也是憂愁，但我要再見你們，你們的心就喜樂了；這喜樂也沒有人能奪去。",
   "en": "Therefore you now have sorrow, but I will see you again, and your heart will rejoice, and no one will take your joy away from you."
  },
  "23": {
   "zh": "到那日，你們甚麼也就不問我了。我實實在在地告訴你們，你們若向父求甚麼，他必因我的名賜給你們。",
   "en": "“In that day you will ask me no questions. Most certainly I tell you, whatever you may ask of the Father in my name, he will give it to you."
  },
  "24": {
   "zh": "向來你們沒有奉我的名求甚麼，如今你們求，就必得著，叫你們的喜樂可以滿足。」",
   "en": "Until now, you have asked nothing in my name. Ask, and you will receive, that your joy may be made full."
  },
  "25": {
   "zh": "「這些事，我是用比喻對你們說的；時候將到，我不再用比喻對你們說，乃要將父明明地告訴你們。",
   "en": "I have spoken these things to you in figures of speech. But the time is coming when I will no more speak to you in figures of speech, but will tell you plainly about the Father."
  },
  "26": {
   "zh": "到那日，你們要奉我的名祈求；我並不對你們說，我要為你們求父。",
   "en": "In that day you will ask in my name; and I don’t say to you, that I will pray to the Father for you,"
  },
  "27": {
   "zh": "父自己愛你們；因為你們已經愛我，又信我是從父出來的。",
   "en": "for the Father himself loves you, because you have loved me, and have believed that I came from God."
  },
  "28": {
   "zh": "我從父出來，到了世界；我又離開世界，往父那裡去。」",
   "en": "I came from the Father, and have come into the world. Again, I leave the world, and go to the Father.”"
  },
  "29": {
   "zh": "門徒說：「如今你是明說，並不用比喻了。",
   "en": "His disciples said to him, “Behold, now you are speaking plainly, and using no figures of speech."
  },
  "30": {
   "zh": "現在我們曉得你凡事都知道，也不用人問你，因此我們信你是從神出來的。」",
   "en": "Now we know that you know all things, and don’t need for anyone to question you. By this we believe that you came from God.”"
  },
  "31": {
   "zh": "耶穌說：「現在你們信嗎？",
   "en": "Jesus answered them, “Do you now believe?"
  },
  "32": {
   "zh": "看哪，時候將到，且是已經到了，你們要分散，各歸自己的地方去，留下我獨自一人；其實我不是獨自一人，因為有父與我同在。",
   "en": "Behold, the time is coming, yes, and has now come, that you will be scattered, everyone to his own place, and you will leave me alone. Yet I am not alone, because the Father is with me."
  },
  "33": {
   "zh": "我將這些事告訴你們，是要叫你們在我裡面有平安。在世上，你們有苦難；但你們可以放心，我已經勝了世界。」",
   "en": "I have told you these things, that in me you may have peace. In the world you have oppression; but cheer up! I have overcome the world.”"
  }
 },
 "17": {
  "1": {
   "zh": "耶穌說了這話，就舉目望天，說：「父啊，時候到了，願你榮耀你的兒子，使兒子也榮耀你；",
   "en": "Jesus said these things, and lifting up his eyes to heaven, he said, “Father, the time has come. Glorify your Son, that your Son may also glorify you;"
  },
  "2": {
   "zh": "正如你曾賜給他權柄管理凡有血氣的，叫他將永生賜給你所賜給他的人。",
   "en": "even as you gave him authority over all flesh, so he will give eternal life to all whom you have given him."
  },
  "3": {
   "zh": "認識你─獨一的真神，並且認識你所差來的耶穌基督，這就是永生。",
   "en": "This is eternal life, that they should know you, the only true God, and him whom you sent, Jesus Christ."
  },
  "4": {
   "zh": "我在地上已經榮耀你，你所託付我的事，我已成全了。",
   "en": "I glorified you on the earth. I have accomplished the work which you have given me to do."
  },
  "5": {
   "zh": "父啊，現在求你使我同你享榮耀，就是未有世界以先，我同你所有的榮耀。",
   "en": "Now, Father, glorify me with your own self with the glory which I had with you before the world existed."
  },
  "6": {
   "zh": "「你從世上賜給我的人，我已將你的名顯明與他們。他們本是你的，你將他們賜給我，他們也遵守了你的道。",
   "en": "I revealed your name to the people whom you have given me out of the world. They were yours, and you have given them to me. They have kept your word."
  },
  "7": {
   "zh": "如今他們知道，凡你所賜給我的，都是從你那裡來的；",
   "en": "Now they have known that all things whatever you have given me are from you,"
  },
  "8": {
   "zh": "因為你所賜給我的道，我已經賜給他們，他們也領受了，又確實知道，我是從你出來的，並且信你差了我來。",
   "en": "for the words which you have given me I have given to them, and they received them, and knew for sure that I came from you, and they have believed that you sent me."
  },
  "9": {
   "zh": "我為他們祈求，不為世人祈求，卻為你所賜給我的人祈求，因他們本是你的。",
   "en": "I pray for them. I don’t pray for the world, but for those whom you have given me, for they are yours."
  },
  "10": {
   "zh": "凡是我的，都是你的；你的也是我的，並且我因他們得了榮耀。",
   "en": "All things that are mine are yours, and yours are mine, and I am glorified in them."
  },
  "11": {
   "zh": "從今以後，我不在世上，他們卻在世上；我往你那裡去。聖父啊，求你因你所賜給我的名保守他們，叫他們合而為一像我們一樣。",
   "en": "I am no more in the world, but these are in the world, and I am coming to you. Holy Father, keep them through your name which you have given me, that they may be one, even as we are."
  },
  "12": {
   "zh": "我與他們同在的時候，因你所賜給我的名保守了他們，我也護衛了他們；其中除了那滅亡之子，沒有一個滅亡的，好叫經上的話得應驗。",
   "en": "While I was with them in the world, I kept them in your name. Those whom you have given me I have kept. None of them is lost, except the son of destruction, that the Scripture might be fulfilled."
  },
  "13": {
   "zh": "現在我往你那裡去，我還在世上說這話，是叫他們心裡充滿我的喜樂。",
   "en": "But now I come to you, and I say these things in the world, that they may have my joy made full in themselves."
  },
  "14": {
   "zh": "我已將你的道賜給他們。世界又恨他們；因為他們不屬世界，正如我不屬世界一樣。",
   "en": "I have given them your word. The world hated them, because they are not of the world, even as I am not of the world."
  },
  "15": {
   "zh": "我不求你叫他們離開世界，只求你保守他們脫離那惡者（或譯：脫離罪惡）。",
   "en": "I pray not that you would take them from the world, but that you would keep them from the evil one."
  },
  "16": {
   "zh": "他們不屬世界，正如我不屬世界一樣。",
   "en": "They are not of the world even as I am not of the world."
  },
  "17": {
   "zh": "求你用真理使他們成聖；你的道就是真理。",
   "en": "Sanctify them in your truth. Your word is truth."
  },
  "18": {
   "zh": "你怎樣差我到世上，我也照樣差他們到世上。",
   "en": "As you sent me into the world, even so I have sent them into the world."
  },
  "19": {
   "zh": "我為他們的緣故，自己分別為聖，叫他們也因真理成聖。",
   "en": "For their sakes I sanctify myself, that they themselves also may be sanctified in truth."
  },
  "20": {
   "zh": "「我不但為這些人祈求，也為那些因他們的話信我的人祈求，",
   "en": "Not for these only do I pray, but for those also who will believe in me through their word,"
  },
  "21": {
   "zh": "使他們都合而為一。正如你父在我裡面，我在你裡面，使他們也在我們裡面，叫世人可以信你差了我來。",
   "en": "that they may all be one; even as you, Father, are in me, and I in you, that they also may be one in us; that the world may believe that you sent me."
  },
  "22": {
   "zh": "你所賜給我的榮耀，我已賜給他們，使他們合而為一，像我們合而為一。",
   "en": "The glory which you have given me, I have given to them; that they may be one, even as we are one;"
  },
  "23": {
   "zh": "我在他們裡面，你在我裡面，使他們完完全全地合而為一，叫世人知道你差了我來，也知道你愛他們如同愛我一樣。",
   "en": "I in them, and you in me, that they may be perfected into one; that the world may know that you sent me, and loved them, even as you loved me."
  },
  "24": {
   "zh": "父啊，我在哪裡，願你所賜給我的人也同我在那裡，叫他們看見你所賜給我的榮耀；因為創立世界以前，你已經愛我了。",
   "en": "Father, I desire that they also whom you have given me be with me where I am, that they may see my glory, which you have given me, for you loved me before the foundation of the world."
  },
  "25": {
   "zh": "公義的父啊，世人未曾認識你，我卻認識你；這些人也知道你差了我來。",
   "en": "Righteous Father, the world hasn’t known you, but I knew you; and these knew that you sent me."
  },
  "26": {
   "zh": "我已將你的名指示他們，還要指示他們，使你所愛我的愛在他們裡面，我也在他們裡面。」",
   "en": "I made known to them your name, and will make it known; that the love with which you loved me may be in them, and I in them.”"
  }
 },
 "18": {
  "1": {
   "zh": "耶穌說了這話，就同門徒出去，過了汲淪溪。在那裡有一個園子，他和門徒進去了。",
   "en": "When Jesus had spoken these words, he went out with his disciples over the brook Kidron, where there was a garden, into which he and his disciples entered."
  },
  "2": {
   "zh": "賣耶穌的猶大也知道那地方，因為耶穌和門徒屢次上那裡去聚集。",
   "en": "Now Judas, who betrayed him, also knew the place, for Jesus often met there with his disciples."
  },
  "3": {
   "zh": "猶大領了一隊兵，和祭司長並法利賽人的差役，拿著燈籠、火把、兵器，就來到園裡。",
   "en": "Judas then, having taken a detachment of soldiers and officers from the chief priests and the Pharisees, came there with lanterns, torches, and weapons."
  },
  "4": {
   "zh": "耶穌知道將要臨到自己的一切事，就出來對他們說：「你們找誰？」",
   "en": "Jesus therefore, knowing all the things that were happening to him, went out, and said to them, “Who are you looking for?”"
  },
  "5": {
   "zh": "他們回答說：「找拿撒勒人耶穌。」耶穌說：「我就是！」賣他的猶大也同他們站在那裡。",
   "en": "They answered him, “Jesus of Nazareth.” Jesus said to them, “I am he.” Judas also, who betrayed him, was standing with them."
  },
  "6": {
   "zh": "耶穌一說「我就是」，他們就退後倒在地上。",
   "en": "When therefore he said to them, “I am he,” they went backward, and fell to the ground."
  },
  "7": {
   "zh": "他又問他們說：「你們找誰？」他們說：「找拿撒勒人耶穌。」",
   "en": "Again therefore he asked them, “Who are you looking for?” They said, “Jesus of Nazareth.”"
  },
  "8": {
   "zh": "耶穌說：「我已經告訴你們，我就是。你們若找我，就讓這些人去吧。」",
   "en": "Jesus answered, “I told you that I am he. If therefore you seek me, let these go their way,”"
  },
  "9": {
   "zh": "這要應驗耶穌從前的話，說：「你所賜給我的人，我沒有失落一個。」",
   "en": "that the word might be fulfilled which he spoke, “Of those whom you have given me, I have lost none.”"
  },
  "10": {
   "zh": "西門•彼得帶著一把刀，就拔出來，將大祭司的僕人砍了一刀，削掉他的右耳；那僕人名叫馬勒古。",
   "en": "Simon Peter therefore, having a sword, drew it, and struck the high priest’s servant, and cut off his right ear. The servant’s name was Malchus."
  },
  "11": {
   "zh": "耶穌就對彼得說：「收刀入鞘吧，我父所給我的那杯，我豈可不喝呢？」",
   "en": "Jesus therefore said to Peter, “Put the sword into its sheath. The cup which the Father has given me, shall I not surely drink it?”"
  },
  "12": {
   "zh": "那隊兵和千夫長，並猶太人的差役就拿住耶穌，把他捆綁了，",
   "en": "So the detachment, the commanding officer, and the officers of the Jews, seized Jesus and bound him,"
  },
  "13": {
   "zh": "先帶到亞那面前，因為亞那是本年作大祭司該亞法的岳父。",
   "en": "and led him to Annas first, for he was father-in-law to Caiaphas, who was high priest that year."
  },
  "14": {
   "zh": "這該亞法就是從前向猶太人發議論說「一個人替百姓死是有益的」那位。",
   "en": "Now it was Caiaphas who advised the Jews that it was expedient that one man should perish for the people."
  },
  "15": {
   "zh": "西門•彼得跟著耶穌，還有一個門徒跟著。那門徒是大祭司所認識的，他就同耶穌進了大祭司的院子。",
   "en": "Simon Peter followed Jesus, as did another disciple. Now that disciple was known to the high priest, and entered in with Jesus into the court of the high priest;"
  },
  "16": {
   "zh": "彼得卻站在門外。大祭司所認識的那個門徒出來，和看門的使女說了一聲，就領彼得進去。",
   "en": "but Peter was standing at the door outside. So the other disciple, who was known to the high priest, went out and spoke to her who kept the door, and brought in Peter."
  },
  "17": {
   "zh": "那看門的使女對彼得說：「你不也是這人的門徒嗎？」他說：「我不是。」",
   "en": "Then the maid who kept the door said to Peter, “Are you also one of this man’s disciples?” He said, “I am not.”"
  },
  "18": {
   "zh": "僕人和差役因為天冷，就生了炭火，站在那裡烤火；彼得也同他們站著烤火。",
   "en": "Now the servants and the officers were standing there, having made a fire of coals, for it was cold. They were warming themselves. Peter was with them, standing and warming himself."
  },
  "19": {
   "zh": "大祭司就以耶穌的門徒和他的教訓盤問他。",
   "en": "The high priest therefore asked Jesus about his disciples, and about his teaching."
  },
  "20": {
   "zh": "耶穌回答說：「我從來是明明地對世人說話。我常在會堂和殿裡，就是猶太人聚集的地方教訓人；我在暗地裡並沒有說甚麼。",
   "en": "Jesus answered him, “I spoke openly to the world. I always taught in synagogues, and in the temple, where the Jews always meet. I said nothing in secret."
  },
  "21": {
   "zh": "你為甚麼問我呢？可以問那聽見的人，我對他們說的是甚麼；我所說的，他們都知道。」",
   "en": "Why do you ask me? Ask those who have heard me what I said to them. Behold, these know the things which I said.”"
  },
  "22": {
   "zh": "耶穌說了這話，旁邊站著的一個差役用手掌打他，說：「你這樣回答大祭司嗎？」",
   "en": "When he had said this, one of the officers standing by slapped Jesus with his hand, saying, “Do you answer the high priest like that?”"
  },
  "23": {
   "zh": "耶穌說：「我若說的不是，你可以指證那不是；我若說的是，你為甚麼打我呢？」",
   "en": "Jesus answered him, “If I have spoken evil, testify of the evil; but if well, why do you beat me?”"
  },
  "24": {
   "zh": "亞那就把耶穌解到大祭司該亞法那裡，仍是捆著解去的。",
   "en": "Annas sent him bound to Caiaphas, the high priest."
  },
  "25": {
   "zh": "西門•彼得正站著烤火，有人對他說：「你不也是他的門徒嗎？」彼得不承認，說：「我不是。」",
   "en": "Now Simon Peter was standing and warming himself. They said therefore to him, “You aren’t also one of his disciples, are you?” He denied it, and said, “I am not.”"
  },
  "26": {
   "zh": "有大祭司的一個僕人，是彼得削掉耳朵那人的親屬，說：「我不是看見你同他在園子裡嗎？」",
   "en": "One of the servants of the high priest, being a relative of him whose ear Peter had cut off, said, “Didn’t I see you in the garden with him?”"
  },
  "27": {
   "zh": "彼得又不承認。立時雞就叫了。",
   "en": "Peter therefore denied it again, and immediately the rooster crowed."
  },
  "28": {
   "zh": "眾人將耶穌從該亞法那裡往衙門內解去，那時天還早。他們自己卻不進衙門，恐怕染了污穢，不能吃逾越節的筵席。",
   "en": "They led Jesus therefore from Caiaphas into the Praetorium. It was early, and they themselves didn’t enter into the Praetorium, that they might not be defiled, but might eat the Passover."
  },
  "29": {
   "zh": "彼拉多就出來，到他們那裡，說：「你們告這人是為甚麼事呢？」",
   "en": "Pilate therefore went out to them, and said, “What accusation do you bring against this man?”"
  },
  "30": {
   "zh": "他們回答說：「這人若不是作惡的，我們就不把他交給你。」",
   "en": "They answered him, “If this man weren’t an evildoer, we wouldn’t have delivered him up to you.”"
  },
  "31": {
   "zh": "彼拉多說：「你們自己帶他去，按著你們的律法審問他吧。」猶太人說：「我們沒有殺人的權柄。」",
   "en": "Pilate therefore said to them, “Take him yourselves, and judge him according to your law.” Therefore the Jews said to him, “It is not lawful for us to put anyone to death,”"
  },
  "32": {
   "zh": "這要應驗耶穌所說自己將要怎樣死的話了。",
   "en": "that the word of Jesus might be fulfilled, which he spoke, signifying by what kind of death he should die."
  },
  "33": {
   "zh": "彼拉多又進了衙門，叫耶穌來，對他說：「你是猶太人的王嗎？」",
   "en": "Pilate therefore entered again into the Praetorium, called Jesus, and said to him, “Are you the King of the Jews?”"
  },
  "34": {
   "zh": "耶穌回答說：「這話是你自己說的，還是別人論我對你說的呢？」",
   "en": "Jesus answered him, “Do you say this by yourself, or did others tell you about me?”"
  },
  "35": {
   "zh": "彼拉多說：「我豈是猶太人呢？你本國的人和祭司長把你交給我。你做了甚麼事呢？」",
   "en": "Pilate answered, “I’m not a Jew, am I? Your own nation and the chief priests delivered you to me. What have you done?”"
  },
  "36": {
   "zh": "耶穌回答說：「我的國不屬這世界；我的國若屬這世界，我的臣僕必要爭戰，使我不至於被交給猶太人。只是我的國不屬這世界。」",
   "en": "Jesus answered, “My Kingdom is not of this world. If my Kingdom were of this world, then my servants would fight, that I wouldn’t be delivered to the Jews. But now my Kingdom is not from here.”"
  },
  "37": {
   "zh": "彼拉多就對他說：「這樣，你是王嗎？」耶穌回答說：「你說我是王。我為此而生，也為此來到世間，特為給真理作見證。凡屬真理的人就聽我的話。」",
   "en": "Pilate therefore said to him, “Are you a king then?” Jesus answered, “You say that I am a king. For this reason I have been born, and for this reason I have come into the world, that I should testify to the truth. Everyone who is of the truth listens to my voice.”"
  },
  "38": {
   "zh": "彼拉多說：「真理是甚麼呢？」說了這話，又出來到猶太人那裡，對他們說：「我查不出他有甚麼罪來。",
   "en": "Pilate said to him, “What is truth?” When he had said this, he went out again to the Jews, and said to them, “I find no basis for a charge against him."
  },
  "39": {
   "zh": "但你們有個規矩，在逾越節要我給你們釋放一個人，你們要我給你們釋放猶太人的王嗎？」",
   "en": "But you have a custom, that I should release someone to you at the Passover. Therefore, do you want me to release to you the King of the Jews?”"
  },
  "40": {
   "zh": "他們又喊著說：「不要這人，要巴拉巴！」這巴拉巴是個強盜。",
   "en": "Then they all shouted again, saying, “Not this man, but Barabbas!” Now Barabbas was a robber."
  }
 },
 "19": {
  "1": {
   "zh": "當下彼拉多將耶穌鞭打了。",
   "en": "So Pilate then took Jesus, and flogged him."
  },
  "2": {
   "zh": "兵丁用荊棘編做冠冕戴在他頭上，給他穿上紫袍，",
   "en": "The soldiers twisted thorns into a crown, and put it on his head, and dressed him in a purple garment."
  },
  "3": {
   "zh": "又挨近他，說：「恭喜，猶太人的王啊！」他們就用手掌打他。",
   "en": "They kept saying, “Hail, King of the Jews!” and they kept slapping him."
  },
  "4": {
   "zh": "彼拉多又出來對眾人說：「我帶他出來見你們，叫你們知道我查不出他有甚麼罪來。」",
   "en": "Then Pilate went out again, and said to them, “Behold, I bring him out to you, that you may know that I find no basis for a charge against him.”"
  },
  "5": {
   "zh": "耶穌出來，戴著荊棘冠冕，穿著紫袍。彼拉多對他們說：「你們看這個人！」",
   "en": "Jesus therefore came out, wearing the crown of thorns and the purple garment. Pilate said to them, “Behold, the man!”"
  },
  "6": {
   "zh": "祭司長和差役看見他，就喊著說：「釘他十字架！釘他十字架！」彼拉多說：「你們自己把他釘十字架吧！我查不出他有甚麼罪來。」",
   "en": "When therefore the chief priests and the officers saw him, they shouted, saying, “Crucify! Crucify!” Pilate said to them, “Take him yourselves, and crucify him, for I find no basis for a charge against him.”"
  },
  "7": {
   "zh": "猶太人回答說：「我們有律法，按那律法，他是該死的，因他以自己為神的兒子。」",
   "en": "The Jews answered him, “We have a law, and by our law he ought to die, because he made himself the Son of God.”"
  },
  "8": {
   "zh": "彼拉多聽見這話，越發害怕，",
   "en": "When therefore Pilate heard this saying, he was more afraid."
  },
  "9": {
   "zh": "又進衙門，對耶穌說：「你是哪裡來的？」耶穌卻不回答。",
   "en": "He entered into the Praetorium again, and said to Jesus, “Where are you from?” But Jesus gave him no answer."
  },
  "10": {
   "zh": "彼拉多說：「你不對我說話嗎？你豈不知我有權柄釋放你，也有權柄把你釘十字架嗎？」",
   "en": "Pilate therefore said to him, “Aren’t you speaking to me? Don’t you know that I have power to release you, and have power to crucify you?”"
  },
  "11": {
   "zh": "耶穌回答說：「若不是從上頭賜給你的，你就毫無權柄辦我。所以，把我交給你的那人罪更重了。」",
   "en": "Jesus answered, “You would have no power at all against me, unless it were given to you from above. Therefore he who delivered me to you has greater sin.”"
  },
  "12": {
   "zh": "從此，彼拉多想要釋放耶穌，無奈猶太人喊著說：「你若釋放這個人，就不是該撒的忠臣（原文是朋友）。凡以自己為王的，就是背叛該撒了。」",
   "en": "At this, Pilate was seeking to release him, but the Jews cried out, saying, “If you release this man, you aren’t Caesar’s friend! Everyone who makes himself a king speaks against Caesar!”"
  },
  "13": {
   "zh": "彼拉多聽見這話，就帶耶穌出來，到了一個地方，名叫「鋪華石處」，希伯來話叫厄巴大，就在那裡坐堂。",
   "en": "When Pilate therefore heard these words, he brought Jesus out, and sat down on the judgment seat at a place called “The Pavement”, but in Hebrew, “Gabbatha.”"
  },
  "14": {
   "zh": "那日是預備逾越節的日子，約有午正。彼拉多對猶太人說：「看哪，這是你們的王！」",
   "en": "Now it was the Preparation Day of the Passover, at about the sixth hour. He said to the Jews, “Behold, your King!”"
  },
  "15": {
   "zh": "他們喊著說：「除掉他！除掉他！釘他在十字架上！」彼拉多說：「我可以把你們的王釘十字架嗎？」祭司長回答說：「除了該撒，我們沒有王。」",
   "en": "They cried out, “Away with him! Away with him! Crucify him!” Pilate said to them, “Shall I crucify your King?” The chief priests answered, “We have no king but Caesar!”"
  },
  "16": {
   "zh": "於是彼拉多將耶穌交給他們去釘十字架。",
   "en": "So then he delivered him to them to be crucified. So they took Jesus and led him away."
  },
  "17": {
   "zh": "他們就把耶穌帶了去。耶穌背著自己的十字架出來，到了一個地方，名叫「髑髏地」，希伯來話叫各各他。",
   "en": "He went out, bearing his cross, to the place called “The Place of a Skull”, which is called in Hebrew, “Golgotha”,"
  },
  "18": {
   "zh": "他們就在那裡釘他在十字架上，還有兩個人和他一同釘著，一邊一個，耶穌在中間。",
   "en": "where they crucified him, and with him two others, on either side one, and Jesus in the middle."
  },
  "19": {
   "zh": "彼拉多又用牌子寫了一個名號，安在十字架上，寫的是：「猶太人的王，拿撒勒人耶穌。」",
   "en": "Pilate wrote a title also, and put it on the cross. There was written, “JESUS OF NAZARETH, THE KING OF THE JEWS.”"
  },
  "20": {
   "zh": "有許多猶太人念這名號；因為耶穌被釘十字架的地方與城相近，並且是用希伯來、羅馬、希臘三樣文字寫的。",
   "en": "Therefore many of the Jews read this title, for the place where Jesus was crucified was near the city; and it was written in Hebrew, in Latin, and in Greek."
  },
  "21": {
   "zh": "猶太人的祭司長就對彼拉多說：「不要寫『猶太人的王』，要寫『他自己說：我是猶太人的王』。」",
   "en": "The chief priests of the Jews therefore said to Pilate, “Don’t write, ‘The King of the Jews,’ but, ‘he said, “I am King of the Jews.”’”"
  },
  "22": {
   "zh": "彼拉多說：「我所寫的，我已經寫上了。」",
   "en": "Pilate answered, “What I have written, I have written.”"
  },
  "23": {
   "zh": "兵丁既然將耶穌釘在十字架上，就拿他的衣服分為四分，每兵一分；又拿他的裡衣，這件裡衣原來沒有縫兒，是上下一片織成的。",
   "en": "Then the soldiers, when they had crucified Jesus, took his garments and made four parts, to every soldier a part; and also the coat. Now the coat was without seam, woven from the top throughout."
  },
  "24": {
   "zh": "他們就彼此說：「我們不要撕開，只要拈鬮，看誰得著。」這要應驗經上的話說：他們分了我的外衣，為我的裡衣拈鬮。兵丁果然做了這事。",
   "en": "Then they said to one another, “Let’s not tear it, but cast lots for it to decide whose it will be,” that the Scripture might be fulfilled, which says, “They parted my garments among them. For my cloak they cast lots.” Therefore the soldiers did these things."
  },
  "25": {
   "zh": "站在耶穌十字架旁邊的，有他母親與他母親的姊妹，並革羅罷的妻子馬利亞，和抹大拉的馬利亞。",
   "en": "But there were standing by the cross of Jesus his mother, and his mother’s sister, Mary the wife of Clopas, and Mary Magdalene."
  },
  "26": {
   "zh": "耶穌見母親和他所愛的那門徒站在旁邊，就對他母親說：「母親（原文是婦人），看，你的兒子！」",
   "en": "Therefore when Jesus saw his mother, and the disciple whom he loved standing there, he said to his mother, “Woman, behold, your son!”"
  },
  "27": {
   "zh": "又對那門徒說：「看，你的母親！」從此，那門徒就接她到自己家裡去了。",
   "en": "Then he said to the disciple, “Behold, your mother!” From that hour, the disciple took her to his own home."
  },
  "28": {
   "zh": "這事以後，耶穌知道各樣的事已經成了，為要使經上的話應驗，就說：「我渴了。」",
   "en": "After this, Jesus, seeing that all things were now finished, that the Scripture might be fulfilled, said, “I am thirsty.”"
  },
  "29": {
   "zh": "有一個器皿盛滿了醋，放在那裡；他們就拿海絨蘸滿了醋，綁在牛膝草上，送到他口。",
   "en": "Now a vessel full of vinegar was set there; so they put a sponge full of the vinegar on hyssop, and held it at his mouth."
  },
  "30": {
   "zh": "耶穌嘗（原文是受）了那醋，就說：「成了！」便低下頭，將靈魂交付神了。",
   "en": "When Jesus therefore had received the vinegar, he said, “It is finished.” He bowed his head, and gave up his spirit."
  },
  "31": {
   "zh": "猶太人因這日是預備日，又因那安息日是個大日，就求彼拉多叫人打斷他們的腿，把他們拿去，免得屍首當安息日留在十字架上。",
   "en": "Therefore the Jews, because it was the Preparation Day, so that the bodies wouldn’t remain on the cross on the Sabbath (for that Sabbath was a special one), asked of Pilate that their legs might be broken, and that they might be taken away."
  },
  "32": {
   "zh": "於是兵丁來，把頭一個人的腿，並與耶穌同釘第二個人的腿，都打斷了。",
   "en": "Therefore the soldiers came, and broke the legs of the first, and of the other who was crucified with him;"
  },
  "33": {
   "zh": "只是來到耶穌那裡，見他已經死了，就不打斷他的腿。",
   "en": "but when they came to Jesus, and saw that he was already dead, they didn’t break his legs."
  },
  "34": {
   "zh": "惟有一個兵拿槍扎他的肋旁，隨即有血和水流出來。",
   "en": "However one of the soldiers pierced his side with a spear, and immediately blood and water came out."
  },
  "35": {
   "zh": "看見這事的那人就作見證─他的見證也是真的，並且他知道自己所說的是真的─叫你們也可以信。",
   "en": "He who has seen has testified, and his testimony is true. He knows that he tells the truth, that you may believe."
  },
  "36": {
   "zh": "這些事成了，為要應驗經上的話說：「他的骨頭一根也不可折斷。」",
   "en": "For these things happened, that the Scripture might be fulfilled, “A bone of him will not be broken.”"
  },
  "37": {
   "zh": "經上又有一句說：「他們要仰望自己所扎的人。」",
   "en": "Again another Scripture says, “They will look on him whom they pierced.”"
  },
  "38": {
   "zh": "這些事以後，有亞利馬太人約瑟，是耶穌的門徒，只因怕猶太人，就暗暗地作門徒。他來求彼拉多，要把耶穌的身體領去。彼拉多允准，他就把耶穌的身體領去了。",
   "en": "After these things, Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, asked of Pilate that he might take away Jesus’ body. Pilate gave him permission. He came therefore and took away his body."
  },
  "39": {
   "zh": "又有尼哥底母，就是先前夜裡去見耶穌的，帶著沒藥和沉香約有一百斤前來。",
   "en": "Nicodemus, who at first came to Jesus by night, also came bringing a mixture of myrrh and aloes, about a hundred Roman pounds."
  },
  "40": {
   "zh": "他們就照猶太人殯葬的規矩，把耶穌的身體用細麻布加上香料裹好了。",
   "en": "So they took Jesus’ body, and bound it in linen cloths with the spices, as the custom of the Jews is to bury."
  },
  "41": {
   "zh": "在耶穌釘十字架的地方有一個園子，園子裡有一座新墳墓，是從來沒有葬過人的。",
   "en": "Now in the place where he was crucified there was a garden. In the garden was a new tomb in which no man had ever yet been laid."
  },
  "42": {
   "zh": "只因是猶太人的預備日，又因那墳墓近，他們就把耶穌安放在那裡。",
   "en": "Then because of the Jews’ Preparation Day (for the tomb was near at hand) they laid Jesus there."
  }
 },
 "20": {
  "1": {
   "zh": "七日的第一日清早，天還黑的時候，抹大拉的馬利亞來到墳墓那裡，看見石頭從墳墓挪開了，",
   "en": "Now on the first day of the week, Mary Magdalene went early, while it was still dark, to the tomb, and saw the stone taken away from the tomb."
  },
  "2": {
   "zh": "就跑來見西門•彼得和耶穌所愛的那個門徒，對他們說：「有人把主從墳墓裡挪了去，我們不知道放在哪裡。」",
   "en": "Therefore she ran and came to Simon Peter, and to the other disciple whom Jesus loved, and said to them, “They have taken away the Lord out of the tomb, and we don’t know where they have laid him!”"
  },
  "3": {
   "zh": "彼得和那門徒就出來，往墳墓那裡去。",
   "en": "Therefore Peter and the other disciple went out, and they went toward the tomb."
  },
  "4": {
   "zh": "兩個人同跑，那門徒比彼得跑得更快，先到了墳墓，",
   "en": "They both ran together. The other disciple outran Peter, and came to the tomb first."
  },
  "5": {
   "zh": "低頭往裡看，就見細麻布還放在那裡，只是沒有進去。",
   "en": "Stooping and looking in, he saw the linen cloths lying, yet he didn’t enter in."
  },
  "6": {
   "zh": "西門•彼得隨後也到了，進墳墓裡去，就看見細麻布還放在那裡，",
   "en": "Then Simon Peter came, following him, and entered into the tomb. He saw the linen cloths lying,"
  },
  "7": {
   "zh": "又看見耶穌的裹頭巾沒有和細麻布放在一處，是另在一處捲著。",
   "en": "and the cloth that had been on his head, not lying with the linen cloths, but rolled up in a place by itself."
  },
  "8": {
   "zh": "先到墳墓的那門徒也進去，看見就信了。",
   "en": "So then the other disciple who came first to the tomb also entered in, and he saw and believed."
  },
  "9": {
   "zh": "（因為他們還不明白聖經的意思，就是耶穌必要從死裡復活。）",
   "en": "For as yet they didn’t know the Scripture, that he must rise from the dead."
  },
  "10": {
   "zh": "於是兩個門徒回自己的住處去了。",
   "en": "So the disciples went away again to their own homes."
  },
  "11": {
   "zh": "馬利亞卻站在墳墓外面哭。哭的時候，低頭往墳墓裡看，",
   "en": "But Mary was standing outside at the tomb weeping. So, as she wept, she stooped and looked into the tomb,"
  },
  "12": {
   "zh": "就見兩個天使，穿著白衣，在安放耶穌身體的地方坐著，一個在頭，一個在腳。",
   "en": "and she saw two angels in white sitting, one at the head, and one at the feet, where the body of Jesus had lain."
  },
  "13": {
   "zh": "天使對她說：「婦人，你為甚麼哭？」她說：「因為有人把我主挪了去，我不知道放在那裡。」",
   "en": "They told her, “Woman, why are you weeping?” She said to them, “Because they have taken away my Lord, and I don’t know where they have laid him.”"
  },
  "14": {
   "zh": "說了這話，就轉過身來，看見耶穌站在那裡，卻不知道是耶穌。",
   "en": "When she had said this, she turned around and saw Jesus standing, and didn’t know that it was Jesus."
  },
  "15": {
   "zh": "耶穌問她說：「婦人，為甚麼哭？你找誰呢？」馬利亞以為是看園的，就對他說：「先生，若是你把他移了去，請告訴我，你把他放在哪裡，我便去取他。」",
   "en": "Jesus said to her, “Woman, why are you weeping? Who are you looking for?” She, supposing him to be the gardener, said to him, “Sir, if you have carried him away, tell me where you have laid him, and I will take him away.”"
  },
  "16": {
   "zh": "耶穌說：「馬利亞。」馬利亞就轉過來，用希伯來話對他說：「拉波尼！」（拉波尼就是夫子的意思。）",
   "en": "Jesus said to her, “Mary.” She turned and said to him, “Rabboni!” which is to say, “Teacher!”"
  },
  "17": {
   "zh": "耶穌說：「不要摸我，因我還沒有升上去見我的父。你往我弟兄那裡去，告訴他們說，我要升上去見我的父，也是你們的父，見我的神，也是你們的神。」",
   "en": "Jesus said to her, “Don’t hold me, for I haven’t yet ascended to my Father; but go to my brothers, and tell them, ‘I am ascending to my Father and your Father, to my God and your God.’”"
  },
  "18": {
   "zh": "抹大拉的馬利亞就去告訴門徒說：「我已經看見了主。」她又將主對她說的這話告訴他們。",
   "en": "Mary Magdalene came and told the disciples that she had seen the Lord, and that he had said these things to her."
  },
  "19": {
   "zh": "那日（就是七日的第一日）晚上，門徒所在的地方，因怕猶太人，門都關了。耶穌來，站在當中，對他們說：「願你們平安！」",
   "en": "When therefore it was evening, on that day, the first day of the week, and when the doors were locked where the disciples were assembled, for fear of the Jews, Jesus came and stood in the middle, and said to them, “Peace be to you.”"
  },
  "20": {
   "zh": "說了這話，就把手和肋旁指給他們看。門徒看見主，就喜樂了。",
   "en": "When he had said this, he showed them his hands and his side. The disciples therefore were glad when they saw the Lord."
  },
  "21": {
   "zh": "耶穌又對他們說：「願你們平安！父怎樣差遣了我，我也照樣差遣你們。」",
   "en": "Jesus therefore said to them again, “Peace be to you. As the Father has sent me, even so I send you.”"
  },
  "22": {
   "zh": "說了這話，就向他們吹一口氣，說：「你們受聖靈！",
   "en": "When he had said this, he breathed on them, and said to them, “Receive the Holy Spirit!"
  },
  "23": {
   "zh": "你們赦免誰的罪，誰的罪就赦免了；你們留下誰的罪，誰的罪就留下了。」",
   "en": "If you forgive anyone’s sins, they have been forgiven them. If you retain anyone’s sins, they have been retained.”"
  },
  "24": {
   "zh": "那十二個門徒中，有稱為低土馬的多馬；耶穌來的時候，他沒有和他們同在。",
   "en": "But Thomas, one of the twelve, called Didymus, wasn’t with them when Jesus came."
  },
  "25": {
   "zh": "那些門徒就對他說：「我們已經看見主了。」多馬卻說：「我非看見他手上的釘痕，用指頭探入那釘痕，又用手探入他的肋旁，我總不信。」",
   "en": "The other disciples therefore said to him, “We have seen the Lord!” But he said to them, “Unless I see in his hands the print of the nails, put my finger into the print of the nails, and put my hand into his side, I will not believe.”"
  },
  "26": {
   "zh": "過了八日，門徒又在屋裡，多馬也和他們同在，門都關了。耶穌來，站在當中說：「願你們平安！」",
   "en": "After eight days again his disciples were inside, and Thomas was with them. Jesus came, the doors being locked, and stood in the middle, and said, “Peace be to you.”"
  },
  "27": {
   "zh": "就對多馬說：「伸過你的指頭來，摸（原文是看）我的手；伸出你的手來，探入我的肋旁。不要疑惑，總要信！」",
   "en": "Then he said to Thomas, “Reach here your finger, and see my hands. Reach here your hand, and put it into my side. Don’t be unbelieving, but believing.”"
  },
  "28": {
   "zh": "多馬說：「我的主！我的神！」",
   "en": "Thomas answered him, “My Lord and my God!”"
  },
  "29": {
   "zh": "耶穌對他說：「你因看見了我才信；那沒有看見就信的有福了。」",
   "en": "Jesus said to him, “Because you have seen me, you have believed. Blessed are those who have not seen, and have believed.”"
  },
  "30": {
   "zh": "耶穌在門徒面前另外行了許多神蹟，沒有記在這書上。",
   "en": "Therefore Jesus did many other signs in the presence of his disciples, which are not written in this book;"
  },
  "31": {
   "zh": "但記這些事要叫你們信耶穌是基督，是神的兒子，並且叫你們信了他，就可以因他的名得生命。",
   "en": "but these are written, that you may believe that Jesus is the Christ, the Son of God, and that believing you may have life in his name."
  }
 },
 "21": {
  "1": {
   "zh": "這些事以後，耶穌在提比哩亞海邊又向門徒顯現。他怎樣顯現記在下面：",
   "en": "After these things, Jesus revealed himself again to the disciples at the sea of Tiberias. He revealed himself this way."
  },
  "2": {
   "zh": "有西門•彼得和稱為低土馬的多馬，並加利利的迦拿人拿但業，還有西庇太的兩個兒子，又有兩個門徒，都在一處。",
   "en": "Simon Peter, Thomas called Didymus, Nathanael of Cana in Galilee, and the sons of Zebedee, and two others of his disciples were together."
  },
  "3": {
   "zh": "西門•彼得對他們說：「我打魚去。」他們說：「我們也和你同去。」他們就出去，上了船；那一夜並沒有打著甚麼。",
   "en": "Simon Peter said to them, “I’m going fishing.” They told him, “We are also coming with you.” They immediately went out, and entered into the boat. That night, they caught nothing."
  },
  "4": {
   "zh": "天將亮的時候，耶穌站在岸上，門徒卻不知道是耶穌。",
   "en": "But when day had already come, Jesus stood on the beach, yet the disciples didn’t know that it was Jesus."
  },
  "5": {
   "zh": "耶穌就對他們說：「小子！你們有吃的沒有？」他們回答說：「沒有。」",
   "en": "Jesus therefore said to them, “Children, have you anything to eat?” They answered him, “No.”"
  },
  "6": {
   "zh": "耶穌說：「你們把網撒在船的右邊，就必得著。」他們便撒下網去，竟拉不上來了，因為魚甚多。",
   "en": "He said to them, “Cast the net on the right side of the boat, and you will find some.” They cast it therefore, and now they weren’t able to draw it in for the multitude of fish."
  },
  "7": {
   "zh": "耶穌所愛的那門徒對彼得說：「是主！」那時西門•彼得赤著身子，一聽見是主，就束上一件外衣，跳在海裡。",
   "en": "That disciple therefore whom Jesus loved said to Peter, “It’s the Lord!” So when Simon Peter heard that it was the Lord, he wrapped his coat around him (for he was naked), and threw himself into the sea."
  },
  "8": {
   "zh": "其餘的門徒離岸不遠，約有二百肘（古時以肘為尺，一肘約有今時尺半），就在小船上把那網魚拉過來。",
   "en": "But the other disciples came in the little boat (for they were not far from the land, but about two hundred cubits away), dragging the net full of fish."
  },
  "9": {
   "zh": "他們上了岸，就看見那裡有炭火，上面有魚，又有餅。",
   "en": "So when they got out on the land, they saw a fire of coals there, and fish laid on it, and bread."
  },
  "10": {
   "zh": "耶穌對他們說：「把剛才打的魚拿幾條來。」",
   "en": "Jesus said to them, “Bring some of the fish which you have just caught.”"
  },
  "11": {
   "zh": "西門•彼得就去（或譯：上船），把網拉到岸上。那網滿了大魚，共一百五十三條；魚雖這樣多，網卻沒有破。",
   "en": "Simon Peter went up, and drew the net to land, full of great fish, one hundred fifty-three; and even though there were so many, the net wasn’t torn."
  },
  "12": {
   "zh": "耶穌說：「你們來吃早飯。」門徒中沒有一個敢問他：「你是誰？」因為知道是主。",
   "en": "Jesus said to them, “Come and eat breakfast.” None of the disciples dared inquire of him, “Who are you?” knowing that it was the Lord."
  },
  "13": {
   "zh": "耶穌就來拿餅和魚給他們。",
   "en": "Then Jesus came and took the bread, gave it to them, and the fish likewise."
  },
  "14": {
   "zh": "耶穌從死裡復活以後，向門徒顯現，這是第三次。",
   "en": "This is now the third time that Jesus was revealed to his disciples, after he had risen from the dead."
  },
  "15": {
   "zh": "他們吃完了早飯，耶穌對西門•彼得說：「約翰（在馬太十六章十七節稱約拿）的兒子西門，你愛我比這些更深嗎？」彼得說：「主啊，是的，你知道我愛你。」耶穌對他說：「你餵養我的小羊。」",
   "en": "So when they had eaten their breakfast, Jesus said to Simon Peter, “Simon, son of Jonah, do you love me more than these?” He said to him, “Yes, Lord; you know that I have affection for you.” He said to him, “Feed my lambs.”"
  },
  "16": {
   "zh": "耶穌第二次又對他說：「約翰的兒子西門，你愛我嗎？」彼得說：「主啊，是的，你知道我愛你。」耶穌說：「你牧養我的羊。」",
   "en": "He said to him again a second time, “Simon, son of Jonah, do you love me?” He said to him, “Yes, Lord; you know that I have affection for you.” He said to him, “Tend my sheep.”"
  },
  "17": {
   "zh": "第三次對他說：「約翰的兒子西門，你愛我嗎？」彼得因為耶穌第三次對他說「你愛我嗎」，就憂愁，對耶穌說：「主啊，你是無所不知的；你知道我愛你。」耶穌說：「你餵養我的羊。",
   "en": "He said to him the third time, “Simon, son of Jonah, do you have affection for me?” Peter was grieved because he asked him the third time, “Do you have affection for me?” He said to him, “Lord, you know everything. You know that I have affection for you.” Jesus said to him, “Feed my sheep."
  },
  "18": {
   "zh": "我實實在在地告訴你，你年少的時候，自己束上帶子，隨意往來；但年老的時候，你要伸出手來，別人要把你束上，帶你到不願意去的地方。」",
   "en": "Most certainly I tell you, when you were young, you dressed yourself, and walked where you wanted to. But when you are old, you will stretch out your hands, and another will dress you, and carry you where you don’t want to go.”"
  },
  "19": {
   "zh": "（耶穌說這話是指著彼得要怎樣死，榮耀神。）說了這話，就對他說：「你跟從我吧！」",
   "en": "Now he said this, signifying by what kind of death he would glorify God. When he had said this, he said to him, “Follow me.”"
  },
  "20": {
   "zh": "彼得轉過來，看見耶穌所愛的那門徒跟著，（就是在晚飯的時候，靠著耶穌胸膛說：「主啊，賣你的是誰？」的那門徒。）",
   "en": "Then Peter, turning around, saw a disciple following. This was the disciple whom Jesus loved, the one who had also leaned on Jesus’ breast at the supper and asked, “Lord, who is going to betray You?”"
  },
  "21": {
   "zh": "彼得看見他，就問耶穌說：「主啊，這人將來如何？」",
   "en": "Peter seeing him, said to Jesus, “Lord, what about this man?”"
  },
  "22": {
   "zh": "耶穌對他說：「我若要他等到我來的時候，與你何干？你跟從我吧！」",
   "en": "Jesus said to him, “If I desire that he stay until I come, what is that to you? You follow me.”"
  },
  "23": {
   "zh": "於是這話傳在弟兄中間，說那門徒不死。其實，耶穌不是說他不死，乃是說：「我若要他等到我來的時候，與你何干？」",
   "en": "This saying therefore went out among the brothers, that this disciple wouldn’t die. Yet Jesus didn’t say to him that he wouldn’t die, but, “If I desire that he stay until I come, what is that to you?”"
  },
  "24": {
   "zh": "為這些事作見證，並且記載這些事的就是這門徒；我們也知道他的見證是真的。",
   "en": "This is the disciple who testifies about these things, and wrote these things. We know that his witness is true."
  },
  "25": {
   "zh": "耶穌所行的事還有許多，若是一一地都寫出來，我想，所寫的書就是世界也容不下了。",
   "en": "There are also many other things which Jesus did, which if they would all be written, I suppose that even the world itself wouldn’t have room for the books that would be written."
  }
 }
};
